import sys, os, re, json, html as htmlmod, unicodedata, textwrap, math
from html.parser import HTMLParser

VERSION="3.9.0.2"
API_VERSION=[1,23,1,2]
PROG=os.path.basename(sys.argv[0]) if sys.argv else "pandoc"

def get_prog():
    return os.path.basename(sys.argv[0]) or "pandoc"

def user_data_dir():
    x=os.environ.get("XDG_DATA_HOME")
    if x:
        return os.path.join(x,"pandoc")
    home=os.path.expanduser("~")
    return os.path.join(home,".local","share","pandoc")

# ---------------- AST helpers ----------------
def B(t,c=None):
    if c is None:
        return {"t":t}
    return {"t":t,"c":c}
def I(t,c=None):
    if c is None:
        return {"t":t}
    return {"t":t,"c":c}
EMPTY_ATTR=["",[],[]]
def clone_attr(a):
    return [a[0], list(a[1]), [list(x) for x in a[2]]]

def parse_attr_block(s):
    # s inside {}  e.g. #id .class key=value key="v a"  or bare: python
    s=s.strip()
    ident=""
    classes=[]
    kvs=[]
    # tokenise respecting quotes
    tokens=[]
    i=0
    while i<len(s):
        while i<len(s) and s[i].isspace(): i+=1
        if i>=len(s): break
        start=i
        q=None
        while i<len(s):
            ch=s[i]
            if q:
                if ch==q: q=None
            elif ch in "\"'":
                q=ch
            elif ch.isspace():
                break
            i+=1
        tokens.append(s[start:i])
    for tok in tokens:
        if tok.startswith("#"):
            ident=tok[1:]
        elif tok.startswith("."):
            if tok[1:]: classes.append(tok[1:])
        elif "=" in tok:
            k,v=tok.split("=",1)
            v=v.strip()
            if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
                v=v[1:-1]
            kvs.append([k,v])
        else:
            # bare word = class (for fenced code info like {.python} handled elsewhere; here treat as class)
            classes.append(tok)
    return [ident,classes,kvs]

def attr_from_info(info):
    info=info.strip()
    if not info:
        return clone_attr(EMPTY_ATTR)
    if info.startswith("{") and info.endswith("}"):
        return parse_attr_block(info[1:-1])
    # words: first is language/class, rest classes? pandoc: ```python {.x} ???
    parts=info.split()
    classes=[]
    ident=""; kvs=[]
    for p in parts:
        if p.startswith("{"):
            return parse_attr_block(info[info.find("{")+1:info.rfind("}")])
        classes.append(p)
    return [ident,classes,kvs]

def inline_text(inlines):
    # plain text extraction
    out=[]
    for n in inlines or []:
        t=n.get("t"); c=n.get("c")
        if t=="Str": out.append(c)
        elif t=="Space": out.append(" ")
        elif t=="SoftBreak": out.append(" ")
        elif t=="LineBreak": out.append("\n")
        elif t in ("Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline","Span"):
            out.append(inline_text(c[1] if t=="Span" else c))
        elif t=="Quoted": out.append(inline_text(c[1]))
        elif t=="Code": out.append(c[1])
        elif t=="Math": out.append(c[1])
        elif t=="Link": out.append(inline_text(c[1]))
        elif t=="Image": out.append(inline_text(c[1]))
        elif t=="RawInline": out.append(c[1])
        elif t=="Note": out.append("")
        elif t=="Cite": out.append(inline_text(c[1]))
        else:
            if isinstance(c,list):
                # try
                pass
    return "".join(out)

def block_plain_text(blocks):
    out=[]
    for b in blocks or []:
        t=b.get("t"); c=b.get("c")
        if t in ("Para","Plain"): out.append(inline_text(c))
        elif t=="Header": out.append(inline_text(c[2]))
        elif t=="CodeBlock": out.append(c[1])
        elif t in ("BulletList",):
            for item in c:
                out.append(block_plain_text(item))
        elif t=="OrderedList":
            for item in c[1]:
                out.append(block_plain_text(item))
        elif t=="BlockQuote": out.append(block_plain_text(c))
        elif t=="Div": out.append(block_plain_text(c[1]))
        elif t=="RawBlock": out.append(c[1])
        elif t=="LineBlock":
            for line in c: out.append(inline_text(line))
    return " ".join([x for x in out if x])

_id_counter={}
def generate_identifier(text, fmt_base="markdown"):
    # reset per document handled by caller resetting global
    orig=text
    # pandoc: strip, lowercase
    s=text.strip().lower()
    # replace spaces with -
    # remove punctuation etc.
    # First, split? Algorithm: filter chars: alphanumeric, _, -, ., space
    res=[]
    for ch in s:
        if ch.isspace():
            res.append("-")
        elif ch.isalnum() or ch in "_-.":
            res.append(ch)
        # else drop
    s="".join(res)
    # remove leading non-letter
    idx=0
    while idx<len(s) and not s[idx].isalpha():
        idx+=1
    s=s[idx:]
    if not s:
        s="section"
    # gfm differences minimal
    if s not in _id_counter:
        _id_counter[s]=0
        return s
    else:
        _id_counter[s]+=1
        return f"{s}-{_id_counter[s]}"

def reset_identifiers():
    global _id_counter
    _id_counter={}

# smart helpers
# ---------------- Inline parser ----------------
class InlineParser:
    def __init__(self, refs=None, footnotes=None, options=None):
        self.refs=refs or {}  # normalized label -> (url,title)
        self.footnotes=footnotes or {}  # label -> blocks (raw string lines or blocks) ; handled via callback parse_blocks
        self.options=options or {}
        self.smart=self.options.get("smart", True)
        self.raw_html=self.options.get("raw_html", True)
        self.tex_math_dollars=self.options.get("tex_math_dollars", True)
        self.footnote_blocks={}  # label -> blocks parsed lazily by external
        # footnote order handled in writer? pandoc assigns note content, writer numbers by appearance
    def normalize_label(self,s):
        return " ".join(s.strip().lower().split())
    def parse(self, text):
        # returns inlines
        return self.parse_inlines(text, allow_link=True)
    def flush_text(self, buf, out):
        if not buf:
            return
        s="".join(buf)
        buf.clear()
        # s may contain spaces/newlines . Split preserving.
        # Smart transformations are handled before? We do them in tokenization loop for dashes etc? Simpler: process here for ... -- ---
        # But Quoted nodes already handled at parse level, so remaining text: apply smart dash/ellipsis and apostrophe
        if self.smart:
            s=self.apply_smart_text(s)
        # split by whitespace / newline markers: we encoded softbreak as \n , hard as \x00 ?
        # We'll tokenize:
        i=0
        # Use regex to split keeping separators
        parts=re.split(r'(\s+)', s)
        for part in parts:
            if part=="":
                continue
            if part.isspace():
                # if contains newline -> SoftBreak (single) unless multiple? para single lines
                if "\n" in part:
                    # count? preserve as SoftBreak
                    out.append(I("SoftBreak"))
                else:
                    out.append(I("Space"))
            else:
                # part may contain \x00 linebreak marker handled outside
                out.append(I("Str", part))
    def apply_smart_text(self,s):
        # ellipsis, dashes, apostrophe
        # Order: --- then -- then ...
        s=s.replace("...", "…")
        s=s.replace("---", "—")
        s=s.replace("--", "–")
        # apostrophe: letter'letter or trailing ' after letter? convert ' to ’ when between alphanumeric or after letter and before ... Simple: replace ' preceded by alphanum
        # We'll convert single quote char that is apostrophe: alphanum' or ' at word internal
        s=re.sub(r"(?<=[A-Za-z0-9])'(?=[A-Za-z0-9])", "’", s)
        s=re.sub(r"(?<=[A-Za-z0-9])'(?=\s|$)", "’", s)  # dogs' -> dogs’
        # also 'tis handled as Quoted? pandoc treated 'tis as quoted... hmm leave
        return s
    def parse_inlines(self, text, allow_link=True):
        out=[]
        buf=[]
        i=0
        n=len(text)
        def flush():
            self.flush_text(buf,out)
        while i<n:
            ch=text[i]
            # newline handling for hard break: two spaces before newline or backslash newline handled below
            if ch=="\n":
                # check preceding spaces in buf? Hard break already detected when spaces before? Look back in original: if i>=2 and text[i-2:i]=="  " ?? but buf may contain spaces trimmed?
                # Determine: if preceding two chars are spaces (in text) -> LineBreak
                if i>=2 and text[i-2:i]=="  ":
                    # remove trailing spaces from out/buf
                    # flush but strip trailing spaces
                    # Simplify: remove spaces from buf tail
                    s="".join(buf).rstrip(" ")
                    buf.clear(); buf.append(s) if s else None
                    flush()
                    out.append(I("LineBreak"))
                    i+=1
                    continue
                else:
                    buf.append("\n")
                    i+=1
                    continue
            # escaped char
            if ch=="\\" and i+1<n:
                nxt=text[i+1]
                if nxt=="\n":
                    flush()
                    out.append(I("LineBreak"))
                    i+=2
                    continue
                elif nxt in r"""!"#$%&'()*+,-./:;<=>?@[\]^_`{|}~""":
                    buf.append(nxt)
                    i+=2
                    continue
                else:
                    buf.append(ch)
                    i+=1
                    continue
            # code span
            if ch=="`":
                # count run
                j=i
                while j<n and text[j]=="`": j+=1
                run=j-i
                # ``` in inline paragraph? treat as code span run
                # find closing run of same length
                delim="`"*run
                k=text.find(delim, j)
                if k!=-1:
                    content=text[j:k]
                    # also ensure closing run not part of longer? simplified
                    content=content.replace("\n"," ")
                    if len(content)>=2 and content[0]==" " and content[-1]==" " and content.strip()!="":
                        content=content[1:-1]
                    flush()
                    attr=clone_attr(EMPTY_ATTR)
                    end=k+run
                    # attribute block following
                    if end<n and text[end]=="{":
                        e=text.find("}",end)
                        if e!=-1:
                            inner=text[end+1:e]
                            # only if looks like attr (starts . # or contains = or word?)
                            attr=parse_attr_block(inner)
                            end=e+1
                    out.append(I("Code",[attr,content]))
                    i=end
                    continue
                else:
                    # unmatched: if smart and `` ? just literal `
                    buf.append(ch)
                    i+=1
                    continue
            # math
            if ch=="$" and self.tex_math_dollars:
                # $$ display
                if text.startswith("$$",i):
                    k=text.find("$$",i+2)
                    if k!=-1:
                        content=text[i+2:k]
                        flush()
                        out.append(I("Math",["DisplayMath",content.strip()]))
                        i=k+2
                        continue
                else:
                    # inline $...$ : opening not followed by space, closing not preceded...
                    if i+1<n and not text[i+1].isspace():
                        k=text.find("$",i+1)
                        if k!=-1 and k>i+1 and not text[k-1].isspace():
                            content=text[i+1:k]
                            if "\n\n" not in content:
                                flush()
                                out.append(I("Math",["InlineMath",content]))
                                i=k+1
                                continue
                    buf.append(ch); i+=1; continue
            if ch=="\\" and text.startswith("\\(",i):
                k=text.find("\\)",i+2)
                if k!=-1 and self.options.get("tex_math_single_backslash",False):
                    flush(); out.append(I("Math",["InlineMath",text[i+2:k]])); i=k+2; continue
            # footnote ref / link / image
            if ch=="!" and i+1<n and text[i+1]=="[" and allow_link:
                res=self.try_link(text,i+1,is_image=True)
                if res:
                    node,end=res
                    flush(); out.append(node); i=end; continue
                else:
                    buf.append(ch); i+=1; continue
            if ch=="[" and allow_link:
                # footnote
                if text.startswith("[^",i):
