def roman_to_int(s):
    vals={'i':1,'v':5,'x':10,'l':50,'c':100,'d':500,'m':1000}
    s=s.lower(); total=0; prev=0
    for ch in reversed(s):
        v=vals.get(ch,0)
        if v<prev: total-=v
        else: total+=v; prev=v
    return total
def int_to_roman(n):
    table=[(1000,'m'),(900,'cm'),(500,'d'),(400,'cd'),(100,'c'),(90,'xc'),(50,'l'),(40,'xl'),(10,'x'),(9,'ix'),(5,'v'),(4,'iv'),(1,'i')]
    res=""
    for v,s in table:
        while n>=v: res+=s; n-=v
    return res

