def parse_html_attrs_to_attr(s):
    # s like ' class="warning" id="x" key="v"'
    ident=""; classes=[]; kvs=[]
    for m in re.finditer(r'([A-Za-z_:][\w:.-]*)(?:\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+))?', s):
        name=m.group(1); val=m.group(2)
        if val and len(val)>=2 and val[0] in "\"'": val=val[1:-1]
        if name=="id": ident=val or ""
        elif name=="class": classes.extend((val or "").split())
        else: kvs.append([name,val or ""])
    return [ident,classes,kvs]

def default_format_options(fmt):
    base=fmt.split("+")[0].split("-")[0].lower() if fmt else "markdown"
    # defaults roughly pandoc markdown
    opts={"fmt":base,"smart":True,"raw_html":True,"tex_math_dollars":True,"auto_identifiers":True,"strikeout":True,"subscript":True,"superscript":True,"implicit_figures":True,"markdown_in_html_blocks":True,"citations":True,"autolink_bare_uris":False,"blank_before_header":True}
    if base in ("commonmark","commonmark_x"):
        opts.update({"smart":False,"auto_identifiers": base=="commonmark_x", "strikeout": base=="commonmark_x","subscript":False,"superscript":False,"implicit_figures":False})
        if base=="commonmark":
            opts.update({"strikeout":False,"tex_math_dollars":False})
    if base=="gfm":
        opts.update({"smart":False,"autolink_bare_uris":True,"auto_identifiers":True})
    if base in ("markdown_strict",):
        opts.update({"smart":True,"auto_identifiers":False,"strikeout":False,"subscript":False,"superscript":False,"implicit_figures":False})
    if base in ("markdown_mmd",):
        opts.update({"auto_identifiers":False})
    if base=="djot":
        opts.update({"smart":False})
    # extensions modifiers +ext -ext parsed by caller
    return opts

