    def is_pipe_delimiter(self,line):
        s=line.strip()
        if "|" not in s and "-" not in s:
            return False
        # remove leading/trailing pipe
        if s.startswith("|"): s=s[1:]
        if s.endswith("|"): s=s[:-1]
        cells=s.split("|")
        for c in cells:
            if not re.match(r'^\s*:?-{1,}:?\s*$', c):
                return False
        return True
    def split_pipe_row(self,line):
        s=line.strip()
        # respect escaped \| and code? simple
        if s.startswith("|"): s=s[1:]
        if s.endswith("|") and not s.endswith("\\|"): s=s[:-1]
        cells=[]
        cur=""; i=0; in_code=False
        while i<len(s):
            ch=s[i]
            if ch=="\\" and i+1<len(s) and s[i+1]=="|":
                cur+="|"; i+=2; continue
            if ch=="`":
                in_code=not in_code; cur+=ch; i+=1; continue
            if ch=="|" and not in_code:
                cells.append(cur.strip()); cur=""; i+=1; continue
            cur+=ch; i+=1
        cells.append(cur.strip())
        return cells
