def parse_html_attrs_to_attr(s):
    # s like ' class="warning" id="x" key="v"'
    ident=""; classes=[]; kvs=[]
    for m in re.finditer(r'([A-Za-z_:][\w:.-]*)(?:\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+))?', s):
        name=m.group(1); val=m.group(2)
