                self.i+=1; return ("list",items)
            while True:
                items.append(self.parse_value())
                self.ws()
                if self.i<self.n and self.s[self.i]==',':
                    self.i+=1; continue
                elif self.i<self.n and self.s[self.i]==']':
                    self.i+=1; break
                else: break
            return ("list",items)
        if ch=='(':
            self.i+=1
            items=[]
            self.ws()
            if self.i<self.n and self.s[self.i]==')':
                self.i+=1; return ("tuple",items)
            while True:
                items.append(self.parse_value())
                self.ws()
                if self.i<self.n and self.s[self.i]==',':
                    self.i+=1; continue
                elif self.i<self.n and self.s[self.i]==')':
                    self.i+=1; break
                else: break
            return ("tuple",items)
        if ch=='{':
            # Meta {unMeta = fromList [...] } special
            # capture balanced
            start=self.i
            depth=0
            while self.i<self.n:
                if self.s[self.i]=='{': depth+=1
                elif self.s[self.i]=='}':
                    depth-=1
                    if depth==0:
                        self.i+=1; break
                self.i+=1
            return ("brace", self.s[start:self.i])
        # atom / constructor application: read identifier/number, then following args that are atoms/lists/tuples/strings/numbers/brace or '(' not tuple? constructors args...
        # Read token
        m=re.match(r'-?[0-9]+(?:\.[0-9]+)?|[A-Za-z_][A-Za-z0-9_\']*', self.s[self.i:])
        if not m:
            # unknown char skip
            self.i+=1; return ("atom",ch)
        tok=m.group(0); self.i+=len(tok)
        # Check if this is a constructor with args: next tokens that look like start of arg ( [ ( " digit letter { ) and not ',' ']' ')' and not a following constructor that is ??? Application args are values; in Haskell show, args are atomic or parenthesized/list.
        # We parse args greedily while next token is start of a value but not a closing, and peek token is not??? How distinguish list elements separated? Inside list parser parse_value returns one application: eg Para [Str "Hi", Space] - parse_value for element: token Para, next is [ -> arg, then stops because next is ','.
        args=[]
        while True:
            save=self.i
            self.ws()
            if self.i>=self.n: break
            nxt=self.s[self.i]
            if nxt in ',])':
                break
            # If next is identifier, it could be arg like `Nothing` or `InlineMath "x"` or `1` etc. But in sequences like "[ Str \"Hi\" , Space ]", after Str "Hi", next is ',' so break. In constructor applications like "Header 1 ( ... ) [ ... ]", args are numbers/tuple/list.
            # However for nested like `MetaInlines [ Str "Me" ]`, arg is list.
            # For `(RowSpan 1)`, token RowSpan arg 1.
            # Parsing identifier as arg would incorrectly consume next element in a list like `[ Str "a" , Str "b" ]`? No commas separate.
            # But inside a tuple/list without comma? Show always uses commas.
            # In application contexts like `Caption Nothing []`, args follow.
            # So greedily parse a value as arg.
            # Guard: if tok is a simple atom like "Space" with no args expected, next identifier would be ??? But lists separate by comma, blocks by comma, so safe.
            # Only parse arg if tok is capitalised constructor or tok in known etc.
            if tok[0].isupper() or tok=="fromList":
                arg=self.parse_value()
                args.append(arg)
            else:
                self.i=save; break
        if args:
            return ("app", tok, args)
        else:
            # number?
            if re.match(r'^-?[0-9]',tok):
                try:
                    if '.' in tok: return ("num", float(tok))
                    else: return ("num", int(tok))
                except: return ("atom",tok)
            return ("atom",tok)
    def parse_string(self):
        # assume opening "
        self.i+=1; out=""
        while self.i<self.n:
            ch=self.s[self.i]
            if ch=='\\' and self.i+1<self.n:
                nxt=self.s[self.i+1]
                if nxt=='n': out+='\n'; self.i+=2
                elif nxt=='t': out+='\t'; self.i+=2
                elif nxt=='r': out+='\r'; self.i+=2
                elif nxt=='"': out+='"'; self.i+=2
                elif nxt=='\\': out+='\\'; self.i+=2
                elif nxt.isdigit():
                    # decimal escape \8212
                    m=re.match(r'\\([0-9]+)', self.s[self.i:])
                    if m:
                        out+=chr(int(m.group(1))); self.i+=len(m.group(0)); continue
                    else:
                        out+=nxt; self.i+=2
                else:
                    # \& etc ignore?
                    if nxt=='&': self.i+=2
                    else: out+=nxt; self.i+=2
                continue
            elif ch=='"':
                self.i+=1; break
            else:
                out+=ch; self.i+=1
        return out

def native_value_to_attr(v):
    # tuple (ident, [classes], [kvs])
    if isinstance(v,tuple) and v[0]=="tuple":
        items=v[1]
        ident=""
        classes=[]; kvs=[]
        if len(items)>=1 and items[0][0]=="str": ident=items[0][1]
        if len(items)>=2 and items[1][0]=="list": classes=[x[1] if x[0]=="str" else "" for x in items[1][1]]
        if len(items)>=3 and items[2][0]=="list":
            for kv in items[2][1]:
                if kv[0]=="tuple" and len(kv[1])>=2:
                    kvs.append([kv[1][0][1],kv[1][1][1]])
        return [ident,classes,kvs]
    return clone_attr(EMPTY_ATTR)

def native_value_to_inlines(v):
    if v is None: return []
    if isinstance(v,tuple) and v[0]=="list":
        return [native_value_to_inline(x) for x in v[1]]
    return []
def native_value_to_blocks(v):
    if v is None: return []
    if isinstance(v,tuple) and v[0]=="list":
        return [native_value_to_block(x) for x in v[1]]
    if isinstance(v,tuple) and v[0]=="app": # single block without list?
        return [native_value_to_block(v)]
    return []

def native_app_args(v):
    if isinstance(v,tuple) and v[0]=="app": return v[1], v[2]
    if isinstance(v,tuple) and v[0]=="atom": return v[1],[]
    return str(v),[]

def native_value_to_inline(v):
    if not isinstance(v,tuple): return I("Str",str(v))
    if v[0]=="atom":
        if v[1]=="Space": return I("Space")
        if v[1]=="SoftBreak": return I("SoftBreak")
        if v[1]=="LineBreak": return I("LineBreak")
        return I("Str",v[1])
    if v[0]=="app":
        name,args=v[1],v[2]
        if name=="Str": return I("Str", args[0][1] if args and args[0][0]=="str" else "")
        if name=="Emph": return I("Emph", native_value_to_inlines(args[0]))
        if name=="Strong": return I("Strong", native_value_to_inlines(args[0]))
        if name=="Strikeout": return I("Strikeout", native_value_to_inlines(args[0]))
        if name=="Superscript": return I("Superscript", native_value_to_inlines(args[0]))
        if name=="Subscript": return I("Subscript", native_value_to_inlines(args[0]))
        if name=="SmallCaps": return I("SmallCaps", native_value_to_inlines(args[0]))
        if name=="Underline": return I("Underline", native_value_to_inlines(args[0]))
        if name=="Quoted":
            q=args[0][1] if args[0][0]=="atom" else "DoubleQuote"
            return I("Quoted",[q, native_value_to_inlines(args[1])])
        if name=="Code": return I("Code",[native_value_to_attr(args[0]), args[1][1] if len(args)>1 else ""])
        if name=="Math":
            mt=args[0][1] if args[0][0]=="atom" else "InlineMath"
            return I("Math",[mt, args[1][1] if len(args)>1 else ""])
        if name=="RawInline": return I("RawInline",[args[0][1], args[1][1]])
        if name=="Link": return I("Link",[native_value_to_attr(args[0]), native_value_to_inlines(args[1]), [args[2][1][0][1], args[2][1][1][1]] if args[2][0]=="tuple" else ["",""]])
        if name=="Image": return I("Image",[native_value_to_attr(args[0]), native_value_to_inlines(args[1]), [args[2][1][0][1], args[2][1][1][1]] if args[2][0]=="tuple" else ["",""]])
        if name=="Span": return I("Span",[native_value_to_attr(args[0]), native_value_to_inlines(args[1])])
        if name=="Note": return I("Note", native_value_to_blocks(args[0]))
        if name=="Cite": return I("Cite",[[], native_value_to_inlines(args[1]) if len(args)>1 else []])
    return I("Str","")

def native_value_to_block(v):
    if not isinstance(v,tuple): return B("Para",[])
    if v[0]=="atom":
        if v[1]=="HorizontalRule": return B("HorizontalRule")
        if v[1]=="Null": return B("Null")
        return B("Para",[])
    if v[0]=="app":
        name,args=v[1],v[2]
        if name=="Para": return B("Para", native_value_to_inlines(args[0]))
        if name=="Plain": return B("Plain", native_value_to_inlines(args[0]))
        if name=="Header": return B("Header",[args[0][1] if args[0][0]=="num" else 1, native_value_to_attr(args[1]), native_value_to_inlines(args[2])])
        if name=="CodeBlock": return B("CodeBlock",[native_value_to_attr(args[0]), args[1][1]])
        if name=="RawBlock": return B("RawBlock",[args[0][1], args[1][1]])
        if name=="BlockQuote": return B("BlockQuote", native_value_to_blocks(args[0]))
        if name=="BulletList":
            items=[]
            for it in args[0][1]:
                items.append(native_value_to_blocks(it))
            return B("BulletList",items)
        if name=="OrderedList":
            # args: tuple (start, style, delim), items
            lst_attr=[1,"Decimal","Period"]
            if args[0][0]=="tuple":
                t=args[0][1]
                lst_attr=[t[0][1] if t[0][0]=="num" else 1, t[1][1], t[2][1]]
            items=[native_value_to_blocks(it) for it in args[1][1]]
            return B("OrderedList",[lst_attr,items])
        if name=="DefinitionList":
            items=[]
            for it in args[0][1]:
                # tuple ([term], [[def blocks],...])
                if it[0]=="tuple":
                    term=native_value_to_inlines(it[1][0])
                    defs=[native_value_to_blocks(d) for d in it[1][1][1]]
                    items.append((term,defs))
            return B("DefinitionList",items)
        if name=="LineBlock":
            lines=[native_value_to_inlines(x) for x in args[0][1]]
            return B("LineBlock",lines)
        if name=="HorizontalRule": return B("HorizontalRule")
        if name=="Div": return B("Div",[native_value_to_attr(args[0]), native_value_to_blocks(args[1])])
        if name=="Figure":
            # (attr, (Caption ... ), blocks) complicated
            # approximate: extract image from blocks
            blocks=native_value_to_blocks(args[2]) if len(args)>2 else []
            caption=[None,[]]
            return B("Figure",[native_value_to_attr(args[0]), caption, blocks])
        if name=="Table":
            # difficult - return raw? Try parse using json-like conversion? Skip return Para empty
            return B("RawBlock",["native", "Table"])  # TODO improve
    # list etc
    return B("Para",[])

def parse_native(text):
    text=text.strip()
    if not text:
        return {},[]
    # Pandoc (Meta {...}) [blocks]  or just [blocks]
    parser=NativeParser(text)
    # peek token Pandoc
    parser.ws()
    meta={}
    if text.startswith("Pandoc"):
        # parse_value will do app Pandoc with args: Meta brace, list
        v=parser.parse_value()
        if v[0]=="app" and v[1]=="Pandoc":
            args=v[2]
            # meta arg is app Meta [brace] ?
            blocks=[]
            for a in args:
                if a[0]=="list":
                    blocks=native_value_to_blocks(a)
                elif a[0]=="app" and a[1]=="Meta":
                    # arg brace contains fromList list
                    # re-parse brace string inner for fromList
                    brace_str=a[2][0][1] if a[2] and a[2][0][0]=="brace" else ""
                    meta=parse_native_meta_brace(brace_str)
            return meta,blocks
    v=parser.parse_value()
    blocks=native_value_to_blocks(v)
    # native blocks conversion tables etc need handle: our native_value_to_block returns placeholder for Table - acceptable
    return meta,blocks

def parse_native_meta_brace(s):
    # s like { unMeta = fromList [("k", MetaInlines [...]), ...]}
    meta={}
    # find fromList list parsing with subparser starting at [
    idx=s.find("[")
    if idx==-1: return meta
    sub=NativeParser(s[idx:])
    v=sub.parse_value()
    if v[0]=="list":
        for item in v[1]:
            if item[0]=="tuple" and len(item[1])>=2:
                key=item[1][0][1] if item[1][0][0]=="str" else ""
                mv=native_value_to_metavalue(item[1][1])
                meta[key]=mv
    return meta

def native_value_to_metavalue(v):
    if v[0]=="app":
        name,args=v[1],v[2]
        if name=="MetaInlines": return {"t":"MetaInlines","c":native_value_to_inlines(args[0])}
        if name=="MetaString": return {"t":"MetaString","c":args[0][1]}
        if name=="MetaBool": return {"t":"MetaBool","c": args[0][1]=="True"}
        if name=="MetaList": return {"t":"MetaList","c":[native_value_to_metavalue(x) for x in args[0][1]]}
        if name=="MetaBlocks": return {"t":"MetaBlocks","c":native_value_to_blocks(args[0])}
        if name=="MetaMap":
            pairs=[]
            for it in args[0][1]:
                if it[0]=="tuple": pairs.append([it[1][0][1], native_value_to_metavalue(it[1][1])])
            return {"t":"MetaMap","c":pairs}
    if v[0]=="atom" and v[1] in ("True","False"):
        return {"t":"MetaBool","c":v[1]=="True"}
    return {"t":"MetaString","c":""}

