# ---------------- HTML reader ----------------
class HTMLToBlocks(HTMLParser):
    def __init__(self, options=None):
        super().__init__(convert_charrefs=True)
        self.options=options or default_format_options("html")
        self.blocks=[]
        self.stack=[]
        # We build a tree-ish using parser events constructing DOM
        self.root={"tag":"root","attrs":{},"children":[]}
        self.cur_stack=[self.root]
    def handle_starttag(self,tag,attrs):
        node={"tag":tag,"attrs":dict(attrs),"children":[]}
        self.cur_stack[-1]["children"].append(node)
        if tag not in ("br","hr","img","meta","link","input","col"):
            self.cur_stack.append(node)
    def handle_startendtag(self,tag,attrs):
        node={"tag":tag,"attrs":dict(attrs),"children":[]}
        self.cur_stack[-1]["children"].append(node)
    def handle_endtag(self,tag):
        # pop to matching
        for idx in range(len(self.cur_stack)-1,0,-1):
            if self.cur_stack[idx]["tag"]==tag:
                del self.cur_stack[idx:]
                break
    def handle_data(self,data):
        if data:
            self.cur_stack[-1]["children"].append({"text":data})
    def handle_comment(self,data):
        self.cur_stack[-1]["children"].append({"tag":"!comment","attrs":{},"children":[{"text":data}]})

def dom_to_blocks(children, options):
    blocks=[]
    # group inline nodes into Para/Plain
    inline_buf=[]
    def flush_para():
        if inline_buf:
            inls=trim_inlines(normalize_inlines(inline_buf[:]))
            # check if only whitespace
            if inls:
                blocks.append(B("Para",inls))
            inline_buf.clear()
    for node in children:
        if "text" in node:
            txt=node["text"]
            if txt.strip()=="":
                # whitespace between blocks - ignore if blocks context? Add space if inline_buf
                if inline_buf:
                    inline_buf.append(I("Space"))
                continue
            inline_buf.extend(InlineParser(options=options).parse(txt))
            continue
        tag=node.get("tag","")
        if tag in ("h1","h2","h3","h4","h5","h6"):
            flush_para()
            level=int(tag[1])
            attr=dom_attr(node)
            inls=dom_to_inlines(node["children"],options)
            if attr[0]=="" and options.get("auto_identifiers",True):
                # HTML headers may have id already; if none, pandoc html reader generates? earlier <h1>Hi</h1> native id "hi" yes
                attr[0]=generate_identifier(inline_text(inls))
            blocks.append(B("Header",[level,attr,inls]))
        elif tag=="p":
            flush_para()
            inls=dom_to_inlines(node["children"],options)
            inls=trim_inlines(inls)
            if inls:
                # figure check: single image
                if len(inls)==1 and inls[0].get("t")=="Image":
                    # html figure handling separate
                    blocks.append(B("Para",inls))
                else:
                    blocks.append(B("Para",inls))
        elif tag in ("div","section","article","main","header","footer"):
            flush_para()
            attr=dom_attr(node)
            inner=dom_to_blocks(node["children"],options)
            if attr[0] or attr[1] or attr[2]:
                blocks.append(B("Div",[attr,inner]))
            else:
                # plain div without attr: pandoc native_divs: Div with empty attr
                if options.get("fmt")=="html":
                    blocks.append(B("Div",[attr,inner]))
                else:
                    blocks.extend(inner)
        elif tag=="figure":
            flush_para()
            inner=dom_to_blocks(node["children"],options)
            # extract caption
            # simplify: Div? Pandoc Figure: find figcaption
            cap_inls=[]
            fig_blocks=[]
            for ch in node["children"]:
                if isinstance(ch,dict) and ch.get("tag")=="figcaption":
                    cap_inls=dom_to_inlines(ch["children"],options)
                elif isinstance(ch,dict) and ch.get("tag")=="img":
                    fig_blocks.append(B("Plain",[dom_img(ch,options)]))
            if fig_blocks:
                blocks.append(B("Figure",[clone_attr(EMPTY_ATTR),[None,[B("Plain",cap_inls)] if cap_inls else []],fig_blocks]))
            else:
                blocks.extend(inner)
        elif tag=="figcaption":
            continue
        elif tag=="blockquote":
            flush_para()
            inner=dom_to_blocks(node["children"],options)
            blocks.append(B("BlockQuote",inner))
        elif tag in ("ul","ol"):
            flush_para()
            blocks.append(dom_list(node,options))
        elif tag=="dl":
            flush_para()
            blocks.append(dom_dl(node,options))
        elif tag=="pre":
            flush_para()
            text=dom_text(node)
            # check code child class
            attr=clone_attr(EMPTY_ATTR)
            # find code
            # classes on pre/code
            code_text=text
            if code_text.endswith("\n"): code_text=code_text[:-1]
            blocks.append(B("CodeBlock",[attr,code_text]))
        elif tag=="table":
            flush_para()
            tbl=dom_table(node,options)
            if tbl: blocks.append(tbl)
        elif tag=="hr":
            flush_para(); blocks.append(B("HorizontalRule"))
        elif tag in ("header","footer","nav"):
            flush_para(); blocks.extend(dom_to_blocks(node["children"],options))
        elif tag in ("html","body"):
            flush_para(); blocks.extend(dom_to_blocks(node["children"],options))
        elif tag=="head":
            continue
        elif tag in ("script","style"):
            continue
        elif tag=="!comment":
            flush_para(); blocks.append(B("RawBlock",["html",f"<!--{node['children'][0]['text'] if node['children'] else ''}-->"]))
        elif tag in ("span","em","strong","a","code","i","b","sub","sup","del","s","small","mark","abbr","q","cite","u","img","br"):
            inline_buf.extend(dom_node_to_inlines(node,options))
        else:
            # unknown block: treat children as blocks
            flush_para(); blocks.extend(dom_to_blocks(node["children"],options))
    flush_para()
    return blocks

def dom_attr(node):
    attrs=node.get("attrs",{})
    ident=attrs.get("id","") or ""
    classes=(attrs.get("class","") or "").split()
    kvs=[]
    for k,v in attrs.items():
        if k in ("id","class"): continue
        kvs.append([k, v if v is not None else ""])
    return [ident,classes,kvs]

def dom_text(node):
    out=[]
    if "text" in node: return node["text"]
    for ch in node.get("children",[]):
        out.append(dom_text(ch))
    return "".join(out)

def dom_img(node,options):
    attrs=node.get("attrs",{})
    src=attrs.get("src","") or ""
    title=attrs.get("title","") or ""
    alt=attrs.get("alt","") or ""
    attr=dom_attr(node)
    # remove src/title/alt from kvs
    attr[2]=[kv for kv in attr[2] if kv[0] not in ("src","title","alt")]
    inls=InlineParser(options=options).parse(alt) if alt else []
    return I("Image",[attr,inls,[src,title]])

def dom_node_to_inlines(node,options):
    tag=node.get("tag","")
    if "text" in node:
        return InlineParser(options=options).parse(node["text"])
    inner=[]
    for ch in node.get("children",[]):
        inner.extend(dom_node_to_inlines(ch,options) if isinstance(ch,dict) else [])
    # trim?
    if tag in ("em","i"):
        return [I("Emph",inner)]
    if tag in ("strong","b"):
        return [I("Strong",inner)]
    if tag=="code":
        attr=dom_attr(node)
        # classes language- ?
        return [I("Code",[attr, dom_text(node)])]
    if tag=="a":
        href=node["attrs"].get("href","") or ""
        title=node["attrs"].get("title","") or ""
        attr=dom_attr(node); attr[2]=[kv for kv in attr[2] if kv[0] not in ("href","title")]
        return [I("Link",[attr,inner,[href,title]])]
    if tag=="img":
        return [dom_img(node,options)]
    if tag=="br":
        return [I("LineBreak")]
    if tag=="sub": return [I("Subscript",inner)]
    if tag=="sup": return [I("Superscript",inner)]
    if tag in ("del","s"): return [I("Strikeout",inner)]
    if tag=="small": return [I("SmallCaps",inner)]
    if tag=="q": return [I("Quoted",["DoubleQuote",inner])]
    if tag=="span":
        attr=dom_attr(node)
        if attr[0] or attr[1] or attr[2]:
            return [I("Span",[attr,inner])]
        else:
            return inner
    if tag=="u": return [I("Underline",inner)]
    # others return inner
    return inner

def dom_to_inlines(children,options):
    out=[]
    for ch in children:
        if "text" in ch:
            out.extend(InlineParser(options=options).parse(ch["text"]))
        else:
            out.extend(dom_node_to_inlines(ch,options))
    return trim_inlines(normalize_inlines(out))

def dom_list(node,options):
    is_ordered=node["tag"]=="ol"
    items=[]
    for ch in node.get("children",[]):
        if isinstance(ch,dict) and ch.get("tag")=="li":
            bl=dom_to_blocks(ch["children"],options)
            # if single Para, make Plain for tight? HTML reader: li content ... pandoc: <ul><li>a</li></ul> native gave Plain. If li contained <p>, gives Para.
            # Determine: if original li had p tag, blocks already Para; if text directly, dom_to_blocks will make Para -- convert Para to Plain if li no p?
            has_p=any(isinstance(x,dict) and x.get("tag")=="p" for x in ch["children"])
            if not has_p:
                conv=[]
                for b in bl:
                    if b["t"]=="Para": conv.append(B("Plain",b["c"]))
                    else: conv.append(b)
                bl=conv
            items.append(bl)
    if is_ordered:
        attrs=node.get("attrs",{})
        start=int(attrs.get("start","1") or "1") if (attrs.get("start") or "1").isdigit() else 1
        typ=attrs.get("type","1")
        style_map={"1":"Decimal","a":"LowerAlpha","A":"UpperAlpha","i":"LowerRoman","I":"UpperRoman"}
        style=style_map.get(typ,"Decimal")
        return B("OrderedList",[[start,style,"Period"],items])
    else:
        return B("BulletList",items)

def dom_dl(node,options):
    items=[]; term=None; defs=[]
    for ch in node.get("children",[]):
        if not isinstance(ch,dict): continue
        if ch.get("tag")=="dt":
            if term is not None:
                items.append((term,defs))
            term=dom_to_inlines(ch["children"],options); defs=[]
        elif ch.get("tag")=="dd":
            bl=dom_to_blocks(ch["children"],options)
            conv=[]
            for b in bl:
                if b["t"]=="Para": conv.append(B("Plain",b["c"]))
                else: conv.append(b)
            defs.append(conv)
    if term is not None:
        items.append((term,defs))
    return B("DefinitionList",items)

def dom_table(node,options):
    # extract caption, thead, tbody
    caption=[]; header=[]; rows=[]; aligns=[]
    def rows_from_section(sec):
        rs=[]
        for tr in sec.get("children",[]):
            if not (isinstance(tr,dict) and tr.get("tag")=="tr"): continue
            row=[]
            for cell in tr.get("children",[]):
                if isinstance(cell,dict) and cell.get("tag") in ("th","td"):
                    inls=dom_to_inlines(cell["children"],options)
                    row.append(inline_text(inls))
                    # store inlines later
                    row[-1]=inls  # will handle
            rs.append(row)
        return rs
    header_inlines=[]; row_inlines=[]; header_cells=[]; row_cells=[]
    for ch in node.get("children",[]):
        if not isinstance(ch,dict): continue
        if ch.get("tag")=="caption":
            caption=[B("Plain",dom_to_inlines(ch["children"],options))]
        elif ch.get("tag")=="thead":
            for tr in ch["children"]:
                if isinstance(tr,dict) and tr.get("tag")=="tr":
                    row=[]
                    for cell in tr["children"]:
                        if isinstance(cell,dict) and cell.get("tag") in ("th","td"):
                            inls=dom_to_inlines(cell["children"],options); row.append(inls)
                            aligns.append("AlignDefault")
                    header_inlines.append(row)  # only first?
            if header_inlines: header_inlines=header_inlines[0]
        elif ch.get("tag") in ("tbody","tfoot"):
            for tr in ch["children"]:
                if isinstance(tr,dict) and tr.get("tag")=="tr":
                    row=[]
                    for cell in tr["children"]:
                        if isinstance(cell,dict) and cell.get("tag") in ("th","td"):
                            row.append(dom_to_inlines(cell["children"],options))
                    row_inlines.append(row)
        elif ch.get("tag")=="tr":
            row=[]
            for cell in ch["children"]:
                if isinstance(cell,dict) and cell.get("tag") in ("th","td"):
                    row.append(dom_to_inlines(cell["children"],options))
            # decide header if th
            if any(isinstance(c,dict) and c.get("tag")=="th" for c in ch["children"]):
                header_inlines=row
            else:
                row_inlines.append(row)
    if not header_inlines and row_inlines:
        header_inlines=row_inlines.pop(0)
    ncol=len(header_inlines) if header_inlines else (len(row_inlines[0]) if row_inlines else 0)
    aligns=(aligns+["AlignDefault"]*ncol)[:ncol] if ncol else []
    # build table custom
    parser_stub=type("obj",(),{"inline":lambda self,t: []})()
    tbl={"t":"Table","c":{"attr":clone_attr(EMPTY_ATTR),"caption":caption,"aligns":aligns,"widths":[None]*ncol,"header":[inline_text(x) for x in header_inlines],"rows":[[inline_text(c) for c in r] for r in row_inlines],"header_inlines":header_inlines,"row_inlines":row_inlines}}
    return tbl

def parse_html_to_blocks(text, options=None):
    if options is None: options=default_format_options("html")
    parser=HTMLToBlocks(options)
    try:
        parser.feed(text)
    except Exception:
        return None
    root=parser.root
    # if root children are html/body etc dom_to_blocks handles
    blocks=dom_to_blocks(root["children"],options)
    return blocks

# ---------------- JSON / Native readers ----------------
def doc_from_json(obj):
    meta={}
    blocks=[]
    if isinstance(obj,dict):
        meta_json=obj.get("meta",{})
        for k,v in meta_json.items():
            meta[k]=v  # already pandoc json meta value with t/c
        blocks=obj.get("blocks",[])
        # Table conversion: pandoc json Table nodes need convert to internal custom
        blocks=[convert_json_block(b) for b in blocks]
    return meta,blocks

def convert_json_block(b):
    if not isinstance(b,dict): return b
    t=b.get("t")
    if t=="Table":
        # c: [attr, caption, colspecs, head, bodies, foot] where caption [short, blocks], colspecs [[align, width]...]
        c=b["c"]
        try:
            attr=c[0]; caption=c[1][1] if len(c[1])>1 else []
            colspecs=c[2]; aligns=[]
            widths=[]
            for align,width in colspecs:
                aligns.append(align.get("t","AlignDefault") if isinstance(align,dict) else str(align))
                if isinstance(width,dict):
                    widths.append(width.get("c") if width.get("t")=="ColWidth" else None)
                else: widths.append(None)
            head=c[3]; bodies=c[4]
            header_inlines=[]
            if head and len(head)>1 and head[1]:
                row=head[1][0]
                for cell in row["c"] if "c" in row else row[1] if isinstance(row,list) else []:
                    pass
            # Use helper to extract inlines from cell structure generically below
            def cell_inlines(cell):
                # cell json: {"t":"Cell","c":[attr,align,rowspan,colspan,blocks]}
                bl=cell.get("c",[])[4] if len(cell.get("c",[]))>4 else []
                # blocks may be Plain/Para
                inls=[]
                for blk in bl:
                    if blk.get("t") in ("Plain","Para"):
                        inls.extend(blk.get("c",[]))
                    else:
                        inls.append(I("Str",block_plain_text([blk])))
                return inls
            def row_inlines(row):
                cells=row.get("c",[])[1] if len(row.get("c",[]))>1 else []
                return [cell_inlines(cell) for cell in cells]
            if head and head[1]:
                header_inlines=row_inlines(head[1][0])
            row_inlines_list=[]
            for body in bodies:
                # body: [attr, rowheadcols, headrows, bodyrows]
                for row in body[3] if len(body)>3 else []:
                    row_inlines_list.append(row_inlines(row))
            return {"t":"Table","c":{"attr":attr,"caption":caption,"aligns":aligns,"widths":widths,"header":[inline_text(x) for x in header_inlines],"rows":[[inline_text(c) for c in r] for r in row_inlines_list],"header_inlines":header_inlines,"row_inlines":row_inlines_list}}
        except Exception as e:
            return b
    # recursively convert nested tables in blocks/inlines? For Div, BlockQuote, lists etc, need conversion inside.
    # Walk json structure converting any Table dict encountered
    return convert_tables_in_obj(b)

def convert_tables_in_obj(o):
    if isinstance(o,dict):
        if o.get("t")=="Table" and isinstance(o.get("c"),list):
            return convert_json_block(o)
        return {k:convert_tables_in_obj(v) for k,v in o.items()}
    if isinstance(o,list):
        return [convert_tables_in_obj(x) for x in o]
    return o

# Native parser: parse Haskell show format for Pandoc / list of blocks
class NativeParser:
    def __init__(self,text):
        self.s=text; self.i=0; self.n=len(text)
    def ws(self):
        while self.i<self.n and self.s[self.i].isspace(): self.i+=1
    def peek(self):
        self.ws(); return self.s[self.i] if self.i<self.n else ""
    def consume(self,ch=None):
        self.ws()
        if ch and self.i<self.n and self.s[self.i]==ch:
            self.i+=1; return True
        return False
    def parse_value(self):
        self.ws()
        if self.i>=self.n: return None
        ch=self.s[self.i]
        if ch=='"':
            return ("str", self.parse_string())
        if ch=='[':
            self.i+=1
            items=[]
            self.ws()
            if self.i<self.n and self.s[self.i]==']':
                self.i+=1; return ("list",items)
            while True:
                items.append(self.parse_value())
                self.ws()
                if self.i<self.n and self.s[self.i]==',':
                    self.i+=1; continue
                elif self.i<self.n and self.s[self.i]==']':
                    self.i+=1; break
                else: break
            return ("list",items)
        if ch=='(':
            self.i+=1
            items=[]
            self.ws()
            if self.i<self.n and self.s[self.i]==')':
                self.i+=1; return ("tuple",items)
            while True:
                items.append(self.parse_value())
                self.ws()
                if self.i<self.n and self.s[self.i]==',':
                    self.i+=1; continue
                elif self.i<self.n and self.s[self.i]==')':
                    self.i+=1; break
                else: break
            return ("tuple",items)
        if ch=='{':
            # Meta {unMeta = fromList [...] } special
            # capture balanced
            start=self.i
            depth=0
            while self.i<self.n:
                if self.s[self.i]=='{': depth+=1
                elif self.s[self.i]=='}':
                    depth-=1
                    if depth==0:
                        self.i+=1; break
                self.i+=1
            return ("brace", self.s[start:self.i])
        # atom / constructor application: read identifier/number, then following args that are atoms/lists/tuples/strings/numbers/brace or '(' not tuple? constructors args...
        # Read token
        m=re.match(r'-?[0-9]+(?:\.[0-9]+)?|[A-Za-z_][A-Za-z0-9_\']*', self.s[self.i:])
        if not m:
            # unknown char skip
            self.i+=1; return ("atom",ch)
        tok=m.group(0); self.i+=len(tok)
        # Check if this is a constructor with args: next tokens that look like start of arg ( [ ( " digit letter { ) and not ',' ']' ')' and not a following constructor that is ??? Application args are values; in Haskell show, args are atomic or parenthesized/list.
        # We parse args greedily while next token is start of a value but not a closing, and peek token is not??? How distinguish list elements separated? Inside list parser parse_value returns one application: eg Para [Str "Hi", Space] - parse_value for element: token Para, next is [ -> arg, then stops because next is ','.
        args=[]
        while True:
            save=self.i
            self.ws()
            if self.i>=self.n: break
            nxt=self.s[self.i]
            if nxt in ',])':
                break
            # If next is identifier, it could be arg like `Nothing` or `InlineMath "x"` or `1` etc. But in sequences like "[ Str \"Hi\" , Space ]", after Str "Hi", next is ',' so break. In constructor applications like "Header 1 ( ... ) [ ... ]", args are numbers/tuple/list.
            # However for nested like `MetaInlines [ Str "Me" ]`, arg is list.
            # For `(RowSpan 1)`, token RowSpan arg 1.
            # Parsing identifier as arg would incorrectly consume next element in a list like `[ Str "a" , Str "b" ]`? No commas separate.
            # But inside a tuple/list without comma? Show always uses commas.
            # In application contexts like `Caption Nothing []`, args follow.
            # So greedily parse a value as arg.
            # Guard: if tok is a simple atom like "Space" with no args expected, next identifier would be ??? But lists separate by comma, blocks by comma, so safe.
            # Only parse arg if tok is capitalised constructor or tok in known etc.
            if tok[0].isupper() or tok=="fromList":
                arg=self.parse_value()
                args.append(arg)
            else:
                self.i=save; break
        if args:
            return ("app", tok, args)
        else:
            # number?
            if re.match(r'^-?[0-9]',tok):
                try:
                    if '.' in tok: return ("num", float(tok))
                    else: return ("num", int(tok))
                except: return ("atom",tok)
            return ("atom",tok)
    def parse_string(self):
        # assume opening "
        self.i+=1; out=""
        while self.i<self.n:
            ch=self.s[self.i]
            if ch=='\\' and self.i+1<self.n:
                nxt=self.s[self.i+1]
                if nxt=='n': out+='\n'; self.i+=2
                elif nxt=='t': out+='\t'; self.i+=2
                elif nxt=='r': out+='\r'; self.i+=2
                elif nxt=='"': out+='"'; self.i+=2
                elif nxt=='\\': out+='\\'; self.i+=2
                elif nxt.isdigit():
                    # decimal escape \8212
                    m=re.match(r'\\([0-9]+)', self.s[self.i:])
                    if m:
                        out+=chr(int(m.group(1))); self.i+=len(m.group(0)); continue
                    else:
                        out+=nxt; self.i+=2
                else:
                    # \& etc ignore?
                    if nxt=='&': self.i+=2
                    else: out+=nxt; self.i+=2
                continue
            elif ch=='"':
                self.i+=1; break
            else:
                out+=ch; self.i+=1
        return out

def native_value_to_attr(v):
    # tuple (ident, [classes], [kvs])
    if isinstance(v,tuple) and v[0]=="tuple":
        items=v[1]
        ident=""
        classes=[]; kvs=[]
        if len(items)>=1 and items[0][0]=="str": ident=items[0][1]
        if len(items)>=2 and items[1][0]=="list": classes=[x[1] if x[0]=="str" else "" for x in items[1][1]]
        if len(items)>=3 and items[2][0]=="list":
            for kv in items[2][1]:
                if kv[0]=="tuple" and len(kv[1])>=2:
                    kvs.append([kv[1][0][1],kv[1][1][1]])
        return [ident,classes,kvs]
    return clone_attr(EMPTY_ATTR)

def native_value_to_inlines(v):
    if v is None: return []
    if isinstance(v,tuple) and v[0]=="list":
        return [native_value_to_inline(x) for x in v[1]]
    return []
def native_value_to_blocks(v):
    if v is None: return []
    if isinstance(v,tuple) and v[0]=="list":
        return [native_value_to_block(x) for x in v[1]]
    if isinstance(v,tuple) and v[0]=="app": # single block without list?
        return [native_value_to_block(v)]
    return []

def native_app_args(v):
    if isinstance(v,tuple) and v[0]=="app": return v[1], v[2]
    if isinstance(v,tuple) and v[0]=="atom": return v[1],[]
    return str(v),[]

def native_value_to_inline(v):
    if not isinstance(v,tuple): return I("Str",str(v))
    if v[0]=="atom":
        if v[1]=="Space": return I("Space")
        if v[1]=="SoftBreak": return I("SoftBreak")
        if v[1]=="LineBreak": return I("LineBreak")
        return I("Str",v[1])
    if v[0]=="app":
        name,args=v[1],v[2]
        if name=="Str": return I("Str", args[0][1] if args and args[0][0]=="str" else "")
        if name=="Emph": return I("Emph", native_value_to_inlines(args[0]))
        if name=="Strong": return I("Strong", native_value_to_inlines(args[0]))
        if name=="Strikeout": return I("Strikeout", native_value_to_inlines(args[0]))
        if name=="Superscript": return I("Superscript", native_value_to_inlines(args[0]))
        if name=="Subscript": return I("Subscript", native_value_to_inlines(args[0]))
        if name=="SmallCaps": return I("SmallCaps", native_value_to_inlines(args[0]))
        if name=="Underline": return I("Underline", native_value_to_inlines(args[0]))
        if name=="Quoted":
            q=args[0][1] if args[0][0]=="atom" else "DoubleQuote"
            return I("Quoted",[q, native_value_to_inlines(args[1])])
        if name=="Code": return I("Code",[native_value_to_attr(args[0]), args[1][1] if len(args)>1 else ""])
        if name=="Math":
            mt=args[0][1] if args[0][0]=="atom" else "InlineMath"
            return I("Math",[mt, args[1][1] if len(args)>1 else ""])
        if name=="RawInline": return I("RawInline",[args[0][1], args[1][1]])
        if name=="Link": return I("Link",[native_value_to_attr(args[0]), native_value_to_inlines(args[1]), [args[2][1][0][1], args[2][1][1][1]] if args[2][0]=="tuple" else ["",""]])
