    def atom_at(pos):
        if pos>=len(tex): return "",pos
        ch=tex[pos]
        if ch=='{':
            end=tex.find('}',pos)
            return mathml_inner(tex[pos+1:end]), end+1
        if ch=='\\':
            m=re.match(r'\\([A-Za-z]+)',tex[pos:])
            if m:
                sym=greek_map.get(m.group(1),m.group(1))
                return f"<mi>{sym}</mi>", pos+len(m.group(0))
            return "",pos+1
        if ch.isalpha():
            return f"<mi>{ch}</mi>", pos+1
        if ch.isdigit():
            m=re.match(r'\d+(?:\.\d+)?',tex[pos:])
            return f"<mn>{m.group(0)}</mn>", pos+len(m.group(0))
        if ch in "+-=<>*/":
            return f"<mo>{htmlmod.escape(ch)}</mo>", pos+1
        if ch in "()[]":
            return f"<mo>{ch}</mo>", pos+1
        return "",pos+1
    while i<len(tex):
        if tex[i].isspace(): i+=1; continue
        if tex[i] in "^_":
            kind="msup" if tex[i]=='^' else "msub"
            # previous element wrapped? Simplified: res last is base
            base=res.pop() if res else ""
            exp,ni=atom_at(i+1)
            res.append(f"<{kind}>{base}{exp}</{kind}>"); i=ni; continue
        atom,ni=atom_at(i)
        res.append(atom); i=ni
    return "".join(res)

