def inlines_to_plain(inlines, ctx=None, fmt="plain"):
    out=[]
    for n in inlines or []:
        t=n.get("t"); c=n.get("c")
        if t=="Str": out.append(c)
        elif t=="Space": out.append(" ")
        elif t=="SoftBreak": out.append(" " if fmt!="markdown" else "\n" if (ctx and ctx.opts.get("wrap")=="preserve") else " ")
        elif t=="LineBreak": out.append("\n")
        elif t in ("Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline"):
            inner=c[1] if t=="Span" else c
            out.append(inlines_to_plain(inner,ctx,fmt))
        elif t=="Span": out.append(inlines_to_plain(c[1],ctx,fmt))
        elif t=="Quoted":
            q='"' if c[0]=="DoubleQuote" else "'"
            inner=inlines_to_plain(c[1],ctx,fmt)
            if fmt=="plain":
                # use curly
                if c[0]=="DoubleQuote": out.append(f"“{inner}”")
                else: out.append(f"‘{inner}’")
            else:
                out.append(f"{q}{inner}{q}")
        elif t=="Code": out.append(c[1])
        elif t=="Math":
            if fmt=="plain":
                out.append(render_math_plain(c[1]))
            else:
                out.append(c[1])
        elif t=="Link": out.append(inlines_to_plain(c[1],ctx,fmt))
        elif t=="Image": out.append(inlines_to_plain(c[1],ctx,fmt))
        elif t=="RawInline": out.append(c[1] if c[0]==fmt else "")
        elif t=="Note":
            # plain: footnote as [^?] ? Plain writer drops notes? Check later: plain footnote maybe shows note at end? For now drop
            out.append("")
        elif t=="Cite": out.append(inlines_to_plain(c[1],ctx,fmt))
        else: out.append("")
    return "".join(out)

