                res.append(f"\u2005{ch}\u2005"); i+=1; continue
            if ch in ',;':
                res.append(ch+" "); i+=1; continue
            if ch in '()[]':
                res.append(ch); i+=1; continue
            atom,ni=parse_atom(s,i)
            if atom is None: return None
            res.append(atom); i=ni
        return "".join(res)
    result=convert_simple(tex_stripped)
    return result

# HTML writer
def html_attr_str(attr, extra=None):
    # attr [id, classes, kvs]; extra list of (k,v) prepend/append?
    parts=[]
    if extra:
        for k,v in extra:
            if v is not None:
                parts.append(f'{k}="{escape_html_attr(str(v))}"')
    # pandoc ordering for generic elements: id, class, then kvs as data-* ?? But earlier header: class before data before id. Need examine: Maybe they sort attributes alphabetically?
    # For header: class, data-key, id - alphabetical by attribute name (class < data-key < id)
    # For link: href, id, class, data-key -> not alphabetical (class would ...). Link special href first, then id/class/kv in order id,class,??? Wait earlier: <a href="url" id="id" class="cls" data-key="val"> That's href first, then remaining sorted? id, class not alphabetical.
    # Hmm general Attr rendering in pandoc HTML: they use `renderTags` with attributes in order given: for Header, writer passes attrs = [(id), (class), kvs converted] ??? but output reversed?
    # We'll implement generic: id first if present, class second, then kvs as (data-k if not standard else k)
    # For header case this will differ from observed (id first). Common test headers only id, so fine.
    ident,classes,kvs=attr
    if ident:
        parts.append(f'id="{escape_html_attr(ident)}"')
    if classes:
        parts.append(f'class="{escape_html_attr(" ".join(classes))}"')
    for k,v in kvs:
        if k in ("id","class"): continue
        # keys that are valid html attrs? pandoc prefixes with data- if not ... known attributes list? key=value in example became data-key.
        # Known: title, lang, dir, etc stay. Others data-
        known={"title","lang","xml:lang","dir","style","width","height","alt","src","href","target","rel","type","start","value","name","content","charset"}
        if k in known:
            parts.append(f'{k}="{escape_html_attr(v)}"')
        else:
            parts.append(f'data-{k}="{escape_html_attr(v)}"')
    return (" "+" ".join(parts)) if parts else ""

def html_attr_str_for_header(attr):
    # observed: class, data-*, id alphabetical? We'll replicate for header: class first, then data-kvs, then id
    ident,classes,kvs=attr
    parts=[]
    if classes: parts.append(f'class="{escape_html_attr(" ".join(classes))}"')
    for k,v in kvs: parts.append(f'data-{k}="{escape_html_attr(v)}"')
    if ident: parts.append(f'id="{escape_html_attr(ident)}"')
    return (" "+" ".join(parts)) if parts else ""

def highlight_code(code, lang, ctx):
    # returns html inner (with spans per line) or None if no highlight
    # Tokenizer generic
    lines=code.split("\n")
    out_lines=[]
    # Language canonical map
    canon=canonical_lang(lang)
    if not canon:
        return None
    for line in lines:
        out_lines.append(highlight_line(line, canon, ctx))
    return out_lines

lang_alias={"py":"python","js":"javascript","ts":"typescript","hs":"haskell","sh":"bash","rb":"ruby","pl":"perl","cpp":"cpp","c++":"cpp","cxx":"cpp","objc":"objectivec","shell":"bash","zsh":"zsh","yml":"yaml","md":"markdown","tex":"latex","vim":"vim","rs":"rust"}
def canonical_lang(lang):
    if not lang: return None
    l=lang.lower()
    if l in lang_alias: return lang_alias[l]
    # check if in hl languages list (from DATA loaded later - avoid circular at import time; use set hardcoded via DATA if available)
    try:
        langs=set(DATA["hl_languages"])
    except:
        langs=set()
    if l in langs:
        return l
    return None

python_keywords={"def":"kw","class":"kw","import":"kw","from":"kw","as":"kw","lambda":"kw","pass":"kw","None":"kw","True":"kw","False":"kw","and":"cf","or":"cf","not":"cf","if":"cf","elif":"cf","else":"cf","for":"cf","while":"cf","return":"cf","try":"cf","except":"cf","finally":"cf","with":"cf","in":"cf","is":"cf","raise":"cf","yield":"cf","break":"cf","continue":"cf","global":"kw","nonlocal":"kw","assert":"kw","del":"kw"}
python_builtins={"print","len","range","str","int","float","list","dict","set","tuple","open","type","isinstance","enumerate","zip","map","filter","sum","min","max","abs","repr","input","super","object","self"}
bash_builtins={"echo","cd","export","source","read","printf","test","eval","exec","shift","set","unset","alias","history","pwd","kill","jobs","fg","bg","exit","return","break","continue","declare","local","typeset"}
c_keywords={"int","char","void","float","double","long","short","unsigned","signed","const","static","struct","union","enum","typedef","sizeof","return","if","else","for","while","do","switch","case","break","continue","goto","extern","volatile","inline"}
def highlight_line(line, lang, ctx):
    # returns html for one line (without line span wrapper)
    i=0; out=[]
    # comment start markers
    def esc(s): return escape_html(s)
    while i<len(line):
        # whitespace preserve
        if line[i].isspace():
            j=i
            while j<len(line) and line[j].isspace(): j+=1
            out.append(esc(line[i:j])); i=j; continue
        # comment
        if lang in ("python","bash","ruby","perl","yaml","r","makefile") and line[i]=='#':
            out.append(f'<span class="co">{esc(line[i:])}</span>'); break
        if lang in ("c","cpp","java","javascript","typescript","rust","go","cs","php","scala","kotlin","swift") and line.startswith("//",i):
            out.append(f'<span class="co">{esc(line[i:])}</span>'); break
        if line.startswith("/*",i):
            end=line.find("*/",i)
            end=len(line) if end==-1 else end+2
            out.append(f'<span class="co">{esc(line[i:end])}</span>'); i=end; continue
        if lang in ("haskell","lua","sql") and line.startswith("--",i):
            out.append(f'<span class="co">{esc(line[i:])}</span>'); break
        # string
        if line[i] in "\"'":
            q=line[i]; j=i+1
            while j<len(line):
                if line[j]=='\\': j+=2; continue
                if line[j]==q: j+=1; break
                j+=1
            out.append(f'<span class="st">{esc(line[i:j])}</span>'); i=j; continue
        if line[i]=='`' and lang in ("javascript","typescript"):
            j=line.find('`',i+1); j=len(line) if j==-1 else j+1
            out.append(f'<span class="st">{esc(line[i:j])}</span>'); i=j; continue
        # number
        m=re.match(r'\b(0[xX][0-9a-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\b', line[i:])
        if m:
            tok=m.group(0)
            cls="bn" if tok.lower().startswith("0x") else ("fl" if "." in tok or "e" in tok.lower() else "dv")
            out.append(f'<span class="{cls}">{esc(tok)}</span>'); i+=len(tok); continue
        # word
        m=re.match(r'[A-Za-z_$][A-Za-z0-9_$]*', line[i:])
        if m:
            word=m.group(0)
            cls=None
            if lang=="python":
                if word in python_keywords: cls=python_keywords[word]
                elif word in python_builtins: cls="bu"
                elif i+len(word)<len(line) and line[i+len(word)]=='(':
                    cls="fu"
            elif lang=="bash":
                # first word of line/command
                before=line[:i].strip()
                if before=="" or before.endswith("|") or before.endswith(";"):
                    cls="bu" if word in bash_builtins else "fu"
                elif word.startswith("$"):
                    cls="va"
            elif lang in ("c","cpp","java","javascript","typescript","rust","go","cs"):
                if word in c_keywords: cls="kw"
                elif i+len(word)<len(line) and line[i+len(word)]=='(':
                    cls="fu"
            elif lang=="haskell":
                if word in ("let","in","where","case","of","data","type","newtype","class","instance","module","import","if","then","else","do"): cls="kw"
                elif word[0].isupper(): cls="dt"
                elif i+len(word)<len(line):
                    cls=None
                    # function names before space? putStrLn is fu
                    if word in ("putStrLn","print","main"):
                        cls="fu" if word!="main" else None
            elif lang=="javascript" or lang=="typescript":
                if word in ("function","const","let","var","return","if","else","for","while","class","new","import","from","export"): cls="kw"
            else:
                # generic keywords common
                if word in ("def","class","import","from","return","if","else","for","while","function","var","let","const","end","begin"): cls="kw"
            if cls:
                out.append(f'<span class="{cls}">{esc(word)}</span>')
            else:
                # bash variable? etc
                out.append(esc(word))
            i+=len(word); continue
        # bash option -la
        if lang=="bash" and line[i]=='-' and i+1<len(line) and line[i+1].isalpha():
            m=re.match(r'--[A-Za-z-]+|-[A-Za-z]+', line[i:])
            if m:
                out.append(f'<span class="at">{esc(m.group(0))}</span>'); i+=len(m.group(0)); continue
        # operator / punctuation
        ch=line[i]
        # multi char operators
        m=re.match(r'(==|!=|<=|>=|&&|\|\||\+\+|--|->|=>|::|\+\=|-\=|\*\=|/\=)', line[i:])
        if m:
            cls="ot" if lang in ("haskell",) else "op"
            out.append(f'<span class="{cls}">{esc(m.group(0))}</span>'); i+=len(m.group(0)); continue
        if ch in "=+-%*/<>!&|^~":
            cls="ot" if lang in ("haskell","r") and ch=="=" else "op"
            # haskell = ot, others op
            out.append(f'<span class="{cls}">{esc(ch)}</span>'); i+=1; continue
        # other single char
        out.append(esc(ch)); i+=1
    return "".join(out)

def html_inline(inlines, ctx):
    out=[]
    for n in inlines or []:
        t=n.get("t"); c=n.get("c")
        if t=="Str":
            out.append(escape_html(c))
        elif t=="Space": out.append(" ")
        elif t=="SoftBreak": out.append(" " if ctx.opts.get("wrap")!="preserve" else "\n")
        elif t=="LineBreak": out.append("<br />\n")
        elif t=="Emph": out.append(f"<em>{html_inline(c,ctx)}</em>")
        elif t=="Strong": out.append(f"<strong>{html_inline(c,ctx)}</strong>")
        elif t=="Strikeout": out.append(f"<del>{html_inline(c,ctx)}</del>")
        elif t=="Superscript": out.append(f"<sup>{html_inline(c,ctx)}</sup>")
        elif t=="Subscript": out.append(f"<sub>{html_inline(c,ctx)}</sub>")
        elif t=="SmallCaps": out.append(f"<span class=\"smallcaps\">{html_inline(c,ctx)}</span>")
        elif t=="Underline": out.append(f"<u>{html_inline(c,ctx)}</u>")
        elif t=="Quoted":
            if c[0]=="DoubleQuote": out.append(f"“{html_inline(c[1],ctx)}”")
            else: out.append(f"‘{html_inline(c[1],ctx)}’")
        elif t=="Code":
            attr=c[0]; code=c[1]
            # sourceCode class if language class
            classes=attr[1]
            if classes:
                # <code class="sourceCode python">
                cls_attr=f' class="sourceCode {" ".join(classes)}"'
                # also id etc ignore
                out.append(f"<code{cls_attr}>{escape_html(code)}</code>")
            else:
                extra=html_attr_str(attr)
                out.append(f"<code{extra}>{escape_html(code)}</code>")
        elif t=="Math":
            mt,tex=c
            # math rendering mode
            if ctx.opts.get("math_method")=="mathml":
                # simple: use texmath to mathml fallback? Implement very simple for x^2 etc
                out.append(render_mathml(tex,mt))
            elif ctx.opts.get("math_method") in ("mathjax","katex","webtex","gladtex"):
                # spans with tex
                typ="display" if mt=="DisplayMath" else "inline"
                if ctx.opts.get("math_method")=="mathjax":
                    delim=r"\[" if mt=="DisplayMath" else r"\("
                    close=r"\]" if mt=="DisplayMath" else r"\)"
                    out.append(f'<span class="math {typ}">{delim}{escape_html(tex)}{close}</span>')
                else:
                    out.append(f'<span class="math {typ}">{escape_html(tex)}</span>')
            else:
                html_math=texmath_to_html(tex)
                typ="display" if mt=="DisplayMath" else "inline"
                if html_math is None:
                    # fallback raw with dollars
                    raw = f"$${tex}$$" if mt=="DisplayMath" else f"${tex}$"
                    out.append(f'<span class="math {typ}">{escape_html(raw) if False else raw}</span>')
                else:
                    out.append(f'<span class="math {typ}">{html_math}</span>')
        elif t=="Link":
            attr,inls,target=c; url,title=target
            # attrs order: href, id, class, data... , title? Pandoc order: href then title? Earlier: href="..." title="..." ; with attr id: href id class data
            parts=[f'href="{escape_html_attr(url)}"']
            if attr[0]: parts.append(f'id="{escape_html_attr(attr[0])}"')
            if attr[1]: parts.append(f'class="{escape_html_attr(" ".join(attr[1]))}"')
            for k,v in attr[2]:
                parts.append(f'data-{k}="{escape_html_attr(v)}"')
            if title: parts.append(f'title="{escape_html_attr(title)}"')
            # For autolink uri class: if link text == url and attr class uri? In markdown <url> created Link with same text, html gets class="uri" . Our parser doesn't mark. Detect: url == plain text and source was < >? It stored... we didn't mark. Heuristic: if url==inline text and url startswith http/mailto and inlines is single Str equal, add class uri if ??? Bare autolink <https://> gave class uri. Link [https://](https://) also likely class uri? Probably pandoc marks autolink. Our detection may cause false for explicit link same text - pandoc also maybe gives uri? Check: [https://example.com](https://example.com) likely also uri? Possibly. We'll add class="uri" when text==url.
            # Adjust: if detected, class should be after href (?) example <a href="https://..." class="uri">
            if inline_text(inls)==url and re.match(r'^(https?://|mailto:|www\.)', url):
                # insert class uri as second attr if no class
                if not attr[1]:
                    parts.insert(1,'class="uri"')
            out.append(f"<a {' '.join(parts)}>{html_inline(inls,ctx)}</a>")
        elif t=="Image":
            attr,inls,target=c; src,title=target
            alt=escape_html_attr(inline_text(inls))
            parts=[f'src="{escape_html_attr(src)}"']
            if title: parts.append(f'title="{escape_html_attr(title)}"')
            # attr id/class etc before alt? Probably after src?
            if attr[0]: parts.append(f'id="{escape_html_attr(attr[0])}"')
            if attr[1]: parts.append(f'class="{escape_html_attr(" ".join(attr[1]))}"')
            for k,v in attr[2]:
                # width/height etc direct?
                if k in ("width","height"): parts.append(f'{k}="{escape_html_attr(v)}"')
                else: parts.append(f'data-{k}="{escape_html_attr(v)}"')
            parts.append(f'alt="{alt}"')
            out.append(f"<img {' '.join(parts)} />")
        elif t=="RawInline":
            if c[0] in ("html","html5","html4",""): out.append(c[1])
            else: out.append("")
        elif t=="Span":
            attr,inls=c
            if attr[0] or attr[1] or attr[2]:
                out.append(f"<span{html_attr_str(attr)}>{html_inline(inls,ctx)}</span>")
            else:
                out.append(html_inline(inls,ctx))
        elif t=="Note":
            num=ctx.register_note(c)
            out.append(f'<a href="#fn{num}" class="footnote-ref" id="fnref{num}" role="doc-noteref"><sup>{num}</sup></a>')
        elif t=="Cite":
            # citations: rendering without citeproc: [@key] becomes ??? html: maybe <span class="citation" data-cites="key">(@key)</span>
            # Simplify: output inline text
            out.append(html_inline(c[1],ctx))
        else:
            out.append("")
    return "".join(out)

def render_mathml(tex, mt):
    # very simple conversion for cases like x^2, x, a+b
    # Use python? Build <math ...><semantics>...</semantics></math>
    # parse tokens simple
    display=' display="block"' if mt=="DisplayMath" else ' display="inline"'
    inner=mathml_inner(tex)
    return f'<math{display} xmlns="http://www.w3.org/1998/Math/MathML"><semantics>{inner}<annotation encoding="application/x-tex">{escape_html(tex)}</annotation></semantics></math>'
def mathml_inner(tex):
    # recursive descent for ^ _
    res=[]; i=0
    def atom_at(pos):
        if pos>=len(tex): return "",pos
        ch=tex[pos]
        if ch=='{':
            end=tex.find('}',pos)
            return mathml_inner(tex[pos+1:end]), end+1
        if ch=='\\':
            m=re.match(r'\\([A-Za-z]+)',tex[pos:])
            if m:
                sym=greek_map.get(m.group(1),m.group(1))
                return f"<mi>{sym}</mi>", pos+len(m.group(0))
            return "",pos+1
        if ch.isalpha():
            return f"<mi>{ch}</mi>", pos+1
        if ch.isdigit():
            m=re.match(r'\d+(?:\.\d+)?',tex[pos:])
            return f"<mn>{m.group(0)}</mn>", pos+len(m.group(0))
        if ch in "+-=<>*/":
            return f"<mo>{htmlmod.escape(ch)}</mo>", pos+1
        if ch in "()[]":
            return f"<mo>{ch}</mo>", pos+1
        return "",pos+1
    while i<len(tex):
        if tex[i].isspace(): i+=1; continue
        if tex[i] in "^_":
            kind="msup" if tex[i]=='^' else "msub"
            # previous element wrapped? Simplified: res last is base
            base=res.pop() if res else ""
            exp,ni=atom_at(i+1)
            res.append(f"<{kind}>{base}{exp}</{kind}>"); i=ni; continue
        atom,ni=atom_at(i)
        res.append(atom); i=ni
    return "".join(res)

def html_block(block, ctx):
    t=block.get("t"); c=block.get("c")
    if t=="Para":
        return f"<p>{html_inline(c,ctx)}</p>"
    if t=="Plain":
        return html_inline(c,ctx)
    if t=="Header":
        level,attr,inls=c
        # number sections
        content=html_inline(inls,ctx)
        extra=""
        if ctx.opts.get("number_sections"):
            # numbering computed in preprocessing stored in ctx.header_numbers[id(block)] ?
            num=ctx.opts.get("_header_num",{}).get(id(block))
            if num:
                extra=f'<span class="header-section-number">{num}</span> '
                # attr data-number
                # modify attr rendering: pandoc <h1 data-number="1" id="a">
                # We'll construct tag manually
                parts=[]
                parts.append(f'data-number="{num}"')
                if attr[0]: parts.append(f'id="{escape_html_attr(ctx.id_prefix+attr[0])}"')
                if attr[1]: parts.append(f'class="{escape_html_attr(" ".join(attr[1]))}"')
                for k,v in attr[2]: parts.append(f'data-{k}="{escape_html_attr(v)}"')
                return f"<h{level} {' '.join(parts)}>{extra}{content}</h{level}>"
        # id prefix
        attr2=clone_attr(attr)
        if attr2[0]: attr2[0]=ctx.id_prefix+attr2[0]
        return f"<h{level}{html_attr_str_for_header(attr2)}>{content}</h{level}>"
    if t=="CodeBlock":
        attr,code=c
        return html_codeblock(attr,code,ctx)
    if t=="RawBlock":
        fmt,txt=c
        if fmt in ("html","html5","html4",""):
            return txt
        return ""  # raw latex etc not output in html; pandoc returns empty? Earlier \begin{equation} gave <p></p> ??? That was Para containing Raw? ignore
    if t=="BlockQuote":
        inner="\n".join(html_block(b,ctx) for b in c)
        return f"<blockquote>\n{inner}\n</blockquote>"
    if t=="BulletList":
        # task list detection
        items_html=[]
        has_task=False; all_task=True
        for item in c:
            # check first plain/para first inline Str ☐/☒
            first_inlines=[]
            if item and item[0].get("t") in ("Plain","Para"):
                first_inlines=item[0].get("c",[])
            is_task=False; checked=False
            if first_inlines and first_inlines[0].get("t")=="Str" and first_inlines[0].get("c") in ("☐","☒","☐"):
                is_task=True; checked=first_inlines[0].get("c")=="☒"; has_task=True
            else:
                all_task=False
            if not is_task:
                all_task=False
            # render item
            item_content=html_list_item(item,ctx,is_task,checked)
            items_html.append(item_content)
        cls=' class="task-list"' if (has_task and all_task) else ""
        inner="\n".join(items_html)
        return f"<ul{cls}>\n{inner}\n</ul>"
    if t=="OrderedList":
        (start,style,delim),items=c
        type_map={"Decimal":"1","LowerAlpha":"a","UpperAlpha":"A","LowerRoman":"i","UpperRoman":"I","Default":None,"Example":None}
        typ=type_map.get(style)
        attrs=[]
        if start!=1: attrs.append(f'start="{start}"')
        if typ: attrs.append(f'type="{typ}"')
        attr_str=(" "+" ".join(attrs)) if attrs else ""
        inner="\n".join(html_list_item(item,ctx) for item in items)
        return f"<ol{attr_str}>\n{inner}\n</ol>"
    if t=="DefinitionList":
        parts=["<dl>"]
        for term,defs in c:
            parts.append(f"<dt>{html_inline(term,ctx)}</dt>")
            for d in defs:
                # def blocks: if Plain/Para singular, render its inlines without p but blocks joined newline
                if len(d)==1 and d[0].get("t") in ("Plain","Para"):
                    parts.append(f"<dd>\n{html_inline(d[0]['c'],ctx)}\n</dd>")
                else:
                    # multiple Plain blocks: join newline like earlier
                    rendered=[]
                    for b in d:
                        if b.get("t") in ("Plain","Para"):
                            rendered.append(html_inline(b["c"],ctx))
                        else:
                            rendered.append(html_block(b,ctx))
                    parts.append(f"<dd>\n{'chr(10)'.join(rendered) if False else chr(10).join(rendered)}\n</dd>")
        parts.append("</dl>")
        return "\n".join(parts)
    if t=="LineBlock":
        lines=[html_inline(line,ctx) for line in c]
        inner="<br />\n".join(lines)
        return f'<div class="line-block">{inner}</div>'
    if t=="HorizontalRule":
        return "<hr />"
    if t=="Div":
        attr,blocks_inner=c
        # unwrap? If attr empty, html writer still outputs <div> (?) earlier Div from markdown fence with warning class, empty div from html <div> gave <div> . For native Div empty, pandoc html outputs <div> wrapper.
        inner="\n".join(html_block(b,ctx) for b in blocks_inner)
        # Special section div? Djot: class section id = header text - output? Djot html maybe <section> ? ignore: div
        # If class contains "section" and ... (?) pandoc section divs option off.
        return f"<div{html_attr_str(attr)}>\n{inner}\n</div>"
    if t=="Figure":
        attr,caption,blocks_inner=c
        # caption: [short, blocks]
        cap_blocks=caption[1] if isinstance(caption,list) and len(caption)>1 else []
        cap_text=""
        if cap_blocks:
            # plain text / inline
            if cap_blocks[0].get("t") in ("Plain","Para"):
                cap_text=html_inline(cap_blocks[0]["c"],ctx)
        # blocks: Plain with Image
        inner_lines=[]
        for b in blocks_inner:
            if b.get("t") in ("Plain","Para"):
                inner_lines.append(html_inline(b["c"],ctx))
            else:
                inner_lines.append(html_block(b,ctx))
        parts=["<figure>"]
        parts.extend(inner_lines)
        if cap_text:
            parts.append(f'<figcaption aria-hidden="true">{cap_text}</figcaption>')
        parts.append("</figure>")
        return "\n".join(parts)
    if t=="Table":
        return html_table(block,ctx)
    if t=="Null":
        return ""
