    for r in rows: allr.append([rst_inline(x,ctx) for x in r])
    if not allr: return ""
    ncol=max(len(r) for r in allr)
    widths=[0]*ncol
    for r in allr:
        for i,cell in enumerate(r): widths[i]=max(widths[i],len(cell))
    def fmt_row(r):
        return "  ".join(cell.ljust(widths[i]) for i,cell in enumerate(r)).rstrip()
    sep="  ".join("="*widths[i] for i in range(ncol))
    lines=[sep]
    if header:
        lines.append(fmt_row(allr[0])); lines.append(sep); rest=allr[1:]
    else: rest=allr
    for r in rest: lines.append(fmt_row(r))
    lines.append(sep)
    return "\n".join(lines)

def write_rst(blocks,ctx):
    parts=[]
    for b in blocks:
        txt=rst_block(b,ctx)
        if txt!="": parts.append(txt)
    body="\n\n".join(parts)
    if ctx.footnotes:
        fn=[]
        for idx,(k,bl) in enumerate(ctx.footnotes):
            txt=" ".join(rst_block(x,ctx) for x in bl)
            fn.append(f".. [{idx+1}] {txt}")
        body=body+"\n\n"+"\n\n".join(fn)
    return body

