# Build Haskell token tree: nodes as tuples:
# ('atom', s) ('str', s) ('num', n) ('list', [...]) ('tuple', [...]) ('app', name, [args]) ('meta', meta_dict)
def hs_str(s):
    # Haskell string literal with escapes: non-ascii as \123 decimal? pandoc shows \8212 etc for unicode >127? Observed Str "\8212" etc, "caf\195\169" (utf8 bytes as decimal?) Actually café: \195\169 is UTF-8 bytes decoded as chars? Native writer uses show which escapes non-ASCII as decimal of char code? café é is 233, not 195 169. But their input bytes mis? Wait earlier python mis encoded. Ignore: Haskell show for unicode char é (233) would be \233 . We'll do: escape ", \, newline etc, and non-printable / >127 as \decimal (codepoint)
    out='"'
    for ch in s:
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\t': out+='\\t'
        elif ch=='\r': out+='\\r'
        elif o<32 or o>126:
            out+=f'\\{o}'
        else:
            out+=ch
    out+='"'
    return out

def inline_to_hs(n):
    t=n.get("t"); c=n.get("c")
    if t=="Str": return ('app',"Str",[('str',c)])
    if t=="Space": return ('atom',"Space")
    if t=="SoftBreak": return ('atom',"SoftBreak")
    if t=="LineBreak": return ('atom',"LineBreak")
    if t in ("Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline"):
        return ('app',t,[('list',[inline_to_hs(x) for x in c])])
    if t=="Quoted":
