    out='"'
    for ch in s:
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\t': out+='\\t'
        elif ch=='\r': out+='\\r'
        elif o<32 or o>126:
            out+=f'\\{o}'
        else:
