    if t in ("Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline"):
        return ('app',t,[('list',[inline_to_hs(x) for x in c])])
    if t=="Quoted":
        return ('app',"Quoted",[('atom',c[0]),('list',[inline_to_hs(x) for x in c[1]])])
    if t=="Code":
        return ('app',"Code",[attr_to_hs(c[0]),('str',c[1])])
    if t=="Math":
        return ('app',"Math",[('atom',c[0]),('str',c[1])])
    if t=="RawInline":
        return ('app',"RawInline",[('str',c[0]),('str',c[1])])
    if t=="Link":
        return ('app',"Link",[attr_to_hs(c[0]),('list',[inline_to_hs(x) for x in c[1]]),('tuple',[('str',c[2][0]),('str',c[2][1])])])
    if t=="Image":
        return ('app',"Image",[attr_to_hs(c[0]),('list',[inline_to_hs(x) for x in c[1]]),('tuple',[('str',c[2][0]),('str',c[2][1])])])
    if t=="Span":
        return ('app',"Span",[attr_to_hs(c[0]),('list',[inline_to_hs(x) for x in c[1]])])
