        elif t=="Strong":
            inner=generic_inline(c,ctx,fmt)
            out.append({"org":f"*{inner}*","asciidoc":f"*{inner}*","mediawiki":f"'''{inner}'''","muse":f"**{inner}**","textile":f"*{inner}*","haddock":f"__{inner}__","djot":f"*{inner}*","typst":f"#strong[{inner}]","jira":f"*{inner}*","dokuwiki":f"**{inner}**","context":f"{{\\bf {inner}}}","texinfo":f"@strong{{{inner}}}","man":f"\\f[B]{inner}\\f[R]","ms":f"\\f[B]{inner}\\f[R]"}.get(fmt,inner))
        elif t=="Strikeout":
