            out.append({"org":f"+{inner}+","gfm":f"~~{inner}~~","djot":f"{{-{inner}-}}"}.get(fmt,inner))
        elif t=="Superscript": out.append(f"^{generic_inline(c,ctx,fmt)}^" if fmt in ("org","markdown") else generic_inline(c,ctx,fmt))
