def generic_table(block,ctx,fmt):
    c=block["c"]; header=c.get("header_inlines",[]); rows=c.get("row_inlines",[])
    def cell(x): return generic_inline(x,ctx,fmt)
    if fmt=="org":
        lines=[]
        if header: lines.append("| "+" | ".join(cell(h) for h in header)+" |")
        if header: lines.append("|"+"+".join("---" for _ in header)+"|") # org separator is |---+---|
        # fix separator format
        if header: lines[-1]="|"+"+".join(["---"]*len(header))+"|"
        for r in rows: lines.append("| "+" | ".join(cell(x) for x in r)+" |")
        return "\n".join(lines)
    if fmt=="asciidoc":
        lines=['[cols=",",options="header",]','|===']
        if header: lines.append("|"+" |".join(cell(h) for h in header))
        for r in rows: lines.append("|"+" |".join(cell(x) for x in r))
        lines.append("|===")
        return "\n".join(lines)
    if fmt=="mediawiki":
        lines=['{| class="wikitable"']
        if header:
            lines.append("|-")
            for h in header: lines.append(f"! {cell(h)}")
        for r in rows:
            lines.append("|-")
            for x in r: lines.append(f"| {cell(x)}")
        lines.append("|}")
        return "\n".join(lines)
    if fmt=="dokuwiki":
        lines=[]
        if header: lines.append("^"+"^".join(cell(h) for h in header)+"^")
        for r in rows: lines.append("|"+"|".join(cell(x) for x in r)+"|")
        return "\n".join(lines)
    if fmt=="textile":
        lines=[]
        if header: lines.append("|"+"|".join("_. "+cell(h) for h in header)+"|")
        for r in rows: lines.append("|"+"|".join(cell(x) for x in r)+"|")
        return "\n".join(lines)
    if fmt=="djot":
        lines=[]
        if header: lines.append("| "+" | ".join(cell(h) for h in header)+" |"); lines.append("|"+"-|"*len(header) if False else "|"+"|".join("-" for _ in header)+"|")
        for r in rows: lines.append("| "+" | ".join(cell(x) for x in r)+" |")
        return "\n".join(lines)
    if fmt=="haddock":
        # grid
        allr=[]
        if header: allr.append([cell(h) for h in header])
        for r in rows: allr.append([cell(x) for x in r])
        widths=[max(len(r[i]) for r in allr) for i in range(len(allr[0]))] if allr else []
        def border(ch): return "+"+"+".join(ch*(w+2) for w in widths)+"+"
        lines=[border("-")]
        if header:
            lines.append("| "+" | ".join(allr[0][i].ljust(widths[i]) for i in range(len(widths)))+" |"); lines.append(border("=")); rest=allr[1:]
        else: rest=allr
        for r in rest: lines.append("| "+" | ".join(r[i].ljust(widths[i]) for i in range(len(widths)))+" |")
        lines.append(border("-")); return "\n".join(lines)
    if fmt=="typst":
        ncol=len(header) if header else len(rows[0]) if rows else 0
        cells=[]
        if header: cells.append("table.header("+", ".join(f"[{cell(h)}]" for h in header)+",)")
        for r in rows: cells.append(", ".join(f"[{cell(x)}]" for x in r)+",")
        inner=",\n    ".join(cells)
        return f"#figure(\n  align(center)[#table(\n    columns: {ncol},\n    align: ({','.join(['auto']*ncol)},),\n    {inner}\n  )]\n  , kind: table\n  )"
    # fallback plain table
    return plain_table(block,ctx)

def write_generic(blocks,ctx,fmt):
    parts=[]
    for b in blocks:
        txt=generic_block(b,ctx,fmt)
        if txt!="": parts.append(txt)
    body="\n\n".join(parts)
    # context section closing? Our context headers opened sectionlevel without close - ignore complexity; for context writer, special handling in write_context
    return body

