# ---------------- Additional writers ----------------
def tokens_for_line(line, lang):
    # returns list of (cls, text) where cls None = normal
    # Reuse highlight_line HTML parsing? Instead simple tokenizer duplicating logic roughly using highlight_line and parsing spans
    h=highlight_line(line, lang, None)
    # parse <span class="xx">...</span> and plain
    tokens=[]; i=0
    while i<len(h):
        m=re.match(r'<span class="([a-z]+)">(.*?)</span>', h[i:], re.S)
        if m:
            tokens.append((m.group(1), htmlmod.unescape(re.sub(r'<[^>]+>','',m.group(2))))); i+=len(m.group(0)); continue
        # plain until next span
        j=h.find('<span',i)
        if j==-1: j=len(h)
        txt=htmlmod.unescape(h[i:j])
        if txt: tokens.append((None,txt))
        i=j
    return tokens

