def latex_highlight_code(code, lang):
    canon=canonical_lang(lang)
    if not canon: return code
    lines=[]
    for line in code.split("\n"):
        parts=[]
        for cls,txt in tokens_for_line(line, canon):
            macro=latex_token_map.get(cls,"NormalTok") if cls else "NormalTok"
            parts.append(f"\\{macro}{{{latex_escape(txt)}}}")
        lines.append("".join(parts))
    return "\n".join(lines)

