        elif t=="Space": out.append(" ")
        elif t=="SoftBreak": out.append(" ")
        elif t=="LineBreak": out.append("\n")
        elif t=="Emph": out.append(f"<emphasis>{db_inline(c,ctx,mode)}</emphasis>" if mode!="jats" else f"<italic>{db_inline(c,ctx,mode)}</italic>")
        elif t=="Strong": out.append(f'<emphasis role="strong">{db_inline(c,ctx,mode)}</emphasis>' if mode=="docbook" else f"<bold>{db_inline(c,ctx,mode)}</bold>" if mode=="jats" else f"<hi rend=\"bold\">{db_inline(c,ctx,mode)}</hi>")
        elif t=="Code": out.append(f"<literal>{xml_escape(c[1])}</literal>" if mode=="docbook" else f"<monospace>{xml_escape(c[1])}</monospace>" if mode=="jats" else f"<code>{xml_escape(c[1])}</code>")
        elif t=="Link":
            txt=db_inline(c[1],ctx,mode); url=c[2][0]
            if mode=="docbook": out.append(f'<link xlink:href="{xml_escape(url)}">{txt}</link>')
            elif mode=="jats": out.append(f'<ext-link ext-link-type="uri" xlink:href="{xml_escape(url)}" xlink:title="{xml_escape(c[2][1])}">{txt}</ext-link>' if c[2][1] else f'<ext-link ext-link-type="uri" xlink:href="{xml_escape(url)}">{txt}</ext-link>')
            else: out.append(f'<ref target="{xml_escape(url)}">{txt}</ref>')
        elif t=="Image":
            txt=db_inline(c[1],ctx,mode); src=c[2][0]
            if mode=="docbook": out.append(f'<inlinemediaobject>\n      <imageobject>\n        <imagedata fileref="{xml_escape(src)}" />\n      </imageobject>\n      <textobject>\n        <phrase>{txt}</phrase>\n      </textobject>\n    </inlinemediaobject>')
            elif mode=="jats":
                # mime subtype from extension
                ext=src.rsplit('.',1)[-1].lower() if '.' in src else ""
                out.append(f'<inline-graphic mimetype="image" mime-subtype="{ext}" xlink:href="{xml_escape(src)}">\n    <alt-text>{txt}</alt-text>\n  </inline-graphic>')
            else: out.append(f'<graphic url="{xml_escape(src)}"/>')
        elif t=="Quoted": out.append(f"“{db_inline(c[1],ctx,mode)}”" if c[0]=="DoubleQuote" else f"‘{db_inline(c[1],ctx,mode)}’")
        elif t=="Math": out.append(db_inline([I("Str",c[1])],ctx,mode))
        elif t=="Span": out.append(db_inline(c[1],ctx,mode))
        elif t=="Superscript": out.append(f"<superscript>{db_inline(c,ctx,mode)}</superscript>")
        elif t=="Subscript": out.append(f"<subscript>{db_inline(c,ctx,mode)}</subscript>")
        elif t=="Strikeout": out.append(db_inline(c,ctx,mode))
        elif t=="SmallCaps": out.append(db_inline(c,ctx,mode))
        elif t=="RawInline": out.append(c[1] if c[0]==mode else "")
        elif t=="Note": out.append("")
    return "".join(out)

def write_docbook(blocks,ctx,mode="docbook"):
    # Section nesting based on headers: simplified flatten with section wrappers for level1 only like sample: first h1 opens section, rest inside.
    # Implement generic recursive section building
    # Build tree
    def build(blist):
        sections=[]; cur=None
        for b in blist:
            if b.get("t")=="Header" and b["c"][0]==1:
                cur={"header":b,"children":[]}; sections.append(cur)
            elif cur is not None:
                cur["children"].append(b)
            else:
                sections.append(b)
        return sections
    parts=[]
    items=build(blocks)
    for it in items:
        if isinstance(it,dict) and "header" in it:
            h=it["header"]; level,attr,inls=h["c"]
            if mode=="docbook":
                parts.append(f'<section xmlns="http://docbook.org/ns/docbook" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="{xml_escape(attr[0])}">')
                parts.append(f"  <title>{db_inline(inls,ctx,mode)}</title>")
                for b in it["children"]: parts.append(db_block(b,ctx,mode,indent=2))
                parts.append("</section>")
            elif mode=="jats":
                parts.append(f'<sec id="{xml_escape(attr[0])}">')
                parts.append(f"  <title>{db_inline(inls,ctx,mode)}</title>")
                for b in it["children"]: parts.append(db_block(b,ctx,mode,indent=2))
                parts.append("</sec>")
            else: # tei
                parts.append(f'<div xmlns="http://www.tei-c.org/ns/1.0">')
                parts.append(f"  <head>{db_inline(inls,ctx,mode)}</head>")
                for b in it["children"]: parts.append(db_block(b,ctx,mode,indent=2))
                parts.append("</div>")
        else:
            parts.append(db_block(it,ctx,mode,0))
    return "\n".join([p for p in parts if p])

def db_block(b,ctx,mode,indent=0):
    sp=" "*indent; t=b.get("t"); c=b.get("c")
    if t=="Para": return f"{sp}<para>\n{sp}  {db_inline(c,ctx,mode)}\n{sp}</para>" if mode=="docbook" else f"{sp}<p>{db_inline(c,ctx,mode)}</p>"
    if t=="Plain": return f"{sp}{db_inline(c,ctx,mode)}"
    if t=="Header":
        level,attr,inls=c
        if mode=="jats": return f"{sp}<sec><title>{db_inline(inls,ctx,mode)}</title></sec>"
        return f"{sp}<section><title>{db_inline(inls,ctx,mode)}</title></section>"
    if t=="CodeBlock":
        lang=c[0][1][0] if c[0][1] else ""
        canon=canonical_lang(lang) or lang
        if mode=="docbook": return f'{sp}<programlisting language="{canon}">\n{xml_escape(c[1])}\n{sp}</programlisting>'
        if mode=="jats": return f'{sp}<code language="{xml_escape(lang)}">{xml_escape(c[1])}</code>'
        return f"{sp}<eg>{xml_escape(c[1])}</eg>"
    if t=="BulletList":
        if mode=="jats":
            lines=[f"{sp}<list list-type=\"bullet\">"]
            for item in c:
                lines.append(f"{sp}  <list-item>")
                for sub in item: lines.append(f"{sp}    <p>{db_inline(sub['c'],ctx,mode) if sub.get('t') in ('Plain','Para') else ''}</p>")
                lines.append(f"{sp}  </list-item>")
            lines.append(f"{sp}</list>"); return "\n".join(lines)
        lines=[f"{sp}<itemizedlist spacing=\"compact\">"]
        for item in c:
            lines.append(f"{sp}  <listitem>")
            for sub in item:
                if sub.get("t") in ("Plain","Para"): lines.append(f"{sp}    <para>\n{sp}      {db_inline(sub['c'],ctx,mode)}\n{sp}    </para>")
                else: lines.append(db_block(sub,ctx,mode,indent+4))
            lines.append(f"{sp}  </listitem>")
        lines.append(f"{sp}</itemizedlist>"); return "\n".join(lines)
    if t=="OrderedList":
        lines=[f"{sp}<orderedlist>"]
        for item in c[1]:
            lines.append(f"{sp}  <listitem>")
            for sub in item: lines.append(db_block(sub,ctx,mode,indent+4))
            lines.append(f"{sp}  </listitem>")
        lines.append(f"{sp}</orderedlist>"); return "\n".join(lines)
    if t=="BlockQuote":
        inner="\n".join(db_block(x,ctx,mode,indent+2) for x in c)
        if mode=="jats": return f"{sp}<disp-quote>\n{inner}\n{sp}</disp-quote>"
        return f"{sp}<blockquote>\n{inner}\n{sp}</blockquote>"
    if t=="Table":
        header=c.get("header_inlines",[]); rows=c.get("row_inlines",[])
        if mode=="jats":
            lines=[f"{sp}<table-wrap>",f"{sp}  <table>",f"{sp}    <thead>",f"{sp}      <tr>"]
            for h in header: lines.append(f"{sp}        <th>{db_inline(h,ctx,mode)}</th>")
            lines.append(f"{sp}      </tr>"); lines.append(f"{sp}    </thead>"); lines.append(f"{sp}    <tbody>")
            for r in rows:
                lines.append(f"{sp}      <tr>")
                for cell in r: lines.append(f"{sp}        <td>{db_inline(cell,ctx,mode)}</td>")
                lines.append(f"{sp}      </tr>")
            lines.append(f"{sp}    </tbody>"); lines.append(f"{sp}  </table>"); lines.append(f"{sp}</table-wrap>"); return "\n".join(lines)
        # docbook informaltable
        ncol=len(header)
        lines=[f"{sp}<informaltable>",f"{sp}  <tgroup cols=\"{ncol}\">"]
        for a in c.get("aligns",[]): lines.append(f'{sp}    <colspec align="left" />')
        if header:
            lines.append(f"{sp}    <thead>"); lines.append(f"{sp}      <row>")
            for h in header: lines.append(f"{sp}        <entry>\n{sp}          {db_inline(h,ctx,mode)}\n{sp}        </entry>")
            lines.append(f"{sp}      </row>"); lines.append(f"{sp}    </thead>")
        lines.append(f"{sp}    <tbody>")
        for r in rows:
            lines.append(f"{sp}      <row>")
            for cell in r: lines.append(f"{sp}        <entry>\n{sp}          {db_inline(cell,ctx,mode)}\n{sp}        </entry>")
            lines.append(f"{sp}      </row>")
        lines.append(f"{sp}    </tbody>"); lines.append(f"{sp}  </tgroup>"); lines.append(f"{sp}</informaltable>"); return "\n".join(lines)
    if t=="HorizontalRule": return ""
    if t=="Div": return "\n".join(db_block(x,ctx,mode,indent) for x in c[1])
    if t=="Figure":
        return ""
    return ""

# ---------------- Writer dispatch ----------------
def transform_blocks(blocks, opts):
    shift=opts.get("shift_heading_level_by",0)
    if opts.get("base_header_level") is not None:
        try: shift=int(opts["base_header_level"])-1
        except: pass
    if shift:
        def walk(blist):
            for b in blist:
                if b.get("t")=="Header":
                    lvl=b["c"][0]+shift
                    if lvl<1:
                        # becomes Para if <1? pandoc shift -1 on H1 gives Para? Check earlier: shift -1 on ## gave h1, # with -1 ? Probe mental: heading level 0 becomes Para
                        # We'll convert later
                        b["c"][0]=lvl
                    elif lvl>6: b["c"][0]=6
                    else: b["c"][0]=lvl
                # recurse
                c=b.get("c")
                if b.get("t") in ("BlockQuote",): walk(c)
                elif b.get("t")=="Div": walk(c[1])
                elif b.get("t")=="BulletList":
                    for it in c: walk(it)
                elif b.get("t")=="OrderedList":
                    for it in c[1]: walk(it)
        walk(blocks)
        # convert Header level <1 to Para, >6 stay?
        def conv(blist):
            for idx,b in enumerate(blist):
                if b.get("t")=="Header" and b["c"][0]<1:
                    blist[idx]=B("Para",b["c"][2])
        conv(blocks)
    return blocks

def render_body(meta, blocks, fmt_base, opts):
    ctx=WriterContext(opts, meta, fmt_base)
    ctx.fmt=fmt_base
    blocks=transform_blocks(json.loads(json.dumps(blocks, default=str)) if False else blocks, opts)  # careful tuples DefinitionList - json would break; our transform operates in place
    # Actually blocks may contain tuples for DefinitionList; in-place ok
    if fmt_base in ("html","html5"):
        return write_html(blocks, ctx), ctx
    if fmt_base=="html4":
        # html4 variant: use html writer then adjust some tags? footnote section div instead section, figure div...
        html_out=write_html(blocks,ctx)
        html_out=html_out.replace('<section id="footnotes" class="footnotes footnotes-end-of-document" role="doc-endnotes">','<div class="footnotes">')
        # closing section for footnotes only? risky - last </section>
        # figure to div.figure
        html_out=re.sub(r'<figure>\n(.*?)\n<figcaption aria-hidden="true">(.*?)</figcaption>\n</figure>', r'<div class="figure">\1\n<p class="caption">\2</p>\n</div>', html_out, flags=re.S)
        return html_out, ctx
    if fmt_base in ("latex","beamer"):
        return write_latex(blocks,ctx), ctx
    if fmt_base in ("markdown","markdown_github","markdown_mmd","markdown_phpextra","markdown_strict","commonmark","commonmark_x","gfm","markua","djot"):
        # djot has own generic but markdown-like
        if fmt_base=="djot":
            return write_generic(blocks,ctx,"djot"), ctx
        # adjust ctx fmt for table decisions in md_block
        ctx.fmt=fmt_base
        # For commonmark, tables rendered as html in md_block? Handle via special: replace table blocks with RawBlock html
        if fmt_base=="commonmark":
            # transform tables to raw html
            new_blocks=[]
            for b in blocks:
                if b.get("t")=="Table":
                    html_table_str=html_table(b, WriterContext(opts,meta,"html"))
                    new_blocks.append(B("RawBlock",["html",html_table_str]))
                else: new_blocks.append(b)
            return write_markdown(new_blocks,ctx), ctx
        return write_markdown(blocks,ctx), ctx
    if fmt_base=="plain":
        return write_plain(blocks,ctx), ctx
    if fmt_base=="ansi":
        return write_ansi(blocks,ctx), ctx
    if fmt_base=="native":
        return write_native(meta,blocks,standalone=opts.get("standalone",False)), ctx
    if fmt_base=="json":
        return write_json(meta,blocks), ctx
    if fmt_base=="xml":
        return write_xml(meta,blocks,ctx), ctx
    if fmt_base=="rst":
        return write_rst(blocks,ctx), ctx
    if fmt_base in ("docbook","docbook4","docbook5"):
        return write_docbook(blocks,ctx,"docbook"),ctx
    if fmt_base in ("jats","jats_archiving","jats_publishing","jats_articleauthoring"):
        return write_docbook(blocks,ctx,"jats"),ctx
    if fmt_base=="tei":
        return write_docbook(blocks,ctx,"tei"),ctx
    if fmt_base=="opendocument":
        return write_docbook(blocks,ctx,"opendocument"),ctx
    if fmt_base=="ipynb":
        return write_ipynb(meta,blocks,ctx),ctx
    if fmt_base in ("bibtex","biblatex","csljson"):
        return write_biblio(meta,blocks,ctx,fmt_base),ctx
    if fmt_base in ("org","asciidoc","asciidoc_legacy","asciidoctor","mediawiki","muse","textile","haddock","dokuwiki","typst","jira","context","man","ms","texinfo","bbcode","bbcode_fluxbb","bbcode_phpbb","bbcode_steam","bbcode_hubzilla","bbcode_xenforo","zimwiki","xwiki","vimdoc","tikiwiki","twiki","creole","fb2","icml","opml","chunkedhtml","s5","slidy","slideous","dzslides","revealjs","epub","epub2","epub3","docx","odt","pptx","pdf"):
        # some special:
        if fmt_base in ("bbcode","bbcode_fluxbb","bbcode_phpbb","bbcode_steam","bbcode_hubzilla","bbcode_xenforo"):
            return write_bbcode(blocks,ctx),ctx
        if fmt_base=="zimwiki":
            return write_zimwiki(blocks,ctx),ctx
        if fmt_base=="xwiki":
            return write_generic(blocks,ctx,"mediawiki"),ctx # approx will adjust
        if fmt_base=="context":
            return write_context(blocks,ctx),ctx
        fmt_map={"asciidoc_legacy":"asciidoc","asciidoctor":"asciidoc"}
        return write_generic(blocks,ctx, fmt_map.get(fmt_base,fmt_base)),ctx
    # fallback plain
    return write_plain(blocks,ctx),ctx

def write_ansi(blocks,ctx):
    # Use plain but with ANSI for header/bold/em/code
    # Implement based on plain blocks and inline ansi
    parts=[]
    for b in blocks:
        t=b.get("t")
        if t=="Header":
            txt=ansi_inline(b["c"][2],ctx, header=True)
            parts.append(txt.upper() if False else txt)
            # pandoc ansi header uppercase? Title sample: TITLE uppercase because input Title uppered? It output "TITLE" - yes header text uppercased
            # redo: header is uppercase plain text with bold codes around
            parts[-1]=ansi_header(b["c"][2],ctx)
        elif t in ("Para","Plain"):
            parts.append(ansi_inline(b["c"],ctx))
        elif t=="BulletList":
            lines=[]
            for item in b["c"]:
                txt=" ".join(ansi_inline(sub["c"],ctx) if sub.get("t") in ("Plain","Para") else "" for sub in item)
                lines.append(f"• {txt}")
            parts.append("\n".join(lines))
        elif t=="CodeBlock":
            parts.append(b["c"][1])
        else:
            parts.append(plain_block(b,ctx))
    return "\n\n".join([p for p in parts if p])

def ansi_header(inlines,ctx):
    txt=inlines_to_plain(inlines,ctx,"plain").upper()
    return f"\x1b[1m\x1b[23m\x1b[39m\x1b[49m\x1b[24m\x1b[29m{txt}\x1b[0m"
def ansi_inline(inlines,ctx,header=False):
    out=[]
    for n in inlines or []:
        t=n.get("t"); c=n.get("c")
        if t=="Strong": out.append(f"\x1b[1m\x1b[23m\x1b[39m\x1b[49m\x1b[24m\x1b[29m{ansi_inline(c,ctx)}\x1b[0m")
        elif t=="Emph": out.append(f"\x1b[22m\x1b[3m\x1b[39m\x1b[49m\x1b[24m\x1b[29m{ansi_inline(c,ctx)}\x1b[0m")
        elif t=="Code": out.append(f"\x1b[22m\x1b[23m\x1b[31m\x1b[47m\x1b[24m\x1b[29m {c[1]} \x1b[0m")
        elif t=="Str": out.append(c)
        elif t=="Space": out.append(" ")
        elif t=="SoftBreak": out.append(" ")
        elif t=="Link": out.append(ansi_inline(c[1],ctx))
        elif t=="Image": out.append(ansi_inline(c[1],ctx))
        elif t in ("Span",): out.append(ansi_inline(c[1],ctx))
        else: out.append(inlines_to_plain([n],ctx,"plain"))
    return "".join(out)

def write_ipynb(meta,blocks,ctx):
    # markdown content for whole doc
    md_ctx=WriterContext(ctx.opts, meta, "markdown"); md_ctx.fmt="markdown"
    md_text=write_markdown(blocks, md_ctx)
    # pandoc ipynb: source lines with trailing \n except last
    lines=md_text.split("\n")
    source=[l+"\n" for l in lines[:-1]]+[lines[-1]] if lines else []
    # cell id random uuid
    import uuid
    cell={"cell_type":"markdown","metadata":{},"source":source,"id":str(uuid.uuid4())}
    nb={"cells":[cell],"nbformat":4,"nbformat_minor":5,"metadata":{}}
    # metadata from meta: kernelspec etc if present ignore
    return json.dumps(nb, indent=1, ensure_ascii=False)

