def write_bbcode(blocks,ctx):
    def inl(inlines):
        out=[]
        for n in inlines or []:
            t=n.get("t"); c=n.get("c")
            if t=="Str": out.append(c)
            elif t=="Space": out.append(" ")
            elif t=="Strong": out.append(f"[b]{inl(c)}[/b]")
            elif t=="Emph": out.append(f"[i]{inl(c)}[/i]")
            elif t=="Underline": out.append(f"[u]{inl(c)}[/u]")
            elif t=="Code": out.append(f"[code]{c[1]}[/code]")
            elif t=="Link": out.append(f"[url={c[2][0]}]{inl(c[1])}[/url]")
            elif t=="Image": out.append(f"[img]{c[2][0]}[/img]")
            elif t in ("Span",): out.append(inl(c[1]))
            else: out.append(inlines_to_plain([n],ctx,"plain"))
        return "".join(out)
    parts=[]
    for b in blocks:
        if b.get("t")=="Header":
            txt=inl(b["c"][2]); parts.append(f"[u][b]{txt}[/b][/u]")
        elif b.get("t") in ("Para","Plain"): parts.append(inl(b["c"]))
        elif b.get("t")=="BulletList":
            lines=["[list]"]
            for item in b["c"]: lines.append("[*]"+" ".join(inl(sub["c"]) if sub.get("t") in ("Plain","Para") else "" for sub in item))
            lines.append("[/list]"); parts.append("\n".join(lines))
        else: parts.append(plain_block(b,ctx))
    return "\n\n".join(parts)

def write_zimwiki(blocks,ctx):
    parts=[]
    for b in blocks:
        if b.get("t")=="Header":
            lvl=b["c"][0]; txt=inlines_to_plain(b["c"][2],ctx,"plain")
            eq="="*(7-lvl)
            parts.append(f"{eq} {txt} {eq}")
        elif b.get("t") in ("Para","Plain"): parts.append(inlines_to_plain(b["c"],ctx,"plain"))
        else: parts.append(plain_block(b,ctx))
    return "\n\n".join(parts)

def write_context(blocks,ctx):
    # Handle headers as section levels: opening each header, closing all at end / before next same/higher
    parts=[]; open_levels=[]
    for b in blocks:
        if b.get("t")=="Header":
            lvl=b["c"][0]
            # close levels >= lvl
            while open_levels and open_levels[-1]>=lvl:
                parts.append(r"\stopsectionlevel"); open_levels.pop()
            txt=generic_inline(b["c"][2],ctx,"context")
            parts.append(f"\\startsectionlevel[title={{{txt}}},reference={{{b['c'][1][0]}}}]")
            open_levels.append(lvl)
        else:
            parts.append(generic_block(b,ctx,"context"))
    while open_levels:
        parts.append(r"\stopsectionlevel"); open_levels.pop()
    return "\n\n".join([p for p in parts if p])

