            else: out.append(f'<ref target="{xml_escape(url)}">{txt}</ref>')
        elif t=="Image":
            txt=db_inline(c[1],ctx,mode); src=c[2][0]
            if mode=="docbook": out.append(f'<inlinemediaobject>\n      <imageobject>\n        <imagedata fileref="{xml_escape(src)}" />\n      </imageobject>\n      <textobject>\n        <phrase>{txt}</phrase>\n      </textobject>\n    </inlinemediaobject>')
            elif mode=="jats":
                # mime subtype from extension
                ext=src.rsplit('.',1)[-1].lower() if '.' in src else ""
