def write_context(blocks,ctx):
    # Handle headers as section levels: opening each header, closing all at end / before next same/higher
    parts=[]; open_levels=[]
    for b in blocks:
        if b.get("t")=="Header":
            lvl=b["c"][0]
            # close levels >= lvl
            while open_levels and open_levels[-1]>=lvl:
                parts.append(r"\stopsectionlevel"); open_levels.pop()
            txt=generic_inline(b["c"][2],ctx,"context")
            parts.append(f"\\startsectionlevel[title={{{txt}}},reference={{{b['c'][1][0]}}}]")
            open_levels.append(lvl)
        else:
            parts.append(generic_block(b,ctx,"context"))
    while open_levels:
        parts.append(r"\stopsectionlevel"); open_levels.pop()
    return "\n\n".join([p for p in parts if p])

