def db_block(b,ctx,mode,indent=0):
    sp=" "*indent; t=b.get("t"); c=b.get("c")
    if t=="Para": return f"{sp}<para>\n{sp}  {db_inline(c,ctx,mode)}\n{sp}</para>" if mode=="docbook" else f"{sp}<p>{db_inline(c,ctx,mode)}</p>"
    if t=="Plain": return f"{sp}{db_inline(c,ctx,mode)}"
    if t=="Header":
        level,attr,inls=c
        if mode=="jats": return f"{sp}<sec><title>{db_inline(inls,ctx,mode)}</title></sec>"
        return f"{sp}<section><title>{db_inline(inls,ctx,mode)}</title></section>"
    if t=="CodeBlock":
        lang=c[0][1][0] if c[0][1] else ""
        canon=canonical_lang(lang) or lang
        if mode=="docbook": return f'{sp}<programlisting language="{canon}">\n{xml_escape(c[1])}\n{sp}</programlisting>'
        if mode=="jats": return f'{sp}<code language="{xml_escape(lang)}">{xml_escape(c[1])}</code>'
        return f"{sp}<eg>{xml_escape(c[1])}</eg>"
    if t=="BulletList":
        if mode=="jats":
            lines=[f"{sp}<list list-type=\"bullet\">"]
            for item in c:
                lines.append(f"{sp}  <list-item>")
                for sub in item: lines.append(f"{sp}    <p>{db_inline(sub['c'],ctx,mode) if sub.get('t') in ('Plain','Para') else ''}</p>")
                lines.append(f"{sp}  </list-item>")
            lines.append(f"{sp}</list>"); return "\n".join(lines)
        lines=[f"{sp}<itemizedlist spacing=\"compact\">"]
        for item in c:
            lines.append(f"{sp}  <listitem>")
            for sub in item:
                if sub.get("t") in ("Plain","Para"): lines.append(f"{sp}    <para>\n{sp}      {db_inline(sub['c'],ctx,mode)}\n{sp}    </para>")
                else: lines.append(db_block(sub,ctx,mode,indent+4))
            lines.append(f"{sp}  </listitem>")
        lines.append(f"{sp}</itemizedlist>"); return "\n".join(lines)
    if t=="OrderedList":
        lines=[f"{sp}<orderedlist>"]
        for item in c[1]:
            lines.append(f"{sp}  <listitem>")
            for sub in item: lines.append(db_block(sub,ctx,mode,indent+4))
            lines.append(f"{sp}  </listitem>")
        lines.append(f"{sp}</orderedlist>"); return "\n".join(lines)
    if t=="BlockQuote":
        inner="\n".join(db_block(x,ctx,mode,indent+2) for x in c)
        if mode=="jats": return f"{sp}<disp-quote>\n{inner}\n{sp}</disp-quote>"
        return f"{sp}<blockquote>\n{inner}\n{sp}</blockquote>"
    if t=="Table":
        header=c.get("header_inlines",[]); rows=c.get("row_inlines",[])
        if mode=="jats":
            lines=[f"{sp}<table-wrap>",f"{sp}  <table>",f"{sp}    <thead>",f"{sp}      <tr>"]
            for h in header: lines.append(f"{sp}        <th>{db_inline(h,ctx,mode)}</th>")
            lines.append(f"{sp}      </tr>"); lines.append(f"{sp}    </thead>"); lines.append(f"{sp}    <tbody>")
            for r in rows:
                lines.append(f"{sp}      <tr>")
                for cell in r: lines.append(f"{sp}        <td>{db_inline(cell,ctx,mode)}</td>")
                lines.append(f"{sp}      </tr>")
            lines.append(f"{sp}    </tbody>"); lines.append(f"{sp}  </table>"); lines.append(f"{sp}</table-wrap>"); return "\n".join(lines)
        # docbook informaltable
        ncol=len(header)
        lines=[f"{sp}<informaltable>",f"{sp}  <tgroup cols=\"{ncol}\">"]
        for a in c.get("aligns",[]): lines.append(f'{sp}    <colspec align="left" />')
        if header:
            lines.append(f"{sp}    <thead>"); lines.append(f"{sp}      <row>")
            for h in header: lines.append(f"{sp}        <entry>\n{sp}          {db_inline(h,ctx,mode)}\n{sp}        </entry>")
            lines.append(f"{sp}      </row>"); lines.append(f"{sp}    </thead>")
        lines.append(f"{sp}    <tbody>")
        for r in rows:
            lines.append(f"{sp}      <row>")
            for cell in r: lines.append(f"{sp}        <entry>\n{sp}          {db_inline(cell,ctx,mode)}\n{sp}        </entry>")
            lines.append(f"{sp}      </row>")
        lines.append(f"{sp}    </tbody>"); lines.append(f"{sp}  </tgroup>"); lines.append(f"{sp}</informaltable>"); return "\n".join(lines)
    if t=="HorizontalRule": return ""
    if t=="Div": return "\n".join(db_block(x,ctx,mode,indent) for x in c[1])
    if t=="Figure":
        return ""
    return ""

