def transform_blocks(blocks, opts):
    shift=opts.get("shift_heading_level_by",0)
    if opts.get("base_header_level") is not None:
        try: shift=int(opts["base_header_level"])-1
        except: pass
    if shift:
        def walk(blist):
            for b in blist:
                if b.get("t")=="Header":
                    lvl=b["c"][0]+shift
                    if lvl<1:
                        # becomes Para if <1? pandoc shift -1 on H1 gives Para? Check earlier: shift -1 on ## gave h1, # with -1 ? Probe mental: heading level 0 becomes Para
                        # We'll convert later
                        b["c"][0]=lvl
                    elif lvl>6: b["c"][0]=6
                    else: b["c"][0]=lvl
                # recurse
                c=b.get("c")
                if b.get("t") in ("BlockQuote",): walk(c)
                elif b.get("t")=="Div": walk(c[1])
                elif b.get("t")=="BulletList":
                    for it in c: walk(it)
                elif b.get("t")=="OrderedList":
                    for it in c[1]: walk(it)
        walk(blocks)
        # convert Header level <1 to Para, >6 stay?
        def conv(blist):
            for idx,b in enumerate(blist):
                if b.get("t")=="Header" and b["c"][0]<1:
                    blist[idx]=B("Para",b["c"][2])
        conv(blocks)
    return blocks

def render_body(meta, blocks, fmt_base, opts):
    ctx=WriterContext(opts, meta, fmt_base)
    ctx.fmt=fmt_base
    blocks=transform_blocks(json.loads(json.dumps(blocks, default=str)) if False else blocks, opts)  # careful tuples DefinitionList - json would break; our transform operates in place
    # Actually blocks may contain tuples for DefinitionList; in-place ok
    if fmt_base in ("html","html5"):
        return write_html(blocks, ctx), ctx
    if fmt_base=="html4":
        # html4 variant: use html writer then adjust some tags? footnote section div instead section, figure div...
        html_out=write_html(blocks,ctx)
        html_out=html_out.replace('<section id="footnotes" class="footnotes footnotes-end-of-document" role="doc-endnotes">','<div class="footnotes">')
        # closing section for footnotes only? risky - last </section>
        # figure to div.figure
        html_out=re.sub(r'<figure>\n(.*?)\n<figcaption aria-hidden="true">(.*?)</figcaption>\n</figure>', r'<div class="figure">\1\n<p class="caption">\2</p>\n</div>', html_out, flags=re.S)
        return html_out, ctx
    if fmt_base in ("latex","beamer"):
        return write_latex(blocks,ctx), ctx
    if fmt_base in ("markdown","markdown_github","markdown_mmd","markdown_phpextra","markdown_strict","commonmark","commonmark_x","gfm","markua","djot"):
        # djot has own generic but markdown-like
