    if fmt_base in ("org","asciidoc","asciidoc_legacy","asciidoctor","mediawiki","muse","textile","haddock","dokuwiki","typst","jira","context","man","ms","texinfo","bbcode","bbcode_fluxbb","bbcode_phpbb","bbcode_steam","bbcode_hubzilla","bbcode_xenforo","zimwiki","xwiki","vimdoc","tikiwiki","twiki","creole","fb2","icml","opml","chunkedhtml","s5","slidy","slideous","dzslides","revealjs","epub","epub2","epub3","docx","odt","pptx","pdf"):
        # some special:
