def write_bbcode(blocks,ctx):
    def inl(inlines):
        out=[]
        for n in inlines or []:
            t=n.get("t"); c=n.get("c")
            if t=="Str": out.append(c)
            elif t=="Space": out.append(" ")
            elif t=="Strong": out.append(f"[b]{inl(c)}[/b]")
            elif t=="Emph": out.append(f"[i]{inl(c)}[/i]")
            elif t=="Underline": out.append(f"[u]{inl(c)}[/u]")
            elif t=="Code": out.append(f"[code]{c[1]}[/code]")
            elif t=="Link": out.append(f"[url={c[2][0]}]{inl(c[1])}[/url]")
            elif t=="Image": out.append(f"[img]{c[2][0]}[/img]")
            elif t in ("Span",): out.append(inl(c[1]))
            else: out.append(inlines_to_plain([n],ctx,"plain"))
        return "".join(out)
    parts=[]
    for b in blocks:
        if b.get("t")=="Header":
            txt=inl(b["c"][2]); parts.append(f"[u][b]{txt}[/b][/u]")
        elif b.get("t") in ("Para","Plain"): parts.append(inl(b["c"]))
        elif b.get("t")=="BulletList":
            lines=["[list]"]
            for item in b["c"]: lines.append("[*]"+" ".join(inl(sub["c"]) if sub.get("t") in ("Plain","Para") else "" for sub in item))
            lines.append("[/list]"); parts.append("\n".join(lines))
        else: parts.append(plain_block(b,ctx))
    return "\n\n".join(parts)

def write_zimwiki(blocks,ctx):
