        # Simple flat/nested by level using stack
        # Output observed pandoc TOC formatting ... implement nested lists
        lines=[]
        # build tree
        root=[]; stack=[(0,root)]
        for h in headers:
            lvl=h["c"][0]; node={"header":h,"children":[]}
            while stack and stack[-1][0]>=lvl: stack.pop()
            stack[-1][1].append(node); stack.append((lvl,node["children"]))
        def render_nodes(nodes, indent=0):
            lines=[]
            lines.append("<ul>")
            for nd in nodes:
                h=nd["header"]; lvl,attr,inls=h["c"]
                txt=html_inline(inls, WriterContext(opts,{}, "html"))
                if opts.get("number_sections"):
                    num=opts.get("_toc_num",{}).get(id(h),"")
                    if num: txt=f'<span class="header-section-number">{num}</span> '+txt
                link=f'<a href="#{opts.get("id_prefix","")}{attr[0]}">{txt}</a>'
                if nd["children"]:
                    lines.append(f"<li>{link}")
                    lines.extend(render_nodes(nd["children"]))
                    lines.append("</li>")
                else:
                    lines.append(f"<li>{link}</li>")
            lines.append("</ul>")
            return lines
        if not headers: return ""
        return "\n".join(render_nodes(root))
    else:
        # plain/markdown toc list lines with links?
        lines=[]
        for h in headers:
            lvl,attr,inls=h["c"]
            txt=inlines_to_plain(inls,None,"plain")
            indent="  "*(lvl-1)
            if fmt.startswith("markdown"):
                lines.append(f"{indent}- [{txt}](#{attr[0]})")
            else:
                lines.append(f"{indent}{txt}")
