def build_template_context(meta, blocks, body, opts, fmt_base, input_filename=None):
    ctx={}
    # variables first
    for k,v in opts.get("variables",{}).items():
        ctx[k]=v
    # variables-json already merged as parsed json values into variables by CLI
    fmtd = fmt_base
    # format context for meta rendering
    dummy_ctx=WriterContext(opts,meta,fmt_base)
    # meta keys
    for k,v in meta.items():
        if k in ctx: continue
        if isinstance(v,dict) and v.get("t")=="MetaList":
            ctx[k]=[meta_value_to_string(x,fmtd,dummy_ctx) for x in v["c"]]
        elif isinstance(v,dict) and v.get("t")=="MetaBool":
            ctx[k]=v["c"]
        else:
            ctx[k]=meta_value_to_string(v,fmtd,dummy_ctx)
    # authors special lists
    if "author" in meta:
        ctx["author"]=meta_value_to_list(meta["author"],fmtd,dummy_ctx)
    if "author" in opts.get("variables",{}):
        av=opts["variables"]["author"]; ctx["author"]=[av] if isinstance(av,str) else av
    # author-meta from meta only
    if "author" in meta:
        ctx["author-meta"]=meta_value_to_list(meta["author"],"plain",dummy_ctx)
    if "date" in meta:
        ctx["date-meta"]=meta_value_to_string(meta["date"],"plain",dummy_ctx)
    # keywords could be MetaList or string split?
    if "keywords" in meta:
        if isinstance(meta["keywords"],dict) and meta["keywords"].get("t")=="MetaList":
            ctx["keywords"]=meta_value_to_list(meta["keywords"],"plain",dummy_ctx)
        else:
            s=meta_value_to_string(meta["keywords"],"plain",dummy_ctx)
            ctx["keywords"]=[x.strip() for x in s.split(",")] if s else []
    if "description" in meta:
        ctx["description-meta"]=meta_value_to_string(meta["description"],"plain",dummy_ctx)
    if "abstract" in meta:
        # abstract as formatted blocks/inlines
        av=meta["abstract"]
        if av.get("t")=="MetaBlocks":
            ctx["abstract"]="\n\n".join(plain_block(b,dummy_ctx) if fmtd!="html" else html_block(b,dummy_ctx) for b in av["c"])
        else:
            ctx["abstract"]=meta_value_to_string(av,fmtd,dummy_ctx)
        ctx["abstract-title"]=ctx.get("abstract-title","Abstract")
    # pagetitle
    if "pagetitle" not in ctx:
        if "title" in meta:
            ctx["pagetitle"]=meta_value_to_string(meta["title"],"plain",dummy_ctx)
        elif input_filename and input_filename not in ("-",""):
            base=os.path.basename(input_filename)
            name=os.path.splitext(base)[0]
            ctx["pagetitle"]=name if name else "-"
        else:
            ctx["pagetitle"]="-"
    else:
        # variable pagetitle may be string keep
        pass
    # title-prefix
    if opts.get("title_prefix"): ctx["title-prefix"]=opts["title_prefix"]
    ctx["body"]=body
    ctx["idprefix"]=opts.get("id_prefix","")
    if opts.get("css"): ctx["css"]=opts["css"] if isinstance(opts["css"],list) else [opts["css"]]
    if opts.get("include_in_header"): ctx["header-includes"]=opts["include_in_header"]
    if opts.get("include_before_body"): ctx["include-before"]=opts["include_before_body"]
    if opts.get("include_after_body"): ctx["include-after"]=opts["include_after_body"]
    if opts.get("toc"):
        ctx["toc"]=True
        ctx["table-of-contents"]=build_toc(blocks,opts,fmt_base)
    ctx["toc-depth"]=opts.get("toc_depth",3)
    ctx["lof"]=opts.get("lof",False); ctx["lot"]=opts.get("lot",False)
    if opts.get("number_sections"):
        ctx["numbersections"]=True; ctx["number-sections"]=True
    # document-css default for html styles
    if "document-css" not in ctx:
        ctx["document-css"]=True
    # latex defaults
    if fmt_base in ("latex","beamer"):
        ctx.setdefault("documentclass","article" if fmt_base=="latex" else "beamer")
        # pandoc context variables hyphenation etc
    if "lang" in meta and "lang" not in opts.get("variables",{}):
        ctx["lang"]=meta_value_to_string(meta["lang"],"plain",dummy_ctx)
    # math variable for html
    if opts.get("math_method")=="mathjax":
        ctx["math"]='<script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml-full.js" type="text/javascript"></script>'
    elif opts.get("math_method")=="katex":
        ctx["math"]='<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css">'
    # titleblock
    if fmt_base in ("markdown","markdown_github","markdown_mmd","markdown_phpextra","markdown_strict","commonmark","commonmark_x","gfm","plain"):
        if meta:
            if fmt_base=="plain":
                lines=[]
                if "title" in meta: lines.append(meta_value_to_string(meta["title"],"plain",dummy_ctx))
                if "author" in meta:
                    for a in meta_value_to_list(meta["author"],"plain",dummy_ctx): lines.append(a)
                if "date" in meta: lines.append(meta_value_to_string(meta["date"],"plain",dummy_ctx))
                ctx["titleblock"]="\n".join(lines)
            else:
                # YAML front matter
                yaml_lines=["---"]
                for k in sorted(meta.keys()):
                    v=meta[k]
                    if isinstance(v,dict) and v.get("t")=="MetaList":
                        yaml_lines.append(f"{k}:")
                        for item in v["c"]: yaml_lines.append(f"- {meta_value_to_string(item,'plain',dummy_ctx)}")
                    elif isinstance(v,dict) and v.get("t")=="MetaBool":
                        yaml_lines.append(f"{k}: {'true' if v['c'] else 'false'}")
                    else:
                        yaml_lines.append(f"{k}: {meta_value_to_string(v,'plain',dummy_ctx)}")
                yaml_lines.append("---")
                ctx["titleblock"]="\n".join(yaml_lines)
    if fmt_base=="rst":
        if "title" in meta:
            title_plain=meta_value_to_string(meta["title"],"plain",dummy_ctx)
            ctx["titleblock"]="="*len(title_plain)+"\n"+title_plain+"\n"+"="*len(title_plain)
    return ctx

def standalone_html(meta,blocks,body,opts,input_filename=None):
    ctx=build_template_context(meta,blocks,body,opts,"html",input_filename)
    # Build manually to match template
    lines=[]
    lang=ctx.get("lang","") if isinstance(ctx.get("lang"),str) else ""
    dirv=ctx.get("dir","") if isinstance(ctx.get("dir"),str) else ""
    lines.append("<!DOCTYPE html>")
    html_tag='<html xmlns="http://www.w3.org/1999/xhtml"'
    if lang: html_tag+=f' lang="{escape_html_attr(str(lang))}" xml:lang="{escape_html_attr(str(lang))}"'
    if dirv: html_tag+=f' dir="{escape_html_attr(str(dirv))}"'
    html_tag+=">"
    lines.append(html_tag)
    lines.append("<head>")
    lines.append('  <meta charset="utf-8" />')
    lines.append('  <meta name="generator" content="pandoc" />')
    lines.append('  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />')
    for a in ctx.get("author-meta",[]):
        lines.append(f'  <meta name="author" content="{escape_html_attr(a)}" />')
    if ctx.get("date-meta"):
        lines.append(f'  <meta name="dcterms.date" content="{escape_html_attr(str(ctx["date-meta"]))}" />')
    if ctx.get("keywords"):
        kw=", ".join(ctx["keywords"]) if isinstance(ctx["keywords"],list) else str(ctx["keywords"])
        lines.append(f'  <meta name="keywords" content="{escape_html_attr(kw)}" />')
    if ctx.get("description-meta"):
        lines.append(f'  <meta name="description" content="{escape_html_attr(str(ctx["description-meta"]))}" />')
    title_prefix=ctx.get("title-prefix","")
    pagetitle=ctx.get("pagetitle","-")
    title_text=f"{title_prefix} – {pagetitle}" if title_prefix else str(pagetitle)
    lines.append(f"  <title>{escape_html(title_text)}</title>")
    lines.append("  <style>")
    # styles partial rendered
    styles_tmpl=DATA.get("data_files",{}).get("templates/styles.html",{}).get("out","")
    styles_rendered=template_render(styles_tmpl, ctx) if styles_tmpl else ""
    # also citations style if needed? template has $styles.citations.html()$? Actually styles.html includes? It's separate conditional; html template only styles.html
    for l in styles_rendered.rstrip("\n").split("\n"):
        lines.append("    "+l if l else "")
    lines.append("  </style>")
    for css in ctx.get("css",[]) or []:
        lines.append(f'  <link rel="stylesheet" href="{escape_html_attr(str(css))}" />')
    for hi in ctx.get("header-includes",[]) or []:
        lines.append("  "+str(hi))
    if ctx.get("math"):
        lines.append("  "+str(ctx["math"]))
    lines.append("</head>")
    lines.append("<body>")
    for ib in ctx.get("include-before",[]) or []:
        lines.append(str(ib))
    if ctx.get("title"):
        lines.append('<header id="title-block-header">')
        lines.append(f'<h1 class="title">{ctx["title"]}</h1>')
        if ctx.get("subtitle"):
            lines.append(f'<p class="subtitle">{ctx["subtitle"]}</p>')
        author_list=ctx.get("author",[])
        if isinstance(author_list,str): author_list=[author_list]
        for a in author_list or []:
            lines.append(f'<p class="author">{a}</p>')
        if ctx.get("date"):
            lines.append(f'<p class="date">{ctx["date"]}</p>')
        if ctx.get("abstract"):
            lines.append('<div class="abstract">')
            lines.append(f'<div class="abstract-title">{ctx.get("abstract-title","Abstract")}</div>')
            lines.append(str(ctx["abstract"]))
            lines.append('</div>')
        lines.append('</header>')
    if ctx.get("toc"):
        idp=ctx.get("idprefix","")
        lines.append(f'<nav id="{idp}TOC" role="doc-toc">')
        if ctx.get("toc-title"):
            lines.append(f'<h2 id="{idp}toc-title">{ctx["toc-title"]}</h2>')
        lines.append(ctx.get("table-of-contents",""))
        lines.append('</nav>')
    if body:
        lines.append(body)
    for ia in ctx.get("include-after",[]) or []:
        lines.append(str(ia))
    lines.append("</body>")
    lines.append("</html>")
    return "\n".join(lines)

def apply_standalone(meta,blocks,body,opts,fmt_base,input_filename=None):
    if fmt_base in ("html","html5"):
        return standalone_html(meta,blocks,body,opts,input_filename)
    if fmt_base=="html4":
        # use html template for html4 from DATA - simplified manual based on html but with html4 doctype etc: Use template_render
        tmpl=DATA.get("templates",{}).get("html4",{}).get("out")
        if tmpl:
            ctx=build_template_context(meta,blocks,body,opts,fmt_base,input_filename)
            return template_render(tmpl,ctx)
        return standalone_html(meta,blocks,body,opts,input_filename)
    if fmt_base in ("native","json","xml","ipynb"):
        return body
    # templates from DATA
    tmpl_entry=DATA.get("templates",{}).get(fmt_base)
    if not tmpl_entry or tmpl_entry.get("code")!=0:
        return body
    tmpl=tmpl_entry["out"]
    ctx=build_template_context(meta,blocks,body,opts,fmt_base,input_filename)
    # partials dict
    partials={}
    for name,df in DATA.get("data_files",{}).items():
        partials[name]=df.get("out","")
        # strip templates/ prefix
        if name.startswith("templates/"): partials[name[len("templates/"):]]=df.get("out","")
    return template_render(tmpl,ctx,partials)

