def parse_bool_opt(value, dest, long_name):
    if value is None: return True
    v=str(value).lower()
    if v in ("true","t","yes","1"): return True
    if v in ("false","f","no","0"): return False
    raise OptError(f"Argument of --{long_name} must be either true or false\n",6)

def resolve_long(name):
    # exact
    if name in LONG_OPTS:
        return LONG_OPTS[name], False
    # abbreviation: candidates where long startswith name
    cands=[v for k,v in LONG_OPTS.items() if k.startswith(name)]
    # unique by dest+definition? If multiple distinct defs, ambiguous
    # Deduplicate by (long)
    uniq={}
    for c in cands: uniq[c[1]]=c
    cands=list(uniq.values())
    if len(cands)==1:
        return cands[0], True
    if len(cands)>1:
        # Build ambiguous message as pandoc: list candidates lines formatted from help? Need reproduce shape for common --ver case.
        # Format: option `--ver' is ambiguous; could be one of:\n      --verbose  \n  -v  --version  \nTry ...
        # We construct from help text lines containing long: search DATA help for lines containing candidate long/short?
        lines=[]
        help_text=DATA.get("help","")
        help_lines=help_text.split("\n")
        for cand in cands:
            # find line in help that contains --long
            found=None
            for hl in help_lines:
                if f"--{cand[1]}" in hl:
                    found=hl.strip()
                    # help lines may contain multiple opts; trim? pandoc shows segment for that opt: e.g. "    --verbose" and "  -v  --version"
                    # Use full segment simplified: replicate pandoc format: two columns?
                    break
            # Pandoc GetOpt formatting: prints each option with its short/long and arg placeholder padded.
            # We'll produce approximate using found line truncated to candidate part
            if found:
                # Split found by two+ spaces? We'll try reconstruct from OPTION help segment: take portion up to next 2+ spaces after candidate arg?
                lines.append("      "+found)  # approximate
            else:
                lines.append(f"      --{cand[1]}")
        # Special exact handling for common ambiguous prefixes we know formatting for: --v and --ver
        msg=f"option `--{name}' is ambiguous; could be one of:\n"
        for cand in cands:
            # reconstruct in pandoc style: find canonical line from stored ambiguous templates for v/ver?
            msg+=format_ambiguous_candidate(cand)+"\n"
        msg+=f"Try {prog_name()} --help for more information.\n"
