def format_ambiguous_candidate(cand):
    short,long_,arg,dest=cand
    # pandoc format: "      --verbose  " or "  -v  --version  " etc padded to 24? Observed for --v:
    # "  -V KEY[:VALUE]  --variable=KEY[:VALUE]      \n                  --variable-json=KEY[:JSON]  \n                  --verbose                   \n  -v              --version                   "
    # Complex. For --ver case: "      --verbose  \n  -v  --version  "
    # Use a simplified pattern approximating: if short: "  -x  --long" plus arg placeholder if req
    placeholder=""
    # find arg name from help? approximate based dest
    arg_names={"variable":"KEY[:VALUE]","variable_json":"KEY[:JSON]"}
    if dest in arg_names: placeholder=" "+arg_names[dest]
    elif arg=="req": placeholder=" FORMAT" if dest in ("from","to") else " FILE" if dest=="output" else " ARG"
    if short:
        return f"  -{short}  --{long_}{placeholder}  "
    else:
        return f"      --{long_}{placeholder}  "

def parse_args(argv):
    opts={}
    opts["_list_metadata"]=[]  # ordered metadata additions
    opts["_list_variables"]=[]
    opts["_list_variables_json"]=[]
    opts["_css"]=[]
    opts["_bibliography"]=[]
