    opts["_pdf_engine_opt"]=[]
    opts["_syntax_definition"]=[]
    files=[]
    i=0
    info_action=None  # dict
    ignore_args=False
    dump_args=False
    while i<len(argv):
        arg=argv[i]
        if ignore_args:
            files.append(arg); i+=1; continue
        if arg=="--":
            files.extend(argv[i+1:]); break
        if arg.startswith("--") and len(arg)>2:
            body=arg[2:]
            if "=" in body:
                name,value=body.split("=",1); has_value=True
            else:
