def wrap_output_text(text, columns, wrap_mode, fmt):
    if wrap_mode!="auto": return text
    if fmt in ("native","json","xml","ipynb"): return text
    # For each line, if too long, wrap using textwrap preserving indent, not breaking long words/hyphens.
    # But for code blocks/latex commands, wrapping may break incorrectly; Pandoc wraps only paragraphs - our output lines are mostly paragraphs lines.
    # We apply per line with exceptions: lines starting with \begin, \end, <pre, code blocks etc - we need track? Simple: skip wrapping if line contains <pre or starts with four spaces or is inside verbatim (can't track easily)
    out_lines=[]
    in_pre=False
    for line in text.split("\n"):
        if "<pre" in line: in_pre=True
        if "</pre>" in line: in_pre=False
            # fallthrough wrap maybe after?
        if in_pre or line.strip().startswith("\\begin{verbatim}") or line.strip().startswith("    "):
            out_lines.append(line); continue
        if len(line)<=columns:
            out_lines.append(line); continue
        # Determine indent
        indent_match=re.match(r'^(\s*)', line)
        indent=indent_match.group(1) if indent_match else ""
        # textwrap: break on spaces (also html tags contain spaces - it will break there)
        wrapped=textwrap.wrap(line, width=columns, initial_indent="", subsequent_indent=indent, break_long_words=False, break_on_hyphens=False, expand_tabs=False)
        if wrapped:
            out_lines.extend(wrapped)
        else:
            out_lines.append(line)
    return "\n".join(out_lines)

def apply_ascii(text, fmt):
    if fmt in ("html","html5","html4"):
        out=""
        for ch in text:
            if ord(ch)>127:
                out+=f"&#x{ord(ch):X};"
            else: out+=ch
        return out
    elif fmt in ("latex","beamer"):
        # Use latex escapes for common accents: implement encode via unicodedata decompose to \' etc for letters
        out=""
        for ch in text:
            if ord(ch)<128: out+=ch; continue
            # use replacements from latex_escape for known punctuation
            repl={"—":"---","–":"--","…":r"\ldots{}","“":"``","”":"''","‘":"`","’":"'","©":r"\copyright{}"}
            if ch in repl: out+=repl[ch]; continue
            decomp=unicodedata.normalize("NFD",ch)
            if len(decomp)==2 and decomp[1] in "̧́̀̈̃̂":
                accent={"́":r"\'","̀":r"\`","̈":r'\"',"̃":r"\~","̂":r"\^","̧":r"\c"}[decomp[1]]
                out+=f"{accent}{{{decomp[0]}}}"
            else: out+=ch
        return out
    else:
        # markdown/plain etc: named entities
        import html.entities
        out=""
        for ch in text:
            if ord(ch)<128: out+=ch; continue
            name=html.entities.codepoint2name.get(ord(ch))
            if fmt.startswith("markdown"):
                # pandoc conversions for smart punctuation back to ascii syntax
                specials={"—":"---","–":"--","…":"...","“":'"',"”":'"',"‘":"'","’":"'"}
                if ch in specials: out+=specials[ch]; continue
                if name:
                    # © becomes &COPY; upper? python name 'copy' -> pandoc &COPY; maybe entities are case ... Use name but uppercase for copy?
                    if name=="copy": out+="&COPY;"
                    else: out+=f"&{name};"
                else: out+=f"&#x{ord(ch):X};"
            else:
                if name: out+=f"&{name};"
                else: out+=f"&#x{ord(ch):X};"
        return out

def read_binary_document(path, fmt):
    # minimal docx/epub/odt reading
    import zipfile
    meta={}; blocks=[]
    try:
        if fmt=="docx":
            with zipfile.ZipFile(path) as z:
                xml_text=z.read("word/document.xml").decode()
            # parse xml text:p etc
            blocks=parse_docx_xml(xml_text)
            return meta,blocks
        elif fmt in ("epub","epub3","epub2"):
            with zipfile.ZipFile(path) as z:
                # find html files
                for name in z.namelist():
                    if name.endswith((".xhtml",".html",".htm")):
                        txt=z.read(name).decode(errors="replace")
                        blocks.extend(parse_html_to_blocks(txt, default_format_options("html")))
            return meta,blocks
        elif fmt=="odt":
            with zipfile.ZipFile(path) as z:
                xml_text=z.read("content.xml").decode()
            # strip tags paragraphs
            txt=re.sub(r'<text:(p|h)[^>]*>', "\n\n", xml_text)
            txt=re.sub(r'<[^>]+>', '', txt)
            parser=MarkdownParser(options=default_format_options("markdown")); return parser.meta, parser.parse(htmlmod.unescape(txt))
    except Exception as e:
        raise PandocError(str(e),1)
    return meta,blocks

def parse_docx_xml(xml_text):
    # namespaces generic: extract w:p elements
    blocks=[]
    # split paragraphs
    paras=re.findall(r'<w:p[^>]*>(.*?)</w:p>', xml_text, re.S)
    for para in paras:
        style_m=re.search(r'<w:pStyle w:val="([^"]+)"', para)
        style=style_m.group(1) if style_m else ""
        runs=re.findall(r'<w:r[^>]*>(.*?)</w:r>', para, re.S)
        inlines=[]
        for run in runs:
            texts=re.findall(r'<w:t[^>]*>([^<]*)</w:t>', run)
            txt="".join(texts)
            if not txt: continue
            bold="<w:b" in run; italic="<w:i" in run
            inls=InlineParser(options=default_format_options("markdown")).parse(htmlmod.unescape(txt))
            if bold: inls=[I("Strong",inls)]
            if italic: inls=[I("Emph",inls)]
            inlines.extend(inls)
            inlines.append(I("Space"))
        inlines=trim_inlines(inlines)
        if style.lower().startswith("heading"):
            m=re.search(r'(\d+)', style); lvl=int(m.group(1)) if m else 1
            attr=clone_attr(EMPTY_ATTR); attr[0]=generate_identifier(inline_text(inlines))
            blocks.append(B("Header",[lvl,attr,inlines]))
        else:
            if inlines: blocks.append(B("Para",inlines))
    return blocks

