def handle_info_actions(opts, argv_original):
    # returns True if handled
    prog=prog_name()
    if opts.get("help"):
        print_help(); return True
    if opts.get("version"):
        sys.stdout.write(version_text(full=not opts.get("_version_short",False))); return True
    if opts.get("bash_completion"):
        sys.stdout.write(DATA.get("bash","")); return True
    if opts.get("list_input_formats"):
        sys.stdout.write("\n".join(DATA.get("input_formats",[]))+"\n"); return True
    if opts.get("list_output_formats"):
        sys.stdout.write("\n".join(DATA.get("output_formats",[]))+"\n"); return True
    if opts.get("list_extensions") is not None and "list_extensions" in opts:
        val=opts["list_extensions"]
        if val is True:
            sys.stdout.write(DATA.get("extensions_default","")); return True
        else:
            fmt=str(val).lower()
            entry=DATA.get("extensions",{}).get(fmt)
            if not entry or entry.get("code")!=0:
                err=entry.get("err") if entry else f"{fmt} is not a recognized reader or writer format\n"
                eprint(err); sys.exit(6)
            sys.stdout.write(entry.get("out","")); return True
    if opts.get("list_highlight_languages"):
        sys.stdout.write("\n".join(DATA.get("hl_languages",[]))+"\n"); return True
    if opts.get("list_highlight_styles"):
        sys.stdout.write("\n".join(DATA.get("hl_styles_list",[]))+"\n"); return True
    if "print_default_template" in opts:
        fmt=str(opts["print_default_template"]).lower()
        entry=DATA.get("templates",{}).get(fmt)
        if entry and entry.get("code")==0:
            sys.stdout.write(entry.get("out","")); return True
        else:
            eprint(f"Could not find data file templates/default.{fmt}\n"); sys.exit(97)
    if "print_default_data_file" in opts:
        name=str(opts["print_default_data_file"])
        df=DATA.get("data_files",{}).get(name)
        if df and df.get("code")==0:
            # write as bytes preserving surrogate escapes
            sys.stdout.buffer.write(df.get("out","").encode(errors="surrogateescape")); return True
        else:
            eprint(f"Could not find data file {name}\n"); sys.exit(97)
    if "print_highlight_style" in opts:
        name=str(opts["print_highlight_style"])
        entry=DATA.get("hl_styles",{}).get(name)
        if entry and entry.get("code")==0:
            sys.stdout.write(entry.get("out","")); return True
        # if file path exists, maybe read? pandoc tries style file
        if os.path.exists(name):
            sys.stdout.write(open(name).read()); return True
        eprint(f"Unknown highlight-style {name}\n"); sys.exit(6)
    return False

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    prog=get_prog()
    # Server / lua modes based on prog name or first arg
    base_prog=os.path.basename(sys.argv[0])
    if base_prog in ("pandoc-server",):
        return run_server(argv)
    if base_prog=="pandoc-server.cgi":
        return run_cgi(argv)
    if base_prog in ("pandoc-lua",):
        return run_lua(argv)
    if argv and argv[0]=="server":
        return run_server(argv[1:])
    if argv and argv[0]=="lua":
        return run_lua(argv[1:])
    # Original pandoc checks argv exactly? Handle
    try:
        opts, files = parse_args(argv)
    except OptError as e:
        eprint(e.msg); return e.code
    # dump-args
    if opts.get("dump_args"):
        out=opts.get("output","-")
        sys.stdout.write(out+"\n")
        if files:
            for f in files: sys.stdout.write(f+"\n")
        else:
            sys.stdout.write("-\n")
        return 0
    # info actions - check presence (note parse_args for list_extensions True/false confusion)
    # Need determine if any info key in opts: version/help stored as True
    info_keys=["help","version","bash_completion","list_input_formats","list_output_formats","list_highlight_languages","list_highlight_styles","print_default_template","print_default_data_file","print_highlight_style"]
    has_info=any(k in opts for k in info_keys) or "list_extensions" in opts
    if has_info:
        try:
            if handle_info_actions(opts, argv):
                return 0
        except SystemExit as e:
            return int(e.code or 0)
    # defaults
    try:
        if "defaults" in opts:
            opts=load_defaults_file(opts["defaults"], opts, files)
        validate_and_normalize_opts(opts)
    except OptError as e:
        eprint(e.msg); return e.code
    except PandocError as e:
        eprint(e.msg+"\n" if not e.msg.endswith("\n") else e.msg); return e.code
    # trace/verbose/quiet are no-ops except trace parsing messages later
    # Determine output and formats
    output_file=opts.get("output")
    from_spec=opts.get("from")
    to_spec=opts.get("to")
    # Guess input format if not specified
    input_filename=None
    if files:
        input_filename=files[0] if files[0]!="-" else None
    warnings=[]
    if not from_spec:
        if files and files[0]!="-":
            guessed=guess_format_from_filename(files[0], is_output=False)
            if guessed:
                from_spec=guessed
            else:
                # if extension present but unknown, warning
                if os.path.splitext(files[0])[1]:
                    warnings.append(f"[WARNING] Could not deduce format from file extension \n  Defaulting to markdown\n")
                from_spec="markdown"
        else:
            from_spec="markdown"
    if not to_spec:
        if output_file and output_file!="-":
            guessed=guess_format_from_filename(output_file, is_output=True)
            if guessed: to_spec=guessed
            else: to_spec="html"
        else:
            to_spec="html"
    # Validate formats
    from_base, from_mods = parse_format_spec(from_spec)
    to_base, to_mods = parse_format_spec(to_spec)
    from_base_lower=from_base.lower(); to_base_lower=to_base.lower()
    # aliases list check: input formats includes html but not html5 - pandoc allows html5 as input alias?
    input_list=[x.lower() for x in DATA.get("input_formats",[])]
    output_list=[x.lower() for x in DATA.get("output_formats",[])]
    # alias additions
    if from_base_lower in ("html5","html4"): from_base_lower="html"
    if to_base_lower=="html5": to_base_lower="html5"  # keep in output list
    if from_base_lower not in input_list and from_base_lower not in ("html",):
        eprint(f"Unknown input format {from_spec}\n"); return 21
    if to_base_lower not in output_list:
        eprint(f"Unknown output format {to_spec}\n"); return 22
    # extension validation
    for base_lower, mods, spec in [(from_base_lower, from_mods, from_spec),(to_base_lower, to_mods, to_spec)]:
        if mods:
            entry=DATA.get("extensions",{}).get(base_lower)
            supported=set()
            if entry and entry.get("code")==0:
                for line in entry.get("out","").splitlines():
                    if line.startswith("+") or line.startswith("-"): supported.add(line[1:])
            for sign,ext in mods:
                if supported and ext not in supported:
                    eprint(f"The extension {ext} is not supported for {base_lower}.\nUse --list-extensions={base_lower} to list supported extensions.\n"); return 23
