def run_server(args):
    # Minimal pandoc-server: HTTP server with JSON API
    # Usage: pandoc-server [--port PORT] etc? Default port 3030?
    port=3030
    i=0
    while i<len(args):
        if args[i]=="--port" and i+1<len(args): port=int(args[i+1]); i+=2; continue
        if args[i].startswith("--port="): port=int(args[i].split("=",1)[1])
        i+=1
    from http.server import BaseHTTPRequestHandler, HTTPServer
    class Handler(BaseHTTPRequestHandler):
        def do_POST(self):
            length=int(self.headers.get('Content-Length',0))
            data=self.rfile.read(length) if length else b"{}"
            try:
                req=json.loads(data.decode())
                text=req.get("text","")
                from_fmt=req.get("from","markdown"); to_fmt=req.get("to","html")
                meta,blocks=read_document(text, from_fmt)
                body,ctx=render_body(meta,blocks, parse_format_spec(to_fmt)[0].lower(), {})
                if req.get("standalone"):
                    body=apply_standalone(meta,blocks,body,{"variables":{}}, parse_format_spec(to_fmt)[0].lower(), None)
                self.send_response(200); self.send_header("Content-Type","text/plain; charset=utf-8"); self.end_headers(); self.wfile.write(body.encode())
            except Exception as e:
                self.send_response(400); self.end_headers(); self.wfile.write(str(e).encode())
        def do_GET(self):
            self.send_response(200); self.send_header("Content-Type","text/plain"); self.end_headers(); self.wfile.write(b"pandoc server\n")
        def log_message(self,format,*args): pass
    server=HTTPServer(("localhost",port),Handler)
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    return 0

def run_cgi(args):
    # Read CONTENT_LENGTH etc - simplified stdin JSON
    length=int(os.environ.get("CONTENT_LENGTH","0") or 0)
    data=sys.stdin.buffer.read(length) if length else sys.stdin.buffer.read()
    print("Content-Type: text/plain\r")
    print("\r")
    try:
        req=json.loads(data.decode())
        meta,blocks=read_document(req.get("text",""), req.get("from","markdown"))
        body,ctx=render_body(meta,blocks, parse_format_spec(req.get("to","html"))[0].lower(), {})
        sys.stdout.write(body)
    except Exception as e:
        sys.stdout.write(str(e))
    return 0

def run_lua(args):
    # Minimal lua interpreter invocation: support -e stat, -v, script file with args, -i interactive (read stdin lines evaluate?)
    # Use MiniLua if available else basic handling for print statements
    if "-v" in args:
        sys.stdout.write("Lua 5.4.6  Copyright (C) 1994-2022 Lua.org, PUC-Rio\n"); return 0
    # collect -e
    code_parts=[]; script=None; script_args=[]
    i=0
    interactive=False
    while i<len(args):
        a=args[i]
        if a=="-e" and i+1<len(args): code_parts.append(args[i+1]); i+=2; continue
        if a=="-i": interactive=True; i+=1; continue
        if a=="-l" and i+1<len(args): i+=2; continue
        if a in ("-E","-W"): i+=1; continue
        if a.startswith("-") and a not in ("-","--"):
            # unknown option: pandoc lua error format
            eprint(f"{prog_name()}: user error (unrecognized option `{a}'\nUsage: pandoc lua [options] [script [args]]\n  -e stat    execute string 'stat'\n  -i         interactive mode\n  -l mod     require library 'mod' into global 'mod';\n             if 'mod' has the pattern 'g=module', then\n             require library 'module' into global 'g'\n  -v         show version information\n  -E         ignore environment variables -- partially supported\n  -W         turn warnings on -- currently not supported\n)\n")
            return 1
        else:
            script=a; script_args=args[i+1:]; break
    # Set globals PANDOC_VERSION etc in mini lua
    try:
        lua=MiniLuaInterpreter()
        for code in code_parts:
            lua.execute(code)
        if script and script!="-":
            if not os.path.exists(script):
                eprint(f"{prog_name()}: cannot open {script}: No such file or directory\n"); return 1
            lua.execute(open(script).read())
        elif script=="-":
            lua.execute(sys.stdin.read())
        if interactive:
            # read lines and execute each
            for line in sys.stdin:
                try: lua.execute(line)
                except Exception as e: eprint(str(e)+"\n")
        elif not code_parts and not script:
            # no script and not interactive: read stdin as script? Standalone lua without args enters interactive if tty else executes stdin?
            if not sys.stdin.isatty():
                data=sys.stdin.read()
                if data.strip(): lua.execute(data)
    except Exception as e:
        eprint(str(e)+"\n"); return 1
    return 0

