def run_server(args):
    # Minimal pandoc-server: HTTP server with JSON API
    # Usage: pandoc-server [--port PORT] etc? Default port 3030?
    port=3030
    i=0
    while i<len(args):
        if args[i]=="--port" and i+1<len(args): port=int(args[i+1]); i+=2; continue
        if args[i].startswith("--port="): port=int(args[i].split("=",1)[1])
        i+=1
    from http.server import BaseHTTPRequestHandler, HTTPServer
    class Handler(BaseHTTPRequestHandler):
        def do_POST(self):
            length=int(self.headers.get('Content-Length',0))
            data=self.rfile.read(length) if length else b"{}"
            try:
                req=json.loads(data.decode())
                text=req.get("text","")
                from_fmt=req.get("from","markdown"); to_fmt=req.get("to","html")
                meta,blocks=read_document(text, from_fmt)
                body,ctx=render_body(meta,blocks, parse_format_spec(to_fmt)[0].lower(), {})
                if req.get("standalone"):
                    body=apply_standalone(meta,blocks,body,{"variables":{}}, parse_format_spec(to_fmt)[0].lower(), None)
                self.send_response(200); self.send_header("Content-Type","text/plain; charset=utf-8"); self.end_headers(); self.wfile.write(body.encode())
            except Exception as e:
                self.send_response(400); self.end_headers(); self.wfile.write(str(e).encode())
        def do_GET(self):
            self.send_response(200); self.send_header("Content-Type","text/plain"); self.end_headers(); self.wfile.write(b"pandoc server\n")
        def log_message(self,format,*args): pass
    server=HTTPServer(("localhost",port),Handler)
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    return 0

