def run_lua(args):
    # Minimal lua interpreter invocation: support -e stat, -v, script file with args, -i interactive (read stdin lines evaluate?)
    # Use MiniLua if available else basic handling for print statements
    if "-v" in args:
        sys.stdout.write("Lua 5.4.6  Copyright (C) 1994-2022 Lua.org, PUC-Rio\n"); return 0
    # collect -e
    code_parts=[]; script=None; script_args=[]
    i=0
    interactive=False
    while i<len(args):
        a=args[i]
        if a=="-e" and i+1<len(args): code_parts.append(args[i+1]); i+=2; continue
        if a=="-i": interactive=True; i+=1; continue
        if a=="-l" and i+1<len(args): i+=2; continue
        if a in ("-E","-W"): i+=1; continue
        if a.startswith("-") and a not in ("-","--"):
            # unknown option: pandoc lua error format
            eprint(f"{prog_name()}: user error (unrecognized option `{a}'\nUsage: pandoc lua [options] [script [args]]\n  -e stat    execute string 'stat'\n  -i         interactive mode\n  -l mod     require library 'mod' into global 'mod';\n             if 'mod' has the pattern 'g=module', then\n             require library 'module' into global 'g'\n  -v         show version information\n  -E         ignore environment variables -- partially supported\n  -W         turn warnings on -- currently not supported\n)\n")
            return 1
        else:
            script=a; script_args=args[i+1:]; break
    # Set globals PANDOC_VERSION etc in mini lua
    try:
        lua=MiniLuaInterpreter()
        for code in code_parts:
            lua.execute(code)
        if script and script!="-":
            if not os.path.exists(script):
                eprint(f"{prog_name()}: cannot open {script}: No such file or directory\n"); return 1
            lua.execute(open(script).read())
        elif script=="-":
            lua.execute(sys.stdin.read())
        if interactive:
            # read lines and execute each
            for line in sys.stdin:
                try: lua.execute(line)
                except Exception as e: eprint(str(e)+"\n")
        elif not code_parts and not script:
            # no script and not interactive: read stdin as script? Standalone lua without args enters interactive if tty else executes stdin?
            if not sys.stdin.isatty():
                data=sys.stdin.read()
                if data.strip(): lua.execute(data)
    except Exception as e:
        eprint(str(e)+"\n"); return 1
    return 0

