            else: parts.append(".QS"); parts.append(".LP"); parts.append("\n".join(inner_parts)); parts.append(".QE")
        elif t=="CodeBlock":
            code=c[1]; lang=c[0][1][0] if c[0][1] else ""
            if fmt=="man":
                parts.append(".IP"); parts.append(".EX"); parts.append(code); parts.append(".EE")
