                    for line in code.split("\n"):
                        toks=[]
                        for cls,tx in tokens_for_line(line, canon or lang):
                            macro=latex_token_map.get(cls,"NormalTok") if cls else "NormalTok"
                            toks.append(f'\\*[{macro} "{tx}"]')
                        parts.append("".join(toks))
                else: parts.append(code)
                parts.append("\\f[]"); parts.append(".fi")
        elif t=="Table":
            parts.append(roff_table(b,ctx,fmt))
        elif t=="HorizontalRule":
            parts.append(".LP" if fmt=="ms" else ".PP")
