# ---------------- Minimal Lua interpreter ----------------
class LuaError(Exception): pass
class LuaReturn(Exception):
    def __init__(self,value=None): self.value=value
class LuaBreak(Exception): pass

class LuaTable:
    def __init__(self):
        self.arr=[]  # index starting 1 stored 0
        self.map={}
        self.metatable=None
    def get(self,key):
        if isinstance(key,float) and key.is_integer(): key=int(key)
        if isinstance(key,int) and not isinstance(key,bool):
            if 1<=key<=len(self.arr): return self.arr[key-1]
            return self.map.get(key)
        return self.map.get(key)
    def set(self,key,value):
        if isinstance(key,float) and key.is_integer(): key=int(key)
        if isinstance(key,int) and not isinstance(key,bool):
            if key==len(self.arr)+1 and value is not None:
                self.arr.append(value); return
            if 1<=key<=len(self.arr):
                if value is None:
                    self.arr[key-1]=None
                else: self.arr[key-1]=value
                return
        if value is None:
            self.map.pop(key,None)
        else:
            self.map[key]=value
    def keys(self):
        ks=[]
        for i,v in enumerate(self.arr, start=1):
            if v is not None: ks.append(i)
        for k in self.map.keys(): ks.append(k)
        return ks
    def __repr__(self):
        return f"table: {id(self):x}"

class LuaFunction:
    def __init__(self, params, body, env, vararg=False, name=None):
        self.params=params; self.body=body; self.env=env; self.vararg=vararg; self.name=name
    def __call__(self, *args):
        return call_lua_function(self, list(args))
class LuaBuiltin:
    def __init__(self, func, name="builtin"):
        self.func=func; self.name=name
    def __call__(self, *args):
        return self.func(list(args))

def lua_truthy(v):
    return not (v is None or v is False)
def lua_type(v):
    if v is None: return "nil"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,(int,float)): return "number"
    if isinstance(v,str): return "string"
    if isinstance(v,LuaTable): return "table"
    if isinstance(v,(LuaFunction,LuaBuiltin)): return "function"
    return "userdata"
def lua_tostring(v):
    if v is None: return "nil"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,float):
        if v.is_integer(): return str(int(v))
        return repr(v)
    if isinstance(v,LuaTable):
        # if has __tostring in metatable ignore
        return f"table: {id(v):012x}"
    if isinstance(v,(LuaFunction,LuaBuiltin)): return f"function: {id(v):012x}"
    return str(v)
def lua_tonumber(v):
    if isinstance(v,(int,float)) and not isinstance(v,bool): return v
    if isinstance(v,str):
        try:
            if re.match(r'^-?\d+$', v.strip()): return int(v.strip())
            return float(v.strip())
        except: return None
    return None
def lua_concat(a,b):
    return lua_tostring(a)+lua_tostring(b)
def lua_equals(a,b):
    if isinstance(a,(int,float)) and isinstance(b,(int,float)) and not isinstance(a,bool) and not isinstance(b,bool): return a==b
    if type(a)!=type(b): 
        # int/float handled, LuaTable identity
        return False
    if isinstance(a,LuaTable): return a is b
    return a==b
def lua_arith(a,b,op):
    x=lua_tonumber(a); y=lua_tonumber(b)
    if x is None or y is None: raise LuaError(f"attempt to perform arithmetic on a {lua_type(a)} value")
    if op=="+": return x+y
    if op=="-": return x-y
    if op=="*": return x*y
    if op=="/": return x/y
    if op=="//": return math.floor(x/y)
    if op=="%": return x % y
    if op=="^": return x**y
    raise LuaError("arith op "+op)

