# ---------------- Minimal Lua interpreter ----------------
class LuaError(Exception): pass
class LuaReturn(Exception):
    def __init__(self,value=None): self.value=value
class LuaBreak(Exception): pass

class LuaTable:
    def __init__(self):
        self.arr=[]  # index starting 1 stored 0
        self.map={}
        self.metatable=None
    def get(self,key):
        if isinstance(key,float) and key.is_integer(): key=int(key)
        if isinstance(key,int) and not isinstance(key,bool):
            if 1<=key<=len(self.arr): return self.arr[key-1]
            return self.map.get(key)
        return self.map.get(key)
    def set(self,key,value):
        if isinstance(key,float) and key.is_integer(): key=int(key)
        if isinstance(key,int) and not isinstance(key,bool):
            if key==len(self.arr)+1 and value is not None:
                self.arr.append(value); return
            if 1<=key<=len(self.arr):
                if value is None:
                    self.arr[key-1]=None
                else: self.arr[key-1]=value
                return
        if value is None:
            self.map.pop(key,None)
        else:
            self.map[key]=value
    def keys(self):
        ks=[]
        for i,v in enumerate(self.arr, start=1):
            if v is not None: ks.append(i)
        for k in self.map.keys(): ks.append(k)
        return ks
    def __repr__(self):
        return f"table: {id(self):x}"

class LuaFunction:
    def __init__(self, params, body, env, vararg=False, name=None):
        self.params=params; self.body=body; self.env=env; self.vararg=vararg; self.name=name
    def __call__(self, *args):
        return call_lua_function(self, list(args))
class LuaBuiltin:
    def __init__(self, func, name="builtin"):
        self.func=func; self.name=name
    def __call__(self, *args):
        return self.func(list(args))

def lua_truthy(v):
    return not (v is None or v is False)
def lua_type(v):
    if v is None: return "nil"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,(int,float)): return "number"
    if isinstance(v,str): return "string"
    if isinstance(v,LuaTable): return "table"
    if isinstance(v,(LuaFunction,LuaBuiltin)): return "function"
    return "userdata"
def lua_tostring(v):
    if v is None: return "nil"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,float):
        if v.is_integer(): return str(int(v))
        return repr(v)
    if isinstance(v,LuaTable):
        # if has __tostring in metatable ignore
        return f"table: {id(v):012x}"
    if isinstance(v,(LuaFunction,LuaBuiltin)): return f"function: {id(v):012x}"
    return str(v)
def lua_tonumber(v):
    if isinstance(v,(int,float)) and not isinstance(v,bool): return v
    if isinstance(v,str):
        try:
            if re.match(r'^-?\d+$', v.strip()): return int(v.strip())
            return float(v.strip())
        except: return None
    return None
def lua_concat(a,b):
    return lua_tostring(a)+lua_tostring(b)
def lua_equals(a,b):
    if isinstance(a,(int,float)) and isinstance(b,(int,float)) and not isinstance(a,bool) and not isinstance(b,bool): return a==b
    if type(a)!=type(b): 
        # int/float handled, LuaTable identity
        return False
    if isinstance(a,LuaTable): return a is b
    return a==b
def lua_arith(a,b,op):
    x=lua_tonumber(a); y=lua_tonumber(b)
    if x is None or y is None: raise LuaError(f"attempt to perform arithmetic on a {lua_type(a)} value")
    if op=="+": return x+y
    if op=="-": return x-y
    if op=="*": return x*y
    if op=="/": return x/y
    if op=="//": return math.floor(x/y)
    if op=="%": return x % y
    if op=="^": return x**y
    raise LuaError("arith op "+op)

# Tokenizer
LuaToken=collections_namedtuple = None
import collections
LuaTok=collections.namedtuple("LuaTok",["kind","value","pos"])
LUA_KEYWORDS={"and","break","do","else","elseif","end","false","for","function","goto","if","in","local","nil","not","or","repeat","return","then","true","until","while"}
def lua_tokenize(src):
    toks=[]; i=0; n=len(src)
    while i<n:
        if src[i].isspace(): i+=1; continue
        if src.startswith("--",i):
            if src.startswith("--[[",i):
                end=src.find("]]",i+4); i=n if end==-1 else end+2; continue
            else:
                end=src.find("\n",i); i=n if end==-1 else end+1; continue
        if src.startswith("[[",i):
            end=src.find("]]",i+2)
            if end==-1: raise LuaError("unfinished long string")
            toks.append(LuaTok("string",src[i+2:end],i)); i=end+2; continue
        if src[i] in "\"'":
            q=src[i]; j=i+1; out=""
            while j<n:
                ch=src[j]
                if ch=="\\":
                    if j+1<n:
                        esc=src[j+1]
                        mp={"n":"\n","t":"\t","r":"\r","\\":"\\",'"':'"',"'":"'", "a":"\a","b":"\b","f":"\f","v":"\v"}
                        if esc in mp: out+=mp[esc]; j+=2
                        elif esc.isdigit():
                            k=j+1; num=""
                            while k<n and src[k].isdigit() and len(num)<3: num+=src[k]; k+=1
                            out+=chr(int(num)); j=k
                        else: out+=esc; j+=2
                    else: j+=1
                elif ch==q:
                    j+=1; break
                else: out+=ch; j+=1
            toks.append(LuaTok("string",out,i)); i=j; continue
        if src[i].isdigit() or (src[i]=="." and i+1<n and src[i+1].isdigit()):
            m=re.match(r'0[xX][0-9a-fA-F]+|\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?', src[i:])
            txt=m.group(0)
            val=int(txt,16) if txt.lower().startswith("0x") else (float(txt) if any(c in txt for c in ".eE") else int(txt))
            toks.append(LuaTok("number",val,i)); i+=len(txt); continue
        if src[i].isalpha() or src[i]=="_":
            m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', src[i:]); word=m.group(0)
            toks.append(LuaTok("keyword" if word in LUA_KEYWORDS else "name", word, i)); i+=len(word); continue
        # operators multi
        for op in ["...","//","==","~=","<=",">=","..","::"]:
            if src.startswith(op,i): toks.append(LuaTok("op",op,i)); i+=len(op); break
        else:
            if src[i] in "+-*%^#<>=(){}[];:,.":
                # '.' handled '..' above, single .
                toks.append(LuaTok("op",src[i],i)); i+=1; continue
            if src[i]=="/": toks.append(LuaTok("op","/",i)); i+=1; continue
            raise LuaError(f"unexpected symbol near '{src[i]}'")
        continue
    toks.append(LuaTok("eof","",n))
    return toks

class LuaParser:
    def __init__(self,toks): self.toks=toks; self.i=0
    def peek(self): return self.toks[self.i]
    def next(self): t=self.toks[self.i]; self.i+=1; return t
    def expect(self,value):
        t=self.next()
        if t.value!=value: raise LuaError(f"expected '{value}' near '{t.value}'")
        return t
    def match(self,value):
        if self.peek().value==value: self.i+=1; return True
        return False
    def parse(self):
        body=self.parse_block()
        if self.peek().kind!="eof": raise LuaError(f"unexpected token {self.peek().value}")
        return body
    def parse_block(self):
        stmts=[]
        while self.peek().value not in ("end","else","elseif","until") and self.peek().kind!="eof":
            if self.match(";"): continue
            stmts.append(self.parse_stmt())
        return stmts
    def parse_stmt(self):
        v=self.peek().value
        if v=="local":
            self.next()
            if self.peek().value=="function":
                self.next(); name=self.next().value; func=self.parse_func_body()
                return ("localfunc",name,func)
            names=[]
            while True:
                names.append(self.next().value)
                if not self.match(","): break
            exprs=[]
            if self.match("="): exprs=self.parse_expr_list()
            return ("local",names,exprs)
        if v=="function":
            self.next()
            # name may be a.b.c or a:m
            target=self.parse_primary_prefix_only()
            is_method=False
            func=self.parse_func_body(is_method=("method_pending",))
            # parse_func_body needs know method colon - we handle differently below if colon was consumed in prefix
            return ("funcdef",target,func)
        if v=="return":
            self.next(); exprs=[]
            if self.peek().value not in ("end","else","elseif","until",";") and self.peek().kind!="eof":
                exprs=self.parse_expr_list()
            self.match(";")
            return ("return",exprs)
        if v=="if":
            self.next(); cond=self.parse_expr(); self.expect("then"); body=self.parse_block(); branches=[(cond,body)]
            else_body=None
            while self.peek().value=="elseif":
                self.next(); c=self.parse_expr(); self.expect("then"); branches.append((c,self.parse_block()))
            if self.peek().value=="else":
                self.next(); else_body=self.parse_block()
            self.expect("end"); return ("if",branches,else_body)
        if v=="while":
            self.next(); cond=self.parse_expr(); self.expect("do"); body=self.parse_block(); self.expect("end"); return ("while",cond,body)
        if v=="do":
            self.next(); body=self.parse_block(); self.expect("end"); return ("do",body)
        if v=="for":
            self.next()
            first_name=self.next().value
            if self.match("="):
                start=self.parse_expr(); self.expect(","); stop=self.parse_expr(); step=None
                if self.match(","): step=self.parse_expr()
                self.expect("do"); body=self.parse_block(); self.expect("end"); return ("fornum",first_name,start,stop,step,body)
            else:
                names=[first_name]
                while self.match(","): names.append(self.next().value)
                self.expect("in"); exprs=self.parse_expr_list(); self.expect("do"); body=self.parse_block(); self.expect("end"); return ("forin",names,exprs,body)
        if v=="repeat":
            self.next(); body=self.parse_block(); self.expect("until"); cond=self.parse_expr(); return ("repeat",body,cond)
        if v=="break":
            self.next(); return ("break",)
        if v=="goto":
            self.next(); self.next(); return ("nop",)
        if self.match("::"):
            # label ::name::
            self.next(); self.expect("::"); return ("nop",)
        # expression statement: assignment or call
        expr=self.parse_expr()
        if self.peek().value in ("=",","):
            targets=[expr]
            while self.match(","):
                targets.append(self.parse_expr())
            self.expect("="); values=self.parse_expr_list(); return ("assign",targets,values)
        return ("exprstmt",expr)
    def parse_primary_prefix_only(self):
        # parse a name with . / : suffixes for function def target
        t=self.next(); node=("name",t.value)
        is_method=False
        while True:
            if self.match("."):
                field=self.next().value; node=("index",node,("str",field))
            elif self.match(":"):
                field=self.next().value; node=("index",node,("str",field)); is_method=True; node=("methoddef",node)
            else: break
        return node
    def parse_func_body(self, is_method=None):
        self.expect("("); params=[]; vararg=False
        if not self.match(")"):
            while True:
                if self.peek().value=="...": self.next(); vararg=True; break
                params.append(self.next().value)
                if self.match(","):
                    if self.peek().value=="...": self.next(); vararg=True; break
                    continue
                break
            self.expect(")")
        body=self.parse_block(); self.expect("end"); return (params,body,vararg)
    def parse_expr_list(self):
        exprs=[self.parse_expr()]
        while self.match(","): exprs.append(self.parse_expr())
        return exprs
    # expression parser precedence
    def parse_expr(self): return self.parse_or()
    def parse_or(self):
        node=self.parse_and()
        while self.peek().value=="or": self.next(); node=("binop","or",node,self.parse_and())
        return node
    def parse_and(self):
        node=self.parse_compare()
        while self.peek().value=="and": self.next(); node=("binop","and",node,self.parse_compare())
        return node
    def parse_compare(self):
        node=self.parse_concat()
        while self.peek().value in ("==","~=","<",">","<=",">="):
            op=self.next().value; node=("binop",op,node,self.parse_concat())
        return node
    def parse_concat(self):
        node=self.parse_addsub()
        if self.peek().value=="..": self.next(); node=("binop","..",node,self.parse_concat())
        return node
    def parse_addsub(self):
        node=self.parse_muldiv()
        while self.peek().value in ("+","-"):
            op=self.next().value; node=("binop",op,node,self.parse_muldiv())
        return node
    def parse_muldiv(self):
        node=self.parse_unary()
        while self.peek().value in ("*","/","//","%"):
            op=self.next().value; node=("binop",op,node,self.parse_unary())
        return node
    def parse_unary(self):
        if self.peek().value in ("not","-","#"):
            op=self.next().value; return ("unary",op,self.parse_unary())
        return self.parse_pow()
    def parse_pow(self):
        node=self.parse_atom()
        if self.peek().value=="^": self.next(); node=("binop","^",node,self.parse_unary())
        return node
    def parse_atom(self):
        t=self.peek()
        if t.value=="nil": self.next(); return ("nil",)
        if t.value=="true": self.next(); return ("bool",True)
        if t.value=="false": self.next(); return ("bool",False)
        if t.kind=="number": self.next(); return ("num",t.value)
        if t.kind=="string": self.next(); return ("str",t.value)
        if t.value=="...": self.next(); return ("vararg",)
        if t.value=="function":
            self.next(); params,body,vararg=self.parse_func_body(); return ("func",(params,body,vararg))
        if t.value=="{":
            return self.parse_table()
        if t.value=="(":
            self.next(); node=self.parse_expr(); self.expect(")"); node=("paren",node)
            return self.parse_suffixes(node)
        if t.kind=="name":
            self.next(); node=("name",t.value); return self.parse_suffixes(node)
        raise LuaError(f"unexpected token {t.value} in expression")
    def parse_suffixes(self,node):
        while True:
            if self.peek().value==".":
                self.next(); field=self.next().value; node=("index",node,("str",field)); continue
            if self.peek().value=="[":
                self.next(); key=self.parse_expr(); self.expect("]"); node=("index",node,key); continue
            if self.peek().value==":":
                self.next(); field=self.next().value
                args=self.parse_call_args(); node=("methodcall",node,field,args); continue
            if self.peek().value in ("(","{") or self.peek().kind=="string":
                args=self.parse_call_args(); node=("call",node,args); continue
            break
        return node
    def parse_call_args(self):
        if self.peek().kind=="string":
            return [("str",self.next().value)]
        if self.peek().value=="{":
            return [self.parse_table()]
        self.expect("("); args=[]
        if not self.match(")"):
            args=self.parse_expr_list(); self.expect(")")
        return args
    def parse_table(self):
        self.expect("{"); fields=[]
        while self.peek().value!="}":
            if self.peek().value=="[":
                self.next(); key=self.parse_expr(); self.expect("]"); self.expect("="); val=self.parse_expr(); fields.append(("kv",key,val))
            elif self.peek().kind=="name" and self.toks[self.i+1].value=="=":
                key=self.next().value; self.expect("="); val=self.parse_expr(); fields.append(("named",key,val))
            else:
                val=self.parse_expr(); fields.append(("pos",val))
            if not (self.match(",") or self.match(";")): break
        self.expect("}"); return ("table",fields)

class LuaEnv:
    def __init__(self, parent=None):
        self.vars={}; self.parent=parent
    def lookup(self,name):
        env=self
        while env:
            if name in env.vars: return env.vars[name]
            env=env.parent
        return None
    def lookup_env(self,name):
        env=self
        while env:
            if name in env.vars: return env
            env=env.parent
        return None
    def set(self,name,value):
        env=self.lookup_env(name)
        if env: env.vars[name]=value
        else:
            # set global (root)
            root=self
            while root.parent: root=root.parent
            root.vars[name]=value
    def define(self,name,value): self.vars[name]=value

def call_lua_function(func, args):
    # func env is list? We stored env as LuaEnv captured
    local_env=LuaEnv(parent=func.env)
    varargs=[]
    for idx,param in enumerate(func.params):
        local_env.define(param, args[idx] if idx<len(args) else None)
    if func.vararg:
        varargs=args[len(func.params):]
        local_env.define("...", varargs)  # internal special
    else:
        local_env.define("...", [])
    # store arg table (for script main)
    try:
        execute_block(func.body, local_env)
    except LuaReturn as r:
        return r.value
    return None

def execute_block(stmts, env):
    result=None
    for st in stmts:
        result=execute_stmt(st, env)
    return result

def execute_stmt(st, env):
    kind=st[0]
    if kind=="nop": return None
    if kind=="local":
        names,exprs=st[1],st[2]
        vals=eval_expr_list(exprs,env) if exprs else []
        for i,name in enumerate(names): env.define(name, vals[i] if i<len(vals) else None)
        return None
    if kind=="localfunc":
        name, (params,body,vararg)=st[1],st[2]
        fn=LuaFunction(params,body,env,vararg,name); env.define(name,fn); return None
    if kind=="funcdef":
        target, (params,body,vararg)=st[1],st[2]
        # method def marker
        is_method=False
