                self.next(); key=self.parse_expr(); self.expect("]"); self.expect("="); val=self.parse_expr(); fields.append(("kv",key,val))
            elif self.peek().kind=="name" and self.toks[self.i+1].value=="=":
                key=self.next().value; self.expect("="); val=self.parse_expr(); fields.append(("named",key,val))
            else:
                val=self.parse_expr(); fields.append(("pos",val))
            if not (self.match(",") or self.match(";")): break
        self.expect("}"); return ("table",fields)

class LuaEnv:
    def __init__(self, parent=None):
        self.vars={}; self.parent=parent
    def lookup(self,name):
        env=self
        while env:
            if name in env.vars: return env.vars[name]
            env=env.parent
        return None
    def lookup_env(self,name):
        env=self
        while env:
            if name in env.vars: return env
            env=env.parent
        return None
    def set(self,name,value):
        env=self.lookup_env(name)
        if env: env.vars[name]=value
        else:
            # set global (root)
            root=self
            while root.parent: root=root.parent
            root.vars[name]=value
    def define(self,name,value): self.vars[name]=value

def call_lua_function(func, args):
    # func env is list? We stored env as LuaEnv captured
    local_env=LuaEnv(parent=func.env)
    varargs=[]
    for idx,param in enumerate(func.params):
        local_env.define(param, args[idx] if idx<len(args) else None)
    if func.vararg:
        varargs=args[len(func.params):]
        local_env.define("...", varargs)  # internal special
    else:
        local_env.define("...", [])
    # store arg table (for script main)
    try:
        execute_block(func.body, local_env)
    except LuaReturn as r:
        return r.value
    return None

def execute_block(stmts, env):
    result=None
    for st in stmts:
        result=execute_stmt(st, env)
    return result

def execute_stmt(st, env):
    kind=st[0]
    if kind=="nop": return None
    if kind=="local":
        names,exprs=st[1],st[2]
        vals=eval_expr_list(exprs,env) if exprs else []
        for i,name in enumerate(names): env.define(name, vals[i] if i<len(vals) else None)
        return None
    if kind=="localfunc":
        name, (params,body,vararg)=st[1],st[2]
        fn=LuaFunction(params,body,env,vararg,name); env.define(name,fn); return None
    if kind=="funcdef":
        target, (params,body,vararg)=st[1],st[2]
        # method def marker
        is_method=False
        if target[0]=="methoddef": is_method=True; target=target[1]; params=["self"]+params
        fn=LuaFunction(params,body,env,vararg)
        assign_target(target,fn,env); return None
    if kind=="assign":
        targets,exprs=st[1],st[2]; vals=eval_expr_list(exprs,env)
        for i,tg in enumerate(targets): assign_target(tg, vals[i] if i<len(vals) else None, env)
        return None
    if kind=="exprstmt":
        return eval_expr(st[1],env)
    if kind=="return":
        exprs=st[1]
        if not exprs: raise LuaReturn(None)
        vals=eval_expr_list(exprs,env)
        raise LuaReturn(vals[0] if len(vals)==1 else make_lua_multi(vals))
    if kind=="if":
        for cond,body in st[1]:
            if lua_truthy(eval_expr(cond,env)): execute_block(body, LuaEnv(parent=env)); return None
        if st[2] is not None: execute_block(st[2], LuaEnv(parent=env))
        return None
    if kind=="while":
        while lua_truthy(eval_expr(st[1],env)):
            try: execute_block(st[2], LuaEnv(parent=env))
            except LuaBreak: break
        return None
    if kind=="do": execute_block(st[1], LuaEnv(parent=env)); return None
    if kind=="repeat":
        while True:
            execute_block(st[1], LuaEnv(parent=env))
            if lua_truthy(eval_expr(st[2],env)): break
        return None
    if kind=="break": raise LuaBreak()
    if kind=="fornum":
        _,name,start_e,stop_e,step_e,body=st
        start=lua_tonumber(eval_expr(start_e,env)); stop=lua_tonumber(eval_expr(stop_e,env)); step=lua_tonumber(eval_expr(step_e,env)) if step_e else 1
        i_val=start
        while (step>0 and i_val<=stop) or (step<0 and i_val>=stop):
            child=LuaEnv(parent=env); child.define(name,i_val)
            try: execute_block(body,child)
            except LuaBreak: break
            i_val+=step
        return None
    if kind=="forin":
        _,names,exprs,body=st
        vals=eval_expr_list(exprs,env)
        # Special pairs/ipairs handling: vals may be iterator markers
        iterator=vals[0] if vals else None
        items=[]
        if isinstance(iterator, LuaTable) and getattr(iterator,"_iterator_items",None) is not None:
            items=iterator._iterator_items
        elif isinstance(iterator, LuaTable):
            # generic table iterate pairs
            items=[(k,iterator.get(k)) for k in iterator.keys()]
        else:
            # function iterator unsupported: try call until nil
            items=[]
        for item in items:
            child=LuaEnv(parent=env)
            if isinstance(item,(list,tuple)):
                for ni,name in enumerate(names): child.define(name, item[ni] if ni<len(item) else None)
            else: child.define(names[0],item)
            try: execute_block(body,child)
            except LuaBreak: break
        return None
    return None

def make_lua_multi(vals):
    # multiple return values packed as table with attribute?
    t=LuaTable(); t.arr=list(vals); t._multi=True; return t

def eval_expr_list(exprs,env):
    vals=[]
    for i,e in enumerate(exprs):
        v=eval_expr(e,env)
        if i==len(exprs)-1 and isinstance(v,LuaTable) and getattr(v,"_multi",False):
            vals.extend(v.arr)
        else: vals.append(v)
    return vals

def assign_target(target,value,env):
    if target[0]=="name": env.set(target[1],value); return
    if target[0]=="paren": assign_target(target[1],value,env); return
    if target[0]=="index":
        obj=eval_expr(target[1],env); key=eval_expr(target[2],env)
        if isinstance(obj,LuaTable): obj.set(key,value); return
        raise LuaError("attempt to index a non-table value")
    raise LuaError("invalid assignment target")

def eval_expr(node,env):
    kind=node[0]
    if kind=="nil": return None
    if kind=="bool": return node[1]
    if kind=="num": return node[1]
    if kind=="str": return node[1]
    if kind=="vararg": return env.lookup("...")[0] if env.lookup("...") else None
    if kind=="name": return env.lookup(node[1])
    if kind=="paren": return eval_expr(node[1],env)
    if kind=="func":
        params,body,vararg=node[1]; return LuaFunction(params,body,env,vararg)
    if kind=="table":
        tbl=LuaTable(); pos=1
        for field in node[1]:
            if field[0]=="pos":
                v=eval_expr(field[1],env)
                if isinstance(v,LuaTable) and getattr(v,"_multi",False):
                    for item in v.arr: tbl.set(pos,item); pos+=1
                else: tbl.set(pos,v); pos+=1
            elif field[0]=="named": tbl.set(field[1], eval_expr(field[2],env))
            elif field[0]=="kv": tbl.set(eval_expr(field[1],env), eval_expr(field[2],env))
        return tbl
    if kind=="index":
        obj=eval_expr(node[1],env); key=eval_expr(node[2],env)
        if obj is None: raise LuaError("attempt to index a nil value")
        if isinstance(obj,LuaTable): return obj.get(key)
        if isinstance(obj,str):
            # string library via str.method?
            strlib=env.lookup("string")
            if isinstance(strlib,LuaTable): return strlib.get(key)
            return None
        raise LuaError(f"attempt to index a {lua_type(obj)} value")
    if kind=="call":
        fn=eval_expr(node[1],env); args=eval_expr_list(node[2],env)
        return call_value(fn,args,env)
    if kind=="methodcall":
        obj=eval_expr(node[1],env); field=node[2]; args=eval_expr_list(node[3],env)
        if isinstance(obj,LuaTable): fn=obj.get(field)
        elif isinstance(obj,str):
            strlib=env.lookup("string"); fn=strlib.get(field) if isinstance(strlib,LuaTable) else None
        else: fn=None
        return call_value(fn,[obj]+args,env)
    if kind=="unary":
        op=node[1]; v=eval_expr(node[2],env)
        if op=="not": return not lua_truthy(v)
        if op=="-": return -lua_tonumber(v)
        if op=="#":
            if isinstance(v,LuaTable): return len(v.arr)
            if isinstance(v,str): return len(v)
            raise LuaError("attempt to get length")
    if kind=="binop":
        op=node[1]
        if op=="and":
            a=eval_expr(node[2],env); return eval_expr(node[3],env) if lua_truthy(a) else a
        if op=="or":
            a=eval_expr(node[2],env); return a if lua_truthy(a) else eval_expr(node[3],env)
        a=eval_expr(node[2],env); b=eval_expr(node[3],env)
        if op=="..": return lua_concat(a,b)
        if op in ("+","-","*","/","//","%","^"): return lua_arith(a,b,op)
        if op=="==": return lua_equals(a,b)
        if op=="~=": return not lua_equals(a,b)
        if op in ("<",">","<=",">="):
            # strings compare lex, numbers numeric
            if isinstance(a,str) and isinstance(b,str): x,y=a,b
            else: x,y=lua_tonumber(a),lua_tonumber(b)
            if op=="<": return x<y
            if op==">": return x>y
            if op=="<=": return x<=y
            if op==">=": return x>=y
    raise LuaError(f"cannot evaluate {kind}")

def call_value(fn,args,env=None):
    if isinstance(fn,LuaFunction): return fn(*args)
    if isinstance(fn,LuaBuiltin): return fn.func(args)
    if callable(fn): 
        # python function expecting list?
        try: return fn(args)
        except TypeError: return fn(*args)
    raise LuaError(f"attempt to call a {lua_type(fn)} value")

