class MiniLuaInterpreter:
    def __init__(self, output_write=None):
        self.env=create_lua_globals(output_write=output_write)
        self.setup_pandoc_module()
        self._output=[]
    def setup_pandoc_module(self, doc_context=None):
        pandoc=make_pandoc_lua_table(self)
        self.env.define("pandoc", pandoc)
    def execute(self, code):
        toks=lua_tokenize(code)
        parser=LuaParser(toks)
        body=parser.parse()
        try:
            execute_block(body, self.env)
        except LuaReturn as r:
            return r.value
        return None
    def call_global(self,name,args):
        fn=self.env.lookup(name)
        if fn: return call_value(fn,args,self.env)
        return None

def make_lua_multi_return_table(vals):
    return make_lua_multi(vals)

