def lua_attr_from_ast(attr):
    t=LuaTable()
    t.set("identifier", attr[0] if attr else "")
    t.set("classes", make_lua_table_from_list(list(attr[1]) if attr else []))
    amap=LuaTable()
    for k,v in (attr[2] if attr else []): amap.set(k,v)
    t.set("attributes", amap)
    t.arr=[attr[0] if attr else "", t.get("classes"), amap]
    return t
