    if attr_tbl is None: return clone_attr(EMPTY_ATTR)
    if isinstance(attr_tbl, LuaTable):
        # hidden ast?
        if getattr(attr_tbl,"_ast_attr",None) is not None: return clone_attr(attr_tbl._ast_attr)
        ident=attr_tbl.get("identifier") or ""
        classes=lua_table_to_list(attr_tbl.get("classes")) if isinstance(attr_tbl.get("classes"),LuaTable) else []
        attrs_tbl=attr_tbl.get("attributes"); kvs=[]
        if isinstance(attrs_tbl,LuaTable):
            for k in attrs_tbl.keys(): kvs.append([str(k), lua_tostring(attrs_tbl.get(k))])
        return [ident, [str(x) for x in classes], kvs]
    return clone_attr(EMPTY_ATTR)

