            # We'll construct AST-ish fields then normalize using lua_element -> ast conversion by setting fields directly heuristics.
            if block_type in ("Para","Plain","BlockQuote","Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline","Note"):
