def lua_list_of_elements(tbl):
    if tbl is None: return []
    if isinstance(tbl, LuaTable):
        if tbl.get("t"): return [tbl]
        return list(tbl.arr)
    if isinstance(tbl, list): return tbl
    return [tbl]

def lua_content_to_ast_inlines(content):
    if content is None: return []
    if isinstance(content,str):
        return [I("Str",content)] if content else []
    elems=lua_list_of_elements(content)
    out=[]
    for e in elems:
        node=ast_from_lua_element(e)
        if isinstance(node,dict) and "t" in node: out.append(node)
        elif isinstance(e,str): out.append(I("Str",e))
    return out
def lua_content_to_ast_blocks(content):
    if content is None: return []
    if isinstance(content,str):
        return [B("Para", lua_content_to_ast_inlines(content))]
    elems=lua_list_of_elements(content)
    out=[]
    for e in elems:
        node=ast_from_lua_element(e)
        if isinstance(node,dict): out.append(node)
        elif isinstance(e,str): out.append(B("Para",[I("Str",e)]))
    return out

def ast_from_lua_element(tbl):
    if tbl is None: return None
    if isinstance(tbl,str): return I("Str",tbl)
    if not isinstance(tbl,LuaTable):
        return getattr(tbl,"_ast",None)
    t=tbl.get("t") or tbl.get("tag")
    if not t:
        # a list table -> return list marker handled by callers
        return None
    # If this table is an unmodified original and fields indicate same, constructors still reconstruct; for complex types fallback to _ast if type in complex
    if t=="Para": return B("Para", lua_content_to_ast_inlines(tbl.get("content")))
    if t=="Plain": return B("Plain", lua_content_to_ast_inlines(tbl.get("content")))
    if t=="Header": return B("Header",[int(lua_tonumber(tbl.get("level")) or 1), ast_attr_from_lua(tbl.get("attr")), lua_content_to_ast_inlines(tbl.get("content"))])
    if t=="CodeBlock": return B("CodeBlock",[ast_attr_from_lua(tbl.get("attr")), tbl.get("text") or ""])
    if t=="RawBlock": return B("RawBlock",[tbl.get("format") or "", tbl.get("text") or ""])
    if t=="BlockQuote": return B("BlockQuote", lua_content_to_ast_blocks(tbl.get("content")))
    if t=="BulletList":
        items=[]
        for item_tbl in lua_list_of_elements(tbl.get("content")): items.append(lua_content_to_ast_blocks(item_tbl))
        return B("BulletList", items)
    if t=="OrderedList":
        items=[]
        for item_tbl in lua_list_of_elements(tbl.get("content")): items.append(lua_content_to_ast_blocks(item_tbl))
        la=tbl.get("listAttributes") or tbl.get("attr")
        start=1; style="Decimal"; delim="Period"
        if isinstance(la,LuaTable):
            start=int(lua_tonumber(la.get("start")) or 1); style=la.get("style") or style; delim=la.get("delimiter") or la.get("delim") or delim
        return B("OrderedList", [[start,style,delim], items])
    if t=="DefinitionList":
        entries=[]
        for entry in lua_list_of_elements(tbl.get("content")):
            pair=lua_list_of_elements(entry)
            if len(pair)>=2: entries.append((lua_content_to_ast_inlines(pair[0]), [lua_content_to_ast_blocks(d) for d in lua_list_of_elements(pair[1])]))
        return B("DefinitionList", entries)
    if t=="LineBlock": return B("LineBlock", [lua_content_to_ast_inlines(line) for line in lua_list_of_elements(tbl.get("content"))])
    if t=="Div": return B("Div",[ast_attr_from_lua(tbl.get("attr")), lua_content_to_ast_blocks(tbl.get("content"))])
    if t=="Figure":
        cap=[None, []]
        return B("Figure",[ast_attr_from_lua(tbl.get("attr")), cap, lua_content_to_ast_blocks(tbl.get("content"))])
    if t in ("Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline"): return I(t, lua_content_to_ast_inlines(tbl.get("content")))
    if t=="Quoted": return I("Quoted",[tbl.get("quoteType") or tbl.get("quotetype") or "DoubleQuote", lua_content_to_ast_inlines(tbl.get("content"))])
    if t=="Code": return I("Code",[ast_attr_from_lua(tbl.get("attr")), tbl.get("text") or ""])
    if t=="Math": return I("Math",[tbl.get("mathType") or tbl.get("mathtype") or "InlineMath", tbl.get("text") or ""])
    if t=="RawInline": return I("RawInline",[tbl.get("format") or "", tbl.get("text") or ""])
    if t=="Link": return I("Link",[ast_attr_from_lua(tbl.get("attr")), lua_content_to_ast_inlines(tbl.get("content")), [tbl.get("target") or "", tbl.get("title") or ""]])
    if t=="Image": return I("Image",[ast_attr_from_lua(tbl.get("attr")), lua_content_to_ast_inlines(tbl.get("content") or tbl.get("caption")), [tbl.get("src") or tbl.get("target") or "", tbl.get("title") or ""]])
    if t=="Span": return I("Span",[ast_attr_from_lua(tbl.get("attr")), lua_content_to_ast_inlines(tbl.get("content"))])
    if t=="Note": return I("Note", lua_content_to_ast_blocks(tbl.get("content")))
    if t=="Cite": return I("Cite",[[], lua_content_to_ast_inlines(tbl.get("content"))])
    if t=="Str": return I("Str", tbl.get("text") or "")
    if t in ("Space","SoftBreak","LineBreak"): return I(t)
    if t=="HorizontalRule": return B("HorizontalRule")
    if t=="Null": return B("Null")
    if t=="Table":
        return getattr(tbl,"_ast",None) or B("Para",[])
    # unknown fallback
    return getattr(tbl,"_ast",None)

def make_pandoc_lua_table(interpreter=None):
    pandoc=LuaTable()
    def constructor(block_type, is_block=True):
        def make(args):
            tbl=LuaTable(); tbl.set("t",block_type); tbl.set("tag",block_type)
            # arguments vary by type; implement common patterns by converting via temporary AST logic
            # We'll construct AST-ish fields then normalize using lua_element -> ast conversion by setting fields directly heuristics.
            if block_type in ("Para","Plain","BlockQuote","Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline","Note"):
                tbl.set("content", args[0] if args else LuaTable())
            elif block_type=="Header":
                tbl.set("level", args[0] if len(args)>0 else 1); tbl.set("content", args[1] if len(args)>1 else LuaTable())
                if len(args)>2: tbl.set("attr", args[2])
                else: tbl.set("attr", lua_attr_from_ast(clone_attr(EMPTY_ATTR)))
            elif block_type in ("CodeBlock","Code"):
                # Code(text, attr)
                tbl.set("text", lua_tostring(args[0]) if args else ""); tbl.set("attr", args[1] if len(args)>1 else lua_attr_from_ast(clone_attr(EMPTY_ATTR)))
            elif block_type=="Str":
                tbl.set("text", lua_tostring(args[0]) if args else "")
            elif block_type in ("Space","SoftBreak","LineBreak","HorizontalRule","Null"):
                pass
            elif block_type in ("Link","Image"):
                tbl.set("content", args[0] if len(args)>0 else LuaTable()); tbl.set("target", lua_tostring(args[1]) if len(args)>1 else ""); tbl.set("src", tbl.get("target")); tbl.set("title", lua_tostring(args[2]) if len(args)>2 else ""); tbl.set("attr", args[3] if len(args)>3 else lua_attr_from_ast(clone_attr(EMPTY_ATTR)))
                if block_type=="Image": tbl.set("caption", tbl.get("content"))
            elif block_type=="Span":
                tbl.set("content", args[0] if args else LuaTable()); tbl.set("attr", args[1] if len(args)>1 else lua_attr_from_ast(clone_attr(EMPTY_ATTR)))
            elif block_type=="Div":
                tbl.set("content", args[0] if args else LuaTable()); tbl.set("attr", args[1] if len(args)>1 else lua_attr_from_ast(clone_attr(EMPTY_ATTR)))
            elif block_type in ("BulletList",):
                tbl.set("content", args[0] if args else LuaTable())
            elif block_type=="OrderedList":
                tbl.set("content", args[0] if args else LuaTable())
                if len(args)>1: tbl.set("listAttributes", args[1])
            elif block_type=="Math":
                tbl.set("mathType", lua_tostring(args[0]) if args else "InlineMath"); tbl.set("mathtype", tbl.get("mathType")); tbl.set("text", lua_tostring(args[1]) if len(args)>1 else "")
            elif block_type=="Quoted":
                tbl.set("quoteType", lua_tostring(args[0]) if args else "DoubleQuote"); tbl.set("content", args[1] if len(args)>1 else LuaTable())
            elif block_type=="RawInline" or block_type=="RawBlock":
                tbl.set("format", lua_tostring(args[0]) if args else ""); tbl.set("text", lua_tostring(args[1]) if len(args)>1 else "")
            else:
                if args: tbl.set("content", args[0])
            return tbl
        return LuaBuiltin(make)
    block_types=["Para","Plain","Header","CodeBlock","BlockQuote","BulletList","OrderedList","DefinitionList","LineBlock","Div","Figure","HorizontalRule","Null","RawBlock"]
    inline_types=["Str","Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline","Quoted","Code","Space","SoftBreak","LineBreak","Math","RawInline","Link","Image","Span","Note","Cite"]
    for bt in block_types+inline_types:
        pandoc.set(bt, constructor(bt))
    # Attr
    def make_attr(args):
        ident=lua_tostring(args[0]) if len(args)>0 and args[0] is not None else ""
        classes=args[1] if len(args)>1 else LuaTable()
        attrs=args[2] if len(args)>2 else LuaTable()
        # classes may be list of strings
        if isinstance(classes, LuaTable): class_list=[lua_tostring(x) for x in classes.arr]
        elif isinstance(classes,list): class_list=classes
        else: class_list=[]
        kvs=[]
        if isinstance(attrs, LuaTable):
            for k in attrs.keys(): kvs.append([str(k), lua_tostring(attrs.get(k))])
        return lua_attr_from_ast([ident,class_list,kvs])
    pandoc.set("Attr", LuaBuiltin(make_attr))
    # List constructor
    pandoc.set("List", LuaBuiltin(lambda args: args[0] if args and isinstance(args[0],LuaTable) else make_lua_table_from_list(args)))
    pandoc.set("Inlines", LuaBuiltin(lambda args: args[0] if args else LuaTable()))
    pandoc.set("Blocks", LuaBuiltin(lambda args: args[0] if args else LuaTable()))
    # utils
    utils=LuaTable()
    def stringify(args):
        v=args[0] if args else None
        if v is None: return ""
        if isinstance(v,str): return v
        if isinstance(v,LuaTable):
            ast=getattr(v,"_ast",None)
            if ast is not None:
                if isinstance(ast,dict) and ast.get("t") in ("Para","Plain","Header"):
                    return inline_text(ast["c"] if ast["t"]!="Header" else ast["c"][2])
                if isinstance(ast,dict): return block_plain_text([ast]) if ast.get("t") else inline_text(ast.get("c",[]) if isinstance(ast.get("c"),list) else [])
            # list
            if v.arr:
                parts=[]
                for e in v.arr:
                    parts.append(stringify([e]))
                return "".join(parts)
