    utils.set("stringify", LuaBuiltin(stringify))
    utils.set("type", LuaBuiltin(lambda args: (args[0].get("t") if isinstance(args[0],LuaTable) and args[0].get("t") else lua_type(args[0]))))
    utils.set("equals", LuaBuiltin(lambda args: lua_equals(args[0],args[1]) if len(args)>1 else False))
    pandoc.set("utils", utils)
    # read/write/convert
    def pandoc_read(args):
        text=lua_tostring(args[0]) if args else ""; fmt=lua_tostring(args[1]) if len(args)>1 else "markdown"
        meta,blocks=read_document(text, fmt)
        return lua_doc_table(meta,blocks)
    def pandoc_write(args):
        doc=args[0] if args else None; fmt=lua_tostring(args[1]) if len(args)>1 else "html"
        meta,blocks=lua_doc_to_ast(doc) if doc is not None else ({},[])
        body,ctx=render_body(meta,blocks, parse_format_spec(fmt)[0].lower(), {})
        return body+"\n" if body and not body.endswith("\n") else body
    def pandoc_convert(args):
        text=lua_tostring(args[0]) if args else ""; opts=args[1] if len(args)>1 else None
        from_fmt="markdown"; to_fmt="html"
        if isinstance(opts,LuaTable):
            from_fmt=lua_tostring(opts.get("from") or from_fmt); to_fmt=lua_tostring(opts.get("to") or to_fmt)
        meta,blocks=read_document(text, from_fmt)
        body,ctx=render_body(meta,blocks, parse_format_spec(to_fmt)[0].lower(), {})
        return body+"\n" if body and not body.endswith("\n") else body
    pandoc.set("read", LuaBuiltin(pandoc_read)); pandoc.set("write", LuaBuiltin(pandoc_write)); pandoc.set("convert", LuaBuiltin(pandoc_convert))
    # FORMAT global set by interpreter for filters
    return pandoc

def lua_meta_value_from_ast(v):
    if not isinstance(v,dict): return v
    t=v.get("t"); c=v.get("c")
    if t=="MetaString": return c
    if t=="MetaBool": return c
    if t=="MetaInlines": return make_lua_table_from_list([lua_element_from_ast(x) for x in c])
    if t=="MetaBlocks": return make_lua_table_from_list([lua_element_from_ast(x) for x in c])
    if t=="MetaList": return make_lua_table_from_list([lua_meta_value_from_ast(x) for x in c])
    if t=="MetaMap":
        tbl=LuaTable()
        for k,val in c: tbl.set(k, lua_meta_value_from_ast(val))
        return tbl
    return c

def lua_doc_table(meta,blocks):
    doc=LuaTable(); doc._doc_ast=(meta,blocks)
    doc.set("blocks", make_lua_table_from_list([lua_element_from_ast(b) for b in blocks]))
    meta_tbl=LuaTable()
    for k,v in meta.items(): meta_tbl.set(k, lua_meta_value_from_ast(v))
    doc.set("meta", meta_tbl)
    return doc
def lua_doc_to_ast(doc):
    if isinstance(doc,LuaTable) and getattr(doc,"_doc_ast",None) is not None:
        meta,orig_blocks=doc._doc_ast
        # if blocks field changed (different table), reconstruct
        blocks_tbl=doc.get("blocks")
        # Assume if script returned same doc object unmodified, keep original; if blocks table is new, reconstruct
        blocks=[ast_from_lua_element(e) for e in lua_list_of_elements(blocks_tbl)] if blocks_tbl is not None else orig_blocks
        blocks=[b for b in blocks if b is not None]
        return meta,blocks
    if isinstance(doc,LuaTable):
        blocks=[ast_from_lua_element(e) for e in lua_list_of_elements(doc.get("blocks"))]
        return {},[b for b in blocks if b]
    return {},[]

def lua_filter_engine(meta,blocks,script):
    interpreter=MiniLuaInterpreter()
    interpreter.env.define("FORMAT", "html")  # will be overwritten by caller? apply_filters knows to fmt but lua_filter_engine signature lacks fmt
    # pandoc global already setup
    result=None
    try:
        toks=lua_tokenize(script); parser=LuaParser(toks); body=parser.parse()
        try: execute_block(body, interpreter.env)
        except LuaReturn as r: result=r.value
    except LuaError as e:
        raise PandocError(str(e),83)
    # Determine stages
    stages=[]
    stage_from_return=None
    if isinstance(result,LuaTable):
        if result.arr and all(isinstance(x,LuaTable) for x in result.arr):
            stages=result.arr
        elif result.map:
            stages=[result]
    if not stages:
        # global stage if any relevant functions
        global_stage={}
        for name in list(interpreter.env.vars.keys()):
            v=interpreter.env.vars[name]
            if isinstance(v,(LuaFunction,LuaBuiltin)):
                global_stage[name]=v
        # Pandoc/Meta handled specially if present
        relevant=False
        for k in global_stage:
            if k in ("Pandoc","Meta","Block","Blocks","Inline","Inlines") or (len(k)>0 and k[0].isupper()): relevant=True
        if relevant:
            stages=[global_stage]
        else:
            return meta,blocks
    else:
        # convert LuaTable stages to dicts
        converted=[]
        for st in stages:
            if isinstance(st,LuaTable):
                d={}
                for k in st.keys():
                    v=st.get(k)
                    if isinstance(v,(LuaFunction,LuaBuiltin)): d[str(k)]=v
                converted.append(d)
            elif isinstance(st,dict): converted.append(st)
        stages=converted
    # If global stage dict already, keep
    if stages and isinstance(stages[0],dict) and "Pandoc" in stages[0]:
        # handled below still via stage loop
        pass
    new_meta,new_blocks=meta,blocks
    for stage in stages:
        if isinstance(stage,LuaTable):
            d={}
            for k in stage.keys(): d[str(k)]=stage.get(k)
            stage=d
        new_meta,new_blocks=apply_lua_stage(new_meta,new_blocks,stage,interpreter)
    return new_meta,new_blocks

def apply_lua_stage(meta,blocks,stage,interpreter):
    # Pandoc function takes whole doc
    if "Pandoc" in stage:
        doc=lua_doc_table(meta,blocks)
        res=call_value(stage["Pandoc"],[doc],interpreter.env)
        if res is None: return meta,blocks
        return lua_doc_to_ast(res)
    # Meta function
    if "Meta" in stage:
        meta_tbl=LuaTable()
        for k,v in meta.items(): meta_tbl.set(k, lua_meta_value_from_ast(v))
        res=call_value(stage["Meta"],[meta_tbl],interpreter.env)
        if isinstance(res,LuaTable):
            new_meta=dict(meta)
            for k in res.keys():
                v=res.get(k)
                # convert simple values to Meta
                if isinstance(v,str): new_meta[str(k)]=meta_value_from_string(v)
                elif isinstance(v,bool): new_meta[str(k)]={"t":"MetaBool","c":v}
                elif isinstance(v,LuaTable) and v.arr and all(isinstance(x,LuaTable) and x.get("t") for x in v.arr):
                    new_meta[str(k)]={"t":"MetaInlines","c":[ast_from_lua_element(x) for x in v.arr]}
            meta=new_meta
    # Traversal helpers
    def process_inlines(inlines):
        out=[]
        for inl in inlines:
            out.extend(process_inline(inl))
        return out
    def process_inline(inl):
        t=inl.get("t"); c=inl.get("c")
        # children first
        processed=inl
        if t in ("Emph","Strong","Strikeout","Superscript","Subscript","SmallCaps","Underline"):
            processed=I(t, process_inlines(c))
        elif t=="Quoted": processed=I("Quoted",[c[0], process_inlines(c[1])])
        elif t=="Span": processed=I("Span",[c[0], process_inlines(c[1])])
        elif t in ("Link","Image"): processed=I(t,[c[0], process_inlines(c[1]), c[2]])
        elif t=="Note": processed=I("Note", process_blocks(c))
        elif t=="Cite": processed=I("Cite",[c[0], process_inlines(c[1])])
        fn=stage.get(t) or stage.get("Inline")
        if not fn: return [processed]
        res=call_value(fn,[lua_element_from_ast(processed)],interpreter.env)
        return handle_filter_result(res, is_block=False)
    def process_blocks(blist):
        out=[]
        for b in blist: out.extend(process_block(b))
        return out
    def process_block(block):
        t=block.get("t"); c=block.get("c")
        processed=block
        if t in ("Para","Plain"): processed=B(t, process_inlines(c))
        elif t=="Header": processed=B("Header",[c[0],c[1],process_inlines(c[2])])
        elif t=="BlockQuote": processed=B("BlockQuote", process_blocks(c))
        elif t=="Div": processed=B("Div",[c[0], process_blocks(c[1])])
        elif t=="BulletList": processed=B("BulletList",[process_blocks(item) for item in c])
        elif t=="OrderedList": processed=B("OrderedList",[c[0],[process_blocks(item) for item in c[1]]])
        elif t=="DefinitionList":
            processed=B("DefinitionList",[(process_inlines(term),[process_blocks(d) for d in defs]) for term,defs in c])
        elif t=="LineBlock": processed=B("LineBlock",[process_inlines(line) for line in c])
        elif t=="Figure":
            # caption blocks etc keep
            processed=B("Figure",[c[0],c[1],[process_blocks([sub])[0] if process_blocks([sub]) else sub for sub in c[2]]]) if False else B("Figure",[c[0],c[1],process_blocks(c[2])])
        elif t=="Table":
            # process header/row inlines
            new_c=dict(c)
            new_c["header_inlines"]=[process_inlines(x) for x in c.get("header_inlines",[])]
            new_c["row_inlines"]=[[process_inlines(cell) for cell in row] for row in c.get("row_inlines",[])]
            new_c["header"]=[inline_text(x) for x in new_c["header_inlines"]]
            new_c["rows"]=[[inline_text(cell) for cell in row] for row in new_c["row_inlines"]]
            processed={"t":"Table","c":new_c}
        fn=stage.get(t) or stage.get("Block")
        if not fn: return [processed]
        res=call_value(fn,[lua_element_from_ast(processed)],interpreter.env)
        return handle_filter_result(res, is_block=True)
    def handle_filter_result(res, is_block):
        if res is None: 
            # caller needs fallback to processed - but we lost it in this closure design: handled by caller? We return special marker
            return [None]
        if isinstance(res,LuaTable):
            if res.get("t"):
                node=ast_from_lua_element(res); return [node] if node else [None]
            # list
            out=[]
            for e in res.arr:
                node=ast_from_lua_element(e) if isinstance(e,LuaTable) else None
                if node: out.append(node)
                elif isinstance(e,str): out.append(B("Para",[I("Str",e)]) if is_block else I("Str",e))
            return out
        if isinstance(res,str):
            return [B("Para",[I("Str",res)])] if is_block else [I("Str",res)]
        return [None]
    # Wrap process to replace None markers with processed original: we need process functions to retain. Adjust: process_block/inline already returned marker; we post-process at top level? Simpler: modify handle to require processed passed - rewrite by monkey: In process_block, after call we check result
    # Instead reimplement top-level traversal here using process functions but fix None handling: process_* return [None] for unchanged, we need substitute. We'll do a second pass function clean:
    raw_blocks=process_blocks(blocks)
    # Replace None placeholders is impossible (lost original). To avoid bug, we handle: if a filter returns nil, pandoc keeps original - our process functions returned [None], losing. Therefore we need to adjust process functions dynamically: we already executed, so for common case where filter only defines some types, other types had fn None and returned processed before. For types with fn returning None, we lose block - This affects filters that conditionally return nil.
    # Fix approach: Re-run with a wrapper stage where functions are wrapped to return original element if lua returns nil.
    # Detect if any stage function returned nil during traversal by checking raw for None and if so, fall back to using wrapped stage.
    if any(x is None for x in raw_blocks):
        wrapped={}
        for k,fn in stage.items():
            if k in ("Pandoc","Meta"): wrapped[k]=fn
            else:
                def make_wrapper(f):
                    def wrapper(args):
                        r=call_value(f,args,interpreter.env)
                        if r is None: return args[0]
                        return r
                    return LuaBuiltin(wrapper)
                wrapped[k]=make_wrapper(fn)
        return apply_lua_stage_wrapped(meta,blocks,wrapped,interpreter)
    return meta, raw_blocks

def apply_lua_stage_wrapped(meta,blocks,stage,interpreter):
