            if t in ("Para","Plain"): out.append(B(t, transform_inlines(c)))
            elif t=="Header": out.append(B("Header",[c[0],c[1],transform_inlines(c[2])]))
            elif t=="BlockQuote": out.append(B("BlockQuote", transform_blocks(c)))
            elif t=="Div": out.append(B("Div",[c[0], transform_blocks(c[1])]))
            elif t=="BulletList": out.append(B("BulletList",[transform_blocks(item) for item in c]))
            elif t=="OrderedList": out.append(B("OrderedList",[c[0],[transform_blocks(item) for item in c[1]]]))
            elif t=="DefinitionList": out.append(B("DefinitionList",[(transform_inlines(term),[transform_blocks(d) for d in defs]) for term,defs in c]))
            elif t=="LineBlock": out.append(B("LineBlock",[transform_inlines(line) for line in c]))
            else: out.append(b)
        return out
    new_blocks=transform_blocks(blocks)
    if cited:
        def bib_entry_inlines(entry):
            f=entry["fields"]; auth=bib_authors(entry)
            auth_str=""
            if auth:
                formatted=[]
                for idx,(last,first) in enumerate(auth):
                    formatted.append(f"{last}, {first}" if idx==0 and first else (f"{first} {last}" if first else last))
                if len(formatted)==1: auth_str=formatted[0]
                elif len(formatted)==2: auth_str=formatted[0]+", and "+formatted[1]
                else: auth_str=", ".join(formatted[:-1])+", and "+formatted[-1]
            year=f.get("year") or ""
            if not year:
                m=re.search(r'(\d{4})', f.get("date","")); year=m.group(1) if m else ""
            title=re.sub(r'[{}]','',f.get("title","")).strip()
            parts=[]
            intro=f"{auth_str}. {year}. " if auth_str else f"{year}. "
            parts.extend(make_str_inlines(intro))
            if entry["type"] in ("article","article-journal"):
                # "Title." Journal...
                if title:
                    parts.append(I("Quoted",["DoubleQuote", make_str_inlines(title+".")]))
                    parts.append(I("Space"))
                journal=f.get("journal") or f.get("journaltitle") or f.get("container-title") or ""
                if journal:
                    parts.append(I("Emph", make_str_inlines(re.sub(r'[{}]','',journal))))
                vol=f.get("volume",""); issue=f.get("number") or f.get("issue",""); pages=f.get("pages") or f.get("page","")
                tail=""
                if vol: tail+=f" {vol}"
                if issue: tail+=f" ({issue})"
                if pages: tail+=f": {pages.replace('--','–')}"
                tail+="."
                parts.extend(make_str_inlines(tail))
            elif entry["type"] in ("book",):
                if title: parts.append(I("Emph", make_str_inlines(title)))
                publisher=f.get("publisher",""); place=f.get("address") or f.get("location") or ""
                tail=". "
                if place and publisher: tail+=f"{place}: {publisher}."
                elif publisher: tail+=f"{publisher}."
                else: tail=tail.rstrip()
                parts.extend(make_str_inlines(tail))
            else:
                if title: parts.extend(make_str_inlines(title+"."))
                publisher=f.get("publisher","")
                if publisher: parts.extend(make_str_inlines(f" {publisher}."))
            return parts
        sorted_keys=sorted(cited, key=lambda k: (bib_authors(entries[k])[0][0].lower() if bib_authors(entries[k]) else k, entries[k]["fields"].get("year","")))
        entry_divs=[]
        for key in sorted_keys:
            entry_divs.append(B("Div",[[f"ref-{key}",["csl-entry"],[["role","listitem"]]], [B("Para", bib_entry_inlines(entries[key]))]]))
        refs_div=B("Div",[["refs",["references","csl-bib-body","hanging-indent"],[["entry-spacing","0"],["role","list"]]], entry_divs])
        new_blocks.append(refs_div)
    return meta,new_blocks

